(5, 'icinga_endpoint', '__CURRENT_HOST__', 'create', NULL, '{\"apiuser\":\"root\",\"host\":\"__CURRENT_HOST__\",\"log_duration\":86400,\"object_name\":\"__CURRENT_HOST__\",\"object_type\":\"external_object\",\"port\":\"5665\",\"zone\":\"__CURRENT_HOST__\"}', 'yalh', '2026-09-03 00:35:34', 0x405ef7d3e2b8677e3db5a3ffeb3da37839dacf14, 0xc77bbc992058b13ab76f8c35fd002fe16fe913ee),
(6, 'icinga_command', 'ido', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"ido\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:34', 0x9774e81a163a062d6819ac05ff18d6de1df3fc51, 0x405ef7d3e2b8677e3db5a3ffeb3da37839dacf14),
(7, 'icinga_command', 'icingadb', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"icingadb\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"icingadb_database_backlog_critical\":900,\"icingadb_database_backlog_warning\":300,\"icingadb_full_dump_duration_critical\":600,\"icingadb_full_dump_duration_warning\":300,\"icingadb_full_sync_duration_critical\":600,\"icingadb_full_sync_duration_warning\":300,\"icingadb_name\":\"icingadb\",\"icingadb_redis_backlog_critical\":900,\"icingadb_redis_backlog_warning\":300}}', 'yalh', '2026-09-03 00:35:34', 0x0ddf91e664058830bb760dad654dd1bb615496bc, 0x9774e81a163a062d6819ac05ff18d6de1df3fc51),
(8, 'icinga_command', 'running_kernel', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"running_kernel\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:34', 0x41a5ce4b711494ba8cbb4fb79ba00602032cbf42, 0x0ddf91e664058830bb760dad654dd1bb615496bc),
(9, 'icinga_command', 'adaptec-raid', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"Insert the controller number to be checked.\",\"required\":true,\"value\":\"$adaptec_controller_number$\"},\"-p\":{\"description\":\"Insert the path to arcconf (e.g. \\/sbin\\/arcconf).\",\"required\":true,\"value\":\"$arcconf_path$\"}},\"command\":\"check_adaptec_raid\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"adaptec-raid\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"arcconf_path\":\"\\/sbin\\/arcconf\"}}', 'yalh', '2026-09-03 00:35:34', 0x16e507bedcc0e6f68b2b52da09595864292d00fa, 0x41a5ce4b711494ba8cbb4fb79ba00602032cbf42),
(10, 'icinga_command', 'sar-perf', 'create', NULL, '{\"arguments\":{\"sar_perf_disk\":{\"description\":\"Disk name for the \'disk\' profile\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"skip_key\":true,\"value\":\"$sar_perf_disk$\"},\"sar_perf_profile\":{\"description\":\"Define the run profile: pagestat, cpu, memory_util, memory_stat, io_transfer, queueln_load, swap_util, swap_stat, task, kernel, disk <disk>. Can be a string or an array of multiple profiles.\",\"repeat_key\":false,\"required\":true,\"skip_key\":true,\"value\":\"$sar_perf_profile$\"}},\"command\":\"check_sar_perf.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"sar-perf\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:34', 0x8b93a5f6a7ef52338b8e3ee6e23de0d8b169a0ea, 0x16e507bedcc0e6f68b2b52da09595864292d00fa),
(11, 'icinga_command', 'apache-status', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"name or IP address of host to check\",\"value\":\"$apache_status_address$\"},\"-N\":{\"description\":\"do not validate the SSL certificate chain\",\"set_if\":\"$apache_status_no_validate$\"},\"-P\":{\"description\":\"password for basic auth\",\"value\":\"$apache_status_password$\"},\"-R\":{\"description\":\"CRITICAL if socket timed out or http code >= 500\",\"set_if\":\"$apache_status_unreachable$\"},\"-U\":{\"description\":\"username for basic auth\",\"value\":\"$apache_status_username$\"},\"-c\":{\"description\":\"number of open slots, busy workers and idle workers that will cause a CRITICAL\",\"value\":\"$apache_status_critical$\"},\"-p\":{\"description\":\"the http port\",\"value\":\"$apache_status_port$\"},\"-s\":{\"description\":\"Whether we should use HTTPS instead of HTTP\",\"set_if\":\"$apache_status_ssl$\"},\"-t\":{\"description\":\"timeout in seconds\",\"value\":\"$apache_status_timeout$\"},\"-u\":{\"description\":\"Specific URL to use, instead of the default \'http:\\/\\/<apache_status_address>\\/server-status\'\",\"value\":\"$apache_status_uri$\"},\"-w\":{\"description\":\"number of open slots, busy workers and idle workers that will cause a WARNING\",\"value\":\"$apache_status_warning$\"}},\"command\":\"check_apache_status.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"apache-status\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"apache_status_address\":\"$check_address$\",\"apache_status_ssl\":false,\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false}}', 'yalh', '2026-09-03 00:35:34', 0x97b1832b34a3fbf848749c86eb1ff0123f709496, 0x8b93a5f6a7ef52338b8e3ee6e23de0d8b169a0ea),
(12, 'icinga_command', 'service-windows', 'create', NULL, '{\"arguments\":{\"--description\":{\"description\":\"Use service description instead of name\",\"set_if\":\"$service_win_description$\"},\"-s\":{\"description\":\"Service to check\",\"required\":true,\"value\":\"$service_win_service$\"},\"-w\":{\"description\":\"Warn instead of critical when service is not running\",\"set_if\":\"$service_win_warn$\"}},\"command\":\"check_service.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"service-windows\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:34', 0xf743b5f4fa70393bf73ba207868b9ba8314f7e39, 0x97b1832b34a3fbf848749c86eb1ff0123f709496),
(13, 'icinga_command', 'apt', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"If the full package information of any of the upgradable packages match this REGEXP, the plugin will return CRITICAL status. Can be specified multiple times.\",\"value\":\"$apt_critical$\"},\"--dist-upgrade\":{\"description\":\"Perform a dist-upgrade instead of normal upgrade. Like with -U OPTS can be provided to override the default options.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--dist-upgrade=OPTS\":{\"description\":\"Perform a dist-upgrade instead of normal upgrade. Like with -U OPTS can be provided to override the default options.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$apt_dist_upgrade$\"},\"--exclude\":{\"description\":\"Exclude packages matching REGEXP from the list of packages that would otherwise be included. Can be specified multiple times.\",\"value\":\"$apt_exclude$\"},\"--extra-opts\":{\"description\":\"Read options from an ini file.\",\"value\":\"$apt_extra_opts$\"},\"--include\":{\"description\":\"Include only packages matching REGEXP. Can be specified multiple times the values will be combined together.\",\"value\":\"$apt_include$\"},\"--list\":{\"description\":\"List packages available for upgrade.\",\"set_if\":\"$apt_list$\"},\"--only-critical\":{\"description\":\"Only warn about critical upgrades.\",\"set_if\":\"$apt_only_critical$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 10).\",\"value\":\"$apt_timeout$\"},\"--upgrade\":{\"description\":\"[Default] Perform an upgrade. If an optional OPTS argument is provided, apt-get will be run with these command line options instead of the default.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--upgrade=OPTS\":{\"description\":\"[Default] Perform an upgrade. If an optional OPTS argument is provided, apt-get will be run with these command line options instead of the default.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$apt_upgrade$\"}},\"command\":\"check_apt\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"apt\",\"object_type\":\"external_object\",\"timeout\":300}', 'yalh', '2026-09-03 00:35:34', 0x7800ba2fd963968d61aeac4ec5fb6e5cfc23cb86, 0xf743b5f4fa70393bf73ba207868b9ba8314f7e39),
(14, 'icinga_command', 'simap', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$simap_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$simap_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$simap_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$simap_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$simap_certificate_age$\"},\"-E\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \\r\\n added to end of quit\",\"value\":\"$simap_escape$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$simap_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit (default: warn)\",\"value\":\"$simap_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$simap_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$simap_critical$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response\",\"value\":\"$simap_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated)\",\"value\":\"$simap_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$simap_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received\",\"value\":\"$simap_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$simap_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$simap_quit$\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit (default: crit)\",\"value\":\"$simap_refuse$\"},\"-s\":{\"description\":\"String to send to the server\",\"value\":\"$simap_send$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$simap_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$simap_warning$\"}},\"command\":\"check_simap\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"simap\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$simap_ipv4$\",\"check_ipv6\":\"$simap_ipv6$\",\"simap_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:34', 0x32ff16ffce1a35abac48d81b647af1590f463fa6, 0x7800ba2fd963968d61aeac4ec5fb6e5cfc23cb86),
(15, 'icinga_command', 'breeze', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"SNMPv1 community (default public)\",\"value\":\"$breeze_community$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"required\":true,\"value\":\"$breeze_hostname$\"},\"-c\":{\"description\":\"Percentage strength below which a CRITICAL status will result\",\"required\":true,\"value\":\"$breeze_critical$\"},\"-w\":{\"description\":\"Percentage strength below which a WARNING status will result\",\"required\":true,\"value\":\"$breeze_warning$\"}},\"command\":\"check_breeze\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"breeze\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"breeze_critical\":\"20\",\"breeze_hostname\":\"$check_address$\",\"breeze_warning\":\"50\",\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false}}', 'yalh', '2026-09-03 00:35:35', 0x0e9e46cb5c5e0f85ca3eb0680b56ce030a7f20db, 0x32ff16ffce1a35abac48d81b647af1590f463fa6),
(16, 'icinga_command', 'sleep', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"sleep\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"sleep_time\":1}}', 'yalh', '2026-09-03 00:35:35', 0x0bc830b27be0abfdf68689a782419e0fe95c16fd, 0x0e9e46cb5c5e0f85ca3eb0680b56ce030a7f20db),
(17, 'icinga_command', 'smart', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$smart_extra_opts$\"},\"-d\":{\"description\":\"Name of a local hard drive to monitor\",\"required\":true,\"value\":\"$smart_device$\"}},\"command\":\"check_ide_smart\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"smart\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:35', 0x973d53d6d2e7ce4842d22b5aefd2efde7b1b75e9, 0x0bc830b27be0abfdf68689a782419e0fe95c16fd),
(18, 'icinga_command', 'btrfs', 'create', NULL, '{\"arguments\":{\"--allocated-critical-gib\":{\"description\":\"Exit with CRITICAL status if less than the specified amount of disk space (in GiB) is unallocated\",\"value\":\"$btrfs_acg$\"},\"--allocated-critical-percent\":{\"description\":\"Exit with CRITICAL status if more than the specified percent of disk space is allocated\",\"value\":\"$btrfs_acp$\"},\"--allocated-warning-gib\":{\"description\":\"Exit with WARNING status if less than the specified amount of disk space (in GiB) is unallocated\",\"value\":\"$btrfs_awg$\"},\"--allocated-warning-percent\":{\"description\":\"Exit with WARNING status if more than the specified percent of disk space is allocated\",\"value\":\"$btrfs_awp$\"},\"--mountpoint\":{\"description\":\"Path to the BTRFS mountpoint\",\"required\":true,\"value\":\"$btrfs_mountpoint$\"}},\"command\":\"sudo \\/usr\\/lib\\/nagios\\/plugins\\/check_btrfs\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"btrfs\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"btrfs_acp\":90,\"btrfs_awp\":80}}', 'yalh', '2026-09-03 00:35:35', 0xac451c31719364aa80b3c36d0464d2aca20e21bf, 0x973d53d6d2e7ce4842d22b5aefd2efde7b1b75e9),
(19, 'icinga_command', 'smart-advanced', 'create', NULL, '{\"arguments\":{\"--skip-self-assessment\":{\"description\":\"If set to true, Skip the SMART self assessment health check (not recommended).\",\"set_if\":\"$smart_skip_self_assessment$\"},\"-E\":{\"description\":\"List of (comma separated) SMART attributes which should be excluded (=ignored) completely from checks and perfdata.\",\"value\":\"$smart_exclude_all_list$\"},\"-b\":{\"description\":\"Threshold value (integer) when to warn for N bad entries (ATA: Current Pending Sector, SCSI: Grown defect list). Note: Deprecated for ATA drives, use `smart_warn` instead. Continue to use this for SCSI drives.\",\"value\":\"$smart_bad$\"},\"-d\":{\"description\":\"A physical block device to be SMART monitored, eg \\/dev\\/sda.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$smart_device$\"},\"-e\":{\"description\":\"List of (comma separated) SMART attributes which should be excluded (=ignored) from checks, but still appear in perfdata.\",\"value\":\"$smart_exclude_list$\"},\"-g\":{\"description\":\"A glob expression of physical devices to be monitored, eg -g \'\\/dev\\/sd[a-z]\'.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$smart_device$\"},\"-i\":{\"description\":\"Drive\'s interface type, must be one of: auto, ata, scsi, nvme, 3ware,N, areca,N, hpt,L\\/M\\/N, cciss,N, megaraid,N.\",\"required\":true,\"value\":\"$smart_interface$\"},\"-l\":{\"description\":\"If set to true, additionally check SSD attribute Percent_Lifetime_Remain.\",\"set_if\":\"$smart_ssd_lifetime$\"},\"-q\":{\"description\":\"If set to true, only show failing drive(s) when faults are detected (only affects output when used with `vars.smart_device_is_glob`).\",\"set_if\":\"$smart_quiet$\"},\"-r\":{\"description\":\"List (comma separated, without spaces!) of SMART attributes to check for their raw values.\",\"value\":\"$smart_raw_list$\"},\"-s\":{\"description\":\"If set to true, additionally check SMART\'s selftest log for errors.\",\"set_if\":\"$smart_selftest$\"},\"-w\":{\"description\":\"Comma separated list of thresholds for ATA drives (e.g. `\'Reallocated_Sector_Ct=10,Current_Pending_Sector=62\'`).\",\"value\":\"$smart_warn$\"}},\"command\":\"check_smart.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"smart-advanced\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"smart_device_is_glob\":false,\"smart_interface\":\"auto\",\"smart_quiet\":false,\"smart_selftest\":false,\"smart_ssd_lifetime\":false}}', 'yalh', '2026-09-03 00:35:35', 0xe02065ec52b05b8086b3261fdf35a0b884f1f77e, 0xac451c31719364aa80b3c36d0464d2aca20e21bf),
(20, 'icinga_command', 'by_ssh', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$by_ssh_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 only\",\"set_if\":\"$by_ssh_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 only\",\"set_if\":\"$by_ssh_ipv4$\"},\"-C\":{\"type\":\"Function\",\"body\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\"},\"-E\":{\"description\":\"Ignore all or (if specified) first n lines on STDERR [optional]\",\"value\":\"$by_ssh_skip_stderr$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$by_ssh_address$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$by_ssh_crit$\"},\"-i\":{\"description\":\"identity of an authorized key [optional]\",\"value\":\"$by_ssh_identity$\"},\"-l\":{\"description\":\"SSH user name on remote host [optional]\",\"value\":\"$by_ssh_logname$\"},\"-o\":{\"description\":\"Provide ssh options (may be repeated)\",\"value\":\"$by_ssh_options$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$by_ssh_port$\"},\"-q\":{\"description\":\"Tell ssh to suppress warning and diagnostic messages [optional]\",\"set_if\":\"$by_ssh_quiet$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$by_ssh_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$by_ssh_warn$\"}},\"command\":\"check_by_ssh\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"by_ssh\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"by_ssh_address\":\"$check_address$\",\"by_ssh_quiet\":false,\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$by_ssh_ipv4$\",\"check_ipv6\":\"$by_ssh_ipv6$\"}}', 'yalh', '2026-09-03 00:35:35', 0x4c9619c33ebcac4110ce8dcce72c7f9106a6aefb, 0xe02065ec52b05b8086b3261fdf35a0b884f1f77e),
(21, 'icinga_command', 'smart-attributes', 'create', NULL, '{\"arguments\":{\"--allperfs\":{\"description\":\"Get performance data for all monitor-able smart attributes and don\'t limit performance data to the \'Perfs\' section in the smartdb.json.\",\"set_if\":\"$smart_attributes_get_allperfs$\"},\"--critical_on_unknown\":{\"description\":\"Show critical if the device was not found in database.\",\"set_if\":\"$smart_attributes_critical_if_not_found$\"},\"--dbjson\":{\"description\":\"Path to the smart attributes config file (e.g. check_smartdb.json)\",\"required\":true,\"value\":\"$smart_attributes_config_path$\"},\"--device\":{\"description\":\"Insert the device name (e.g. \\/dev\\/sda) to monitor\",\"value\":\"$smart_attributes_device$\"},\"--options\":{\"description\":\"Additional parameters forwarded to smarctl binary\",\"value\":\"$smart_attributes_options$\"},\"--path\":{\"description\":\"Specify the path at which the smartctl binary can be found.\",\"value\":\"$smart_attributes_smartclt_path$\"},\"--regex\":{\"description\":\"Insert a regex to finde devices to monitori (version > 1.6)\",\"value\":\"$smart_attributes_device_regex$\"},\"--ssdonly\":{\"description\":\"Check SSDs only, even if more devices are given.\",\"set_if\":\"$smart_attributes_ssd_only$\"},\"--ucfgjson\":{\"description\":\"Specify the path at which the JSON smart db can be found.\",\"value\":\"$smart_attributes_user_config_path$\"},\"-nosudo\":{\"description\":\"Disable the usage of sudo for smartctl.\",\"set_if\":\"$smart_attributes_no_sudo$\"}},\"command\":\"check_smart_attributes\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"smart-attributes\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"smart_attributes_config_path\":\"\\/etc\\/icinga2\\/plugins-config\\/check_smartdb.json\"}}', 'yalh', '2026-09-03 00:35:35', 0x5b0943632796f3652b738c6db0e0046c366bf8cb, 0x4c9619c33ebcac4110ce8dcce72c7f9106a6aefb),
(22, 'icinga_command', 'ceph', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"alternative ceph conf file\",\"required\":false,\"value\":\"$ceph_conf_file$\"},\"-d\":{\"description\":\"exec \'ceph health detail\'\",\"set_if\":\"$ceph_details$\"},\"-e\":{\"description\":\"ceph executable [\\/usr\\/bin\\/ceph]\",\"required\":false,\"value\":\"$ceph_exec_dir$\"},\"-i\":{\"description\":\"ceph client id\",\"required\":false,\"value\":\"$ceph_client_id$\"},\"-k\":{\"description\":\"ceph client keyring file\",\"required\":false,\"value\":\"$ceph_client_key$\"},\"-m\":{\"description\":\"ceph monitor address[:port]\",\"required\":false,\"value\":\"$ceph_mon_address$\"},\"-n\":{\"description\":\"ceph client name\",\"required\":false,\"value\":\"$ceph_client_name$\"},\"-w\":{\"description\":\"whitelist regexp for ceph health warnings\",\"required\":false,\"value\":\"$ceph_whitelist$\"}},\"command\":\"check_ceph.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ceph\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:35', 0x7a215d4447facb6534ab6caf3eb08848644e363b, 0x5b0943632796f3652b738c6db0e0046c366bf8cb),
(23, 'icinga_command', 'smtp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$smtp_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$smtp_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$smtp_ipv4$\"},\"-A\":{\"description\":\"SMTP AUTH type to check (default none, only LOGIN supported)\",\"value\":\"$smtp_authtype$\"},\"-C\":{\"description\":\"SMTP command\",\"value\":\"$smtp_command$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$smtp_certificate_age$\"},\"-F\":{\"description\":\"FQDN used for HELO\",\"value\":\"$smtp_helo_fqdn$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$smtp_address$\"},\"-P\":{\"description\":\"SMTP AUTH password\",\"value\":\"$smtp_authpass$\"},\"-R\":{\"description\":\"Expected response to command (may be used repeatedly)\",\"value\":\"$smtp_response$\"},\"-S\":{\"description\":\"Use STARTTLS for the connection.\",\"set_if\":\"$smtp_starttls$\"},\"-U\":{\"description\":\"SMTP AUTH username\",\"value\":\"$smtp_authuser$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$smtp_critical$\"},\"-e\":{\"description\":\"String to expect in first line of server response (default: \'220\')\",\"value\":\"$smtp_expect$\"},\"-f\":{\"description\":\"FROM-address to include in MAIL command, required by Exchange 2000\",\"value\":\"$smtp_mail_from$\"},\"-p\":{\"description\":\"Port number (default: 25)\",\"value\":\"$smtp_port$\"},\"-q\":{\"description\":\"Ignore failure when sending QUIT command to server\",\"value\":\"$smtp_ignore_quit$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$smtp_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$smtp_warning$\"}},\"command\":\"check_smtp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"smtp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$smtp_ipv4$\",\"check_ipv6\":\"$smtp_ipv6$\",\"smtp_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:35', 0x465efd422b911002b3a0d96a4bed3ad5ae20dd19, 0x7a215d4447facb6534ab6caf3eb08848644e363b),
(24, 'icinga_command', 'clamd', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$clamd_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 only\",\"set_if\":\"$clamd_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 only\",\"set_if\":\"$clamd_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$clamd_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid. 1st value is number of days for warning, 2nd is critical (if not specified: 0) - seperated by comma.\",\"value\":\"$clamd_certificate$\"},\"-E_quit\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in quit string. Default is \\r\\n added to end of quit.\",\"set_if\":\"$clamd_escape_quit$\",\"order\":\"3\"},\"-E_send\":{\"description\":\"Enable usage of \\n, \\r, \\t or \\\\ in send string. Default is nothing.\",\"set_if\":\"$clamd_escape_send$\",\"order\":\"1\"},\"-H\":{\"description\":\"The host\'s address or unix socket (must be an absolute path).\",\"required\":true,\"value\":\"$clamd_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit. Defaults to warn.\",\"value\":\"$clamd_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$clamd_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds).\",\"value\":\"$clamd_ctime$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response.\",\"value\":\"$clamd_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated).\",\"repeat_key\":true,\"value\":\"$clamd_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$clamd_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received.\",\"value\":\"$clamd_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none).\",\"value\":\"$clamd_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection.\",\"value\":\"$clamd_quit$\",\"order\":\"4\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit. Defaults to crit.\",\"value\":\"$clamd_refuse$\"},\"-s\":{\"description\":\"String to send to the server.\",\"value\":\"$clamd_send$\",\"order\":\"2\"},\"-t\":{\"description\":\"Seconds before connection times out. Defaults to 10.\",\"value\":\"$clamd_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds).\",\"value\":\"$clamd_wtime$\"}},\"command\":\"check_clamd\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"clamd\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_ipv4\":\"$clamd_ipv4$\",\"check_ipv6\":\"$clamd_ipv6$\",\"clamd_mismatch\":\"warn\",\"clamd_refuse\":\"crit\",\"clamd_ssl\":false,\"clamd_timeout\":10}}', 'yalh', '2026-09-03 00:35:36', 0x8b535b97d6f6b4f12af85829f30d0f68ea1ad3b6, 0x465efd422b911002b3a0d96a4bed3ad5ae20dd19),
(25, 'icinga_command', 'cloudera_hdfs_files', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"Namenode host\",\"required\":true,\"value\":\"$cloudera_hdfs_files_host$\"},\"-P\":{\"description\":\"Namenode port (default 50070)\",\"required\":false,\"value\":\"$cloudera_hdfs_files_port$\"},\"-c\":{\"description\":\"Critical threshold\",\"required\":true,\"value\":\"$cloudera_hdfs_files_crit$\"},\"-m\":{\"description\":\"Max files count that causes problems (default 140000000)\",\"required\":false,\"value\":\"$cloudera_hdfs_files_max$\"},\"-w\":{\"description\":\"Warning threshold\",\"required\":true,\"value\":\"$cloudera_hdfs_files_warn$\"}},\"command\":\"check_cloudera_hdfs_files.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"cloudera_hdfs_files\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:36', 0x227b38579e4cc568ffa26d175ae8720d0d0c76a3, 0x8b535b97d6f6b4f12af85829f30d0f68ea1ad3b6),
(26, 'icinga_command', 'snmp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$snmp_extra_opts$\"},\"--invert-search\":{\"description\":\"Invert search result and return CRITICAL if found\",\"set_if\":\"$snmp_invert_search$\"},\"--offset\":{\"description\":\"Add\\/substract the specified OFFSET to numeric sensor data\",\"value\":\"$snmp_offset$\"},\"--rate\":{\"description\":\"Enable rate calculation\",\"set_if\":\"$snmp_rate$\"},\"--rate-multiplier\":{\"description\":\"Converts rate per second. For example, set to 60 to convert to per minute\",\"value\":\"$snmp_rate_multiplier$\"},\"-C\":{\"description\":\"Optional community string for SNMP communication (default is \'public\')\",\"value\":\"$snmp_community$\"},\"-D\":{\"description\":\"Separates output on multiple OID requests\",\"value\":\"$snmp_output_delimiter$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$snmp_address$\"},\"-M\":{\"description\":\"Multiplies current value, 0 < n < 1 works as divider, defaults to 1\",\"value\":\"$snmp_multiplier$\"},\"-O\":{\"description\":\"Label performance data with OIDs instead of --label\'s\",\"set_if\":\"$snmp_perf_oids$\"},\"-P\":{\"description\":\"SNMP protocol version\",\"value\":\"$snmp_version$\"},\"-R\":{\"description\":\"Return OK state (for that OID) if case-insensitive extended REGEX matches\",\"value\":\"$snmp_eregi$\"},\"-c\":{\"description\":\"Critical threshold range(s)\",\"value\":\"$snmp_crit$\"},\"-e\":{\"description\":\"Number of retries to be used in the requests\",\"value\":\"$snmp_retries$\"},\"-l\":{\"description\":\"Prefix label for output from plugin\",\"value\":\"$snmp_label$\"},\"-m\":{\"description\":\"List of MIBS to be loaded (default = none if using numeric OIDs or \'ALL\' for symbolic OIDs.)\",\"value\":\"$snmp_miblist$\"},\"-n\":{\"description\":\"Use SNMP GETNEXT instead of SNMP GET\",\"set_if\":\"$snmp_getnext$\"},\"-o\":{\"description\":\"Object identifier(s) or SNMP variables whose value you wish to query\",\"value\":\"$snmp_oid$\"},\"-p\":{\"description\":\"Port number (default: 161)\",\"value\":\"$snmp_port$\"},\"-r\":{\"description\":\"Return OK state (for that OID) if extended regular expression REGEX matches\",\"value\":\"$snmp_ereg$\"},\"-s\":{\"description\":\"Return OK state (for that OID) if STRING is an exact match\",\"value\":\"$snmp_string$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$snmp_timeout$\"},\"-u\":{\"description\":\"Units label(s) for output data (e.g., \'sec.\')\",\"value\":\"$snmp_units$\"},\"-w\":{\"description\":\"Warning threshold range(s)\",\"value\":\"$snmp_warn$\"}},\"command\":\"check_snmp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"snmp_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"snmp_community\":\"public\",\"snmp_invert_search\":false,\"snmp_timeout\":\"10\"}}', 'yalh', '2026-09-03 00:35:36', 0x97ed3ebc543fcb78f19723429b426e265ab5891e, 0x227b38579e4cc568ffa26d175ae8720d0d0c76a3),
(27, 'icinga_command', 'cloudera_hdfs_space', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"Namenode host\",\"required\":true,\"value\":\"$cloudera_hdfs_space_host$\"},\"-P\":{\"description\":\"Namenode port (default 50070)\",\"required\":false,\"value\":\"$cloudera_hdfs_space_port$\"},\"-c\":{\"description\":\"Critical threshold in percent\",\"required\":true,\"value\":\"$cloudera_hdfs_space_crit$\"},\"-d\":{\"description\":\"HDFS disk to check\",\"required\":true,\"value\":\"$cloudera_hdfs_space_disk$\"},\"-w\":{\"description\":\"Warning threshold in percent\",\"required\":true,\"value\":\"$cloudera_hdfs_space_warn$\"}},\"command\":\"check_cloudera_hdfs_space.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"cloudera_hdfs_space\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:36', 0xbc515c3b389cb1a28cc225eaf65bba6a6c8a2cf2, 0x97ed3ebc543fcb78f19723429b426e265ab5891e),
(28, 'icinga_command', 'cloudera_service_status', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"host\",\"required\":true,\"value\":\"$cloudera_host$\"},\"-P\":{\"description\":\"port\",\"required\":false,\"value\":\"$cloudera_port$\"},\"-c\":{\"description\":\"cluster\",\"required\":true,\"value\":\"$cloudera_cluster$\"},\"-k\":{\"description\":\"verify_ssl\",\"required\":false,\"value\":\"$cloudera_verify_ssl$\"},\"-p\":{\"description\":\"pass\",\"required\":true,\"value\":\"$cloudera_pass$\"},\"-s\":{\"description\":\"service\",\"required\":true,\"value\":\"$cloudera_service$\"},\"-u\":{\"description\":\"user\",\"required\":true,\"value\":\"$cloudera_user$\"},\"-v\":{\"description\":\"api_version\",\"required\":true,\"value\":\"$cloudera_api_version$\"}},\"command\":\"check_cloudera_service_status.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"cloudera_service_status\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:36', 0xe8244b2df4373cd6d92ee637e9d4583ef8a14346, 0xbc515c3b389cb1a28cc225eaf65bba6a6c8a2cf2),
(29, 'icinga_command', 'snmp-env', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-F\":{\"description\":\"Minimum fan rpm value (only needed for \'iron\' & \'linux\')\",\"value\":\"$snmp_env_fan$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-T\":{\"description\":\"Environment Type [cisco|nokia|bc|iron|foundry|linux]\",\"value\":\"$snmp_env_type$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-c\":{\"description\":\"Maximum temp in degrees celsius (only needed for \'iron\' & \'linux\')\",\"value\":\"$snmp_env_celsius$\"},\"-f\":{\"description\":\"Perfparse compatible output\",\"set_if\":\"$snmp_perf$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_env.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-env\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_env_type\":\"cisco\",\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false}}', 'yalh', '2026-09-03 00:35:36', 0xa2b0aa260c836ea7d43f86c1bfe8cfdb36c2ef0c, 0xe8244b2df4373cd6d92ee637e9d4583ef8a14346),
(30, 'icinga_command', 'cluster', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"cluster\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:37', 0x8f402c8d858874374ee95e1234ea368f91d344f4, 0xa2b0aa260c836ea7d43f86c1bfe8cfdb36c2ef0c),
(31, 'icinga_command', 'cluster-zone', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"cluster-zone\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"cluster_zone\":\"$host.name$\"}}', 'yalh', '2026-09-03 00:35:37', 0xed7333f8d86adb06a68cecf2d37f0ed1d7b7055c, 0x8f402c8d858874374ee95e1234ea368f91d344f4),
(32, 'icinga_command', 'snmp-interface', 'create', NULL, '{\"arguments\":{\"--64bits\":{\"description\":\"Use 64 bits counters instead of the standard counters when checking bandwidth & performance data for interface >= 1Gbps\",\"set_if\":\"$snmp_interface_64bit$\"},\"--label\":{\"description\":\"Add label before speed in output : in=, out=, errors-out=, etc...\",\"value\":\"$snmp_interface_label$\"},\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-A\":{\"set_if\":\"$snmp_interface_ifalias$\"},\"-B\":{\"description\":\"Make the warning and critical levels in K|M|G Bits\\/s instead of K|M|G Bytes\\/s\",\"set_if\":\"$snmp_interface_kbits$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-M\":{\"description\":\"Make the warning and critical levels in Mbps\",\"set_if\":\"$snmp_interface_megabytes$\"},\"-N\":{\"set_if\":\"$snmp_interface_ifname$\"},\"-W\":{\"description\":\"Include \'weathermap\' data for NagVis in performance data\",\"set_if\":\"$snmp_interface_weathermap$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-Y\":{\"description\":\"Output performance data in bits\\/s or Bytes\\/s\",\"set_if\":\"$snmp_interface_bits_bytes$\"},\"-a\":{\"description\":\"Use administrative status instead of operational\",\"set_if\":\"$snmp_interface_admin$\"},\"-c\":\"$snmp_crit$\",\"-d\":{\"description\":\"Make an average of <delta> seconds (default 300=5min)\",\"value\":\"$snmp_interface_delta$\"},\"-e\":{\"description\":\"Add error & discard to Perfparse output\",\"set_if\":\"$snmp_interface_errors$\"},\"-f\":{\"description\":\"Perfparse compatible output (no output when interface is down)\",\"set_if\":\"$snmp_perf$\"},\"-i\":{\"description\":\"Make critical when up\",\"set_if\":\"$snmp_interface_inverse$\"},\"-k\":{\"description\":\"Check the input\\/ouput bandwidth of the interface\",\"set_if\":\"$snmp_interface_perf$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-n\":{\"description\":\"Name in description OID (eth0, ppp0 ...). This is treated as a regexp : -n eth will match eth0,eth1,...\",\"value\":\"$snmp_interface$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-q\":{\"description\":\"Also check the error and discard input\\/output. When enabled format of snmp_warn and snmp_crit changes to <In bytes>,<Out bytes>,<In error>,<Out error>,<In disc>,<Out disc>\",\"set_if\":\"$snmp_interface_extended_checks$\"},\"-r\":{\"description\":\"Do not use regexp to match NAME in description OID\",\"set_if\":\"$snmp_interface_noregexp$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-u\":{\"description\":\"Make the warning and critical levels in % of reported interface speed\",\"set_if\":\"$snmp_interface_warncrit_percent$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"},\"-y\":{\"description\":\"Output performance data in % of max speed\",\"set_if\":\"$snmp_interface_percent$\"}},\"command\":\"check_snmp_int.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-interface\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_crit\":\"0,600\",\"snmp_interface\":\"eth0\",\"snmp_interface_64bit\":false,\"snmp_interface_bits_bytes\":true,\"snmp_interface_delta\":300,\"snmp_interface_errors\":true,\"snmp_interface_extended_checks\":false,\"snmp_interface_ifalias\":false,\"snmp_interface_ifname\":false,\"snmp_interface_kbits\":true,\"snmp_interface_megabytes\":true,\"snmp_interface_noregexp\":false,\"snmp_interface_percent\":false,\"snmp_interface_perf\":true,\"snmp_interface_warncrit_percent\":false,\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false,\"snmp_warn\":\"300,400\"}}', 'yalh', '2026-09-03 00:35:37', 0x0e039df844200477e27f13e97bbc35f0af28407a, 0xed7333f8d86adb06a68cecf2d37f0ed1d7b7055c);
INSERT INTO `director_activity_log` (`id`, `object_type`, `object_name`, `action_name`, `old_properties`, `new_properties`, `author`, `change_time`, `checksum`, `parent_checksum`) VALUES
(33, 'icinga_command', 'curl', 'create', NULL, '{\"arguments\":{\"(-S w\\/ value)\":{\"description\":\"Connect via SSL. Port defaults to 443. VERSION is optional, and prevents auto-negotiation\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$curl_tls_version$\"},\"(-S w\\/o value)\":{\"description\":\"Connect via SSL. Port defaults to 443. VERSION is optional, and prevents auto-negotiation\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--ca-cert\":{\"description\":\"CA certificate file to verify peer against\",\"value\":\"$curl_ca_cert_file$\"},\"--continue-after-certificate\":{\"description\":\"Allows the HTTP check to continue after performing the certificate check. Does nothing unless -C is used.\",\"value\":\"$curl_continue_after_certificate$\"},\"--cookie-jar\":{\"description\":\"Store cookies in the cookie jar file and send them out when requested.\",\"value\":\"$curl_cookie_jar_file$\"},\"--enable-automatic-decompression\":{\"description\":\"Enable automatic decompression of body (CURLOPT_ACCEPT_ENCODING).\",\"set_if\":\"$curl_enable_automatic_decompression$\"},\"--extra-opts\":{\"description\":\"Read options from an ini file\",\"value\":\"$curl_extra_opts$\"},\"--haproxy-protocol\":{\"description\":\"Send HAProxy proxy protocol v1 header (CURLOPT_HAPROXYPROTOCOL)\",\"set_if\":\"$curl_haproxy_protocol$\"},\"--http-version\":{\"description\":\"Connect via specific HTTP protocol. 1.0 = HTTP\\/1.0, 1.1 = HTTP\\/1.1, 2.0 = HTTP\\/2 (HTTP\\/2 will fail without -S)\",\"value\":\"$curl_http_version$\"},\"--invert-regex\":{\"description\":\"When using regex, return CRITICAL if found, OK if not\",\"set_if\":\"$curl_invert_regex$\"},\"--max-redirs\":{\"description\":\"Maximal number of redirects (default: 15)\",\"value\":\"$curl_max_redirs$\"},\"--sni\":{\"description\":\"Enable SSL\\/TLS hostname extension support (SNI). Default if TLS version > 1.0\",\"set_if\":\"$curl_sni$\"},\"--state-regex\":{\"description\":\"Return STATE if regex is found, OK if not\",\"value\":\"$curl_state_regex$\"},\"-6\":{\"description\":\"Force `check_curl` to use IPv6 instead of choosing automatically\",\"set_if\":\"$curl_ipv6$\"},\"-4\":{\"description\":\"Force `check_curl` to use IPv4 instead of choosing automatically\",\"set_if\":\"$curl_ipv4$\"},\"-A\":{\"description\":\"String to be sent in http header as \'User Agent\'\",\"value\":\"$curl_user_agent$\"},\"-B\":{\"description\":\"Print body content below status line\",\"set_if\":\"$curl_show_body$\"},\"-C\":{\"description\":\"Minimum number of days a certificate has to be valid.\",\"value\":\"$curl_certificate_valid_days_min_warning$,$curl_certificate_valid_days_min_critical$\"},\"-D\":{\"description\":\"Verify the peer\'s SSL certificate and hostname\",\"set_if\":\"$curl_verify_peer_cert$\"},\"-E\":{\"description\":\"Print additional performance data\",\"set_if\":\"$curl_extended_perfdata$\"},\"-H\":{\"description\":\"Host name argument for servers using host headers (virtual host). Append a port to include it in the header (eg: example.com:5000)\",\"value\":\"$curl_vhost$\"},\"-I\":{\"description\":\"IP address or name (use numeric address if possible to bypass DNS lookup).\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$curl_ip$\"},\"-J\":{\"description\":\"Name of file that contains the client certificate (PEM format) to be used in establishing the SSL session\",\"value\":\"$curl_client_certificate_file$\"},\"-K\":{\"description\":\"Name of file containing the private key (PEM format) matching the client certificate\",\"value\":\"$curl_client_certificate_key_file$\"},\"-L\":{\"description\":\"Wrap output in HTML link (obsoleted by urlize)\",\"set_if\":\"$curl_link$\"},\"-M\":{\"description\":\"Warn if document is more than SECONDS old. the number can also be of the form \'10m\' for minutes, \'10h\' for hours, or \'10d\' for days.\",\"value\":\"$curl_max_age$\"},\"-N\":{\"description\":\"Don\'t wait for document body: stop reading after headers. (Note that this still does an HTTP GET or POST, not a HEAD.)\",\"value\":\"$curl_no_body$\"},\"-P\":{\"description\":\"URL encoded http POST data\",\"value\":\"$curl_post_data$\"},\"-R\":{\"description\":\"Search page for case-insensitive regex STRING\",\"value\":\"$curl_eregi$\"},\"-T\":{\"description\":\"specify Content-Type header media type when POSTing\",\"value\":\"$curl_content_type$\"},\"-a\":{\"description\":\"Username:password on sites with basic authentication\",\"value\":\"$curl_authorization$\"},\"-b\":{\"description\":\"Username:password on proxy-servers with basic authentication\",\"value\":\"$curl_proxy_authorization$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$curl_critical$\"},\"-d\":{\"description\":\"String to expect in the response headers\",\"value\":\"$curl_expect_header_string$\"},\"-e\":{\"description\":\"Comma-delimited list of strings, at least one of them is expected in the first (status) line of the server response (default: HTTP\\/), If specified skips all other status line logic (ex: 3xx, 4xx, 5xx processing)\",\"value\":\"$curl_expect_string$\"},\"-f\":{\"description\":\"Options: <ok|warning|critical|follow|sticky|stickyport|curl> How to handle redirected pages.\",\"value\":\"$curl_onredirect$\"},\"-j\":{\"description\":\"Set HTTP method (for example: HEAD, OPTIONS, TRACE, PUT, DELETE, CONNECT)\",\"value\":\"$curl_http_method$\"},\"-k\":{\"description\":\"Any other tags to be sent in http header. Use multiple times for additional headers\",\"repeat_key\":true,\"value\":\"$curl_header$\"},\"-l\":{\"description\":\"Allow regex to span newlines (must precede -r or -R)\",\"value\":\"$curl_linespan$\"},\"-m\":{\"description\":\"Minimum page size required (bytes) : Maximum page size required (bytes)\",\"value\":\"$curl_pagesize$\"},\"-p\":{\"description\":\"Port number (default: 80)\",\"value\":\"$curl_port$\"},\"-r\":{\"description\":\"Search page for regex STRING\",\"value\":\"$curl_ereg$\"},\"-s\":{\"description\":\"String to expect in the content\",\"value\":\"$curl_expect_content_string$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$curl_timeout$\"},\"-u\":{\"description\":\"URL to GET or POST (default: \\/)\",\"value\":\"$curl_url$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$curl_warning$\"}},\"command\":\"check_curl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"curl\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$curl_ipv4$\",\"check_ipv6\":\"$curl_ipv6$\",\"curl_extended_perfdata\":false,\"curl_invert_regex\":false,\"curl_ip\":\"$check_address$\",\"curl_link\":false,\"curl_show_body\":false}}', 'yalh', '2026-09-03 00:35:37', 0x41a5911952e6bf02aab03781e4f674e8ced47923, 0x0e039df844200477e27f13e97bbc35f0af28407a),
(34, 'icinga_command', 'snmp-load', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-T\":{\"description\":\"CPU check\",\"value\":\"$snmp_load_type$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-c\":\"$snmp_crit$\",\"-f\":{\"description\":\"Perfparse compatible output\",\"set_if\":\"$snmp_perf$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_load.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-load\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_crit\":95,\"snmp_load_type\":\"stand\",\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false,\"snmp_warn\":85}}', 'yalh', '2026-09-03 00:35:37', 0x7d856942f4cd0e13b1707f94614e2966da4071e4, 0x41a5911952e6bf02aab03781e4f674e8ced47923),
(35, 'icinga_command', 'db2_health', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"the critical range\",\"value\":\"$db2_health_critical$\",\"order\":\"6\"},\"--database\":{\"description\":\"the database to connect\",\"value\":\"$db2_health_database$\",\"order\":\"0\"},\"--hostname\":{\"description\":\"the host to connect\",\"set_if\":\"$db2_health_not_catalogued$\",\"value\":\"$db2_health_hostname$\",\"order\":\"-2\"},\"--lookback\":{\"description\":\"How many days iin the past db2_health check should look back to calculate exitcode.\",\"value\":\"$db2_health_lookback$\"},\"--maxinactivity\":{\"description\":\"used for the maximum amount of time a certain event has not happened.\",\"value\":\"$db2_health_maxinactivity$\"},\"--mitigation\":{\"description\":\"let you classify the severity of an offline tablespace.\",\"value\":\"$db2_health_mitigation$\"},\"--mode\":{\"description\":\"the mode of the plugin\",\"value\":\"$db2_health_mode$\",\"order\":\"3\"},\"--name\":{\"description\":\"the name of the tablespace, datafile, wait event, latch, enqueue, or sql statement depending on the mode\",\"value\":\"$db2_health_name$\",\"order\":\"4\"},\"--name2\":{\"description\":\"if name is a sql statement, name2 can be used to appear in the output and the performance data\",\"value\":\"$db2_health_name2$\",\"order\":\"7\"},\"--password\":{\"description\":\"the db2 user\'s password\",\"value\":\"$db2_health_password$\",\"order\":\"2\"},\"--port\":{\"description\":\"the db2 port for connection\",\"value\":\"$db2_health_port$\",\"order\":\"-1\"},\"--regexp\":{\"description\":\"name will be interpreted as a regular expression\",\"set_if\":\"$db2_health_regexp$\"},\"--report\":{\"description\":\"Report can be used to output only the bad news (short,long,html)\",\"value\":\"$db2_health_report$\"},\"--units\":{\"description\":\"This is used for a better output of mode=sql and for specifying thresholds for mode=tablespace-free\",\"value\":\"$db2_health_units$\"},\"--username\":{\"description\":\"the db2 user\",\"value\":\"$db2_health_username$\",\"order\":\"1\"},\"--warning\":{\"description\":\"the warning range\",\"value\":\"$db2_health_warning$\",\"order\":\"5\"}},\"command\":\"check_db2_health\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"db2_health\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"db2_health_env_db2_home\":\"\\/opt\\/ibm\\/db2\\/V10.5\",\"db2_health_env_db2_version\":\"10.5\",\"db2_health_hostname\":\"$check_address$\",\"db2_health_not_catalogued\":true,\"db2_health_regexp\":false,\"db2_health_report\":\"short\"}}', 'yalh', '2026-09-03 00:35:38', 0x47e57f31fb4996db483d205a8ecc6d52dacc64a2, 0x7d856942f4cd0e13b1707f94614e2966da4071e4),
(36, 'icinga_command', 'dhcp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$dhcp_extra_opts$\"},\"-i\":{\"description\":\"Interface to to use for listening (i.e. eth0)\",\"value\":\"$dhcp_interface$\"},\"-m\":{\"description\":\"MAC address to use in the DHCP request\",\"value\":\"$dhcp_mac$\"},\"-r\":{\"description\":\"IP address that should be offered by at least one DHCP server\",\"value\":\"$dhcp_requestedip$\"},\"-s\":{\"description\":\"IP address of DHCP server that we must hear from\",\"value\":\"$dhcp_serverip$\"},\"-t\":{\"description\":\"Seconds to wait for DHCPOFFER before timeout occurs\",\"value\":\"$dhcp_timeout$\"},\"-u\":{\"description\":\"Unicast testing: mimic a DHCP relay\",\"set_if\":\"$dhcp_unicast$\"}},\"command\":\"check_dhcp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"dhcp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"dhcp_unicast\":false}}', 'yalh', '2026-09-03 00:35:38', 0xd963c99e76099196dc4f81ab1b5adbc91ecd68f9, 0x47e57f31fb4996db483d205a8ecc6d52dacc64a2),
(37, 'icinga_command', 'snmp-memory', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-E\":{\"description\":\"check HP \\/ Procurve memory\",\"set_if\":\"$snmp_is_hp$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-I\":{\"description\":\"check cisco memory (sum of all memory pools)\",\"set_if\":\"$snmp_is_cisco$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-b\":{\"description\":\"Exclude buffered memory in used memory\",\"set_if\":\"$snmp_membuffer$\"},\"-c\":\"$snmp_crit$\",\"-f\":{\"description\":\"Performance data output\",\"set_if\":\"$snmp_perf$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-m\":{\"description\":\"Include cached memory in used memory\",\"set_if\":\"$snmp_memcached$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_mem.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-memory\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_crit\":\"98,80\",\"snmp_is_cisco\":false,\"snmp_login\":\"snmpuser\",\"snmp_membuffer\":false,\"snmp_memcached\":false,\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false,\"snmp_warn\":\"94,50\"}}', 'yalh', '2026-09-03 00:35:38', 0xffab3c093da2ced2f14582c0cdae172d2f7abe71, 0xd963c99e76099196dc4f81ab1b5adbc91ecd68f9),
(38, 'icinga_command', 'dig', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$dig_extra_opts$\"},\"-6\":{\"description\":\"Force dig to only use IPv6 query transport\",\"set_if\":\"$dig_ipv6$\"},\"-4\":{\"description\":\"Force dig to only use IPv4 query transport\",\"set_if\":\"$dig_ipv4$\"},\"-A\":{\"description\":\"Pass STRING as argument(s) to dig\",\"value\":\"$dig_arguments$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$dig_server$\"},\"-T\":{\"description\":\"Record type to lookup (default: A)\",\"value\":\"$dig_record_type$\"},\"-a\":{\"description\":\"An address expected to be in the answer section\",\"value\":\"$dig_expected_address$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$dig_critical$\"},\"-l\":{\"description\":\"Machine name to lookup\",\"required\":true,\"value\":\"$dig_lookup$\"},\"-p\":{\"description\":\"Port number (default: 53)\",\"value\":\"$dig_port$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$dig_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$dig_warning$\"}},\"command\":\"check_dig\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"dig\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$dig_ipv4$\",\"check_ipv6\":\"$dig_ipv6$\",\"dig_server\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:38', 0xfce6ce93808098d60c36aa8f4ad4f5af699dff9b, 0xffab3c093da2ced2f14582c0cdae172d2f7abe71),
(39, 'icinga_command', 'snmp-process', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-A\":{\"description\":\"Add parameters to select processes (ex : \'named.*-t \\/var\\/named\\/chroot\' will only select named process with this parameter)\",\"set_if\":\"$snmp_process_use_params$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-F\":{\"description\":\"Add performance output (outputs : memory_usage, num_process, cpu_usage)\",\"set_if\":\"$snmp_perf$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-c\":\"$snmp_crit$\",\"-f\":{\"description\":\"Use full path name instead of process name to select processes (ex : \'\\/opt\\/app1\\/app1bin\' will only select named process with this full path)\",\"set_if\":\"$snmp_process_use_fullpath$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-m\":{\"description\":\"Checks memory usage. Values warning and critical in Mb eg. 512,1024\",\"set_if\":\"$snmp_process_mem_usage$\",\"value\":\"$snmp_process_mem_threshold$\"},\"-n\":{\"description\":\"Regex service name eg. ^apache2$\",\"value\":\"$snmp_process_name$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-u\":{\"description\":\"Checks CPU usage. Values warning and critical in % (value can be > 100% : 100%=1 CPU) eg. 15,50\",\"set_if\":\"$snmp_process_cpu_usage$\",\"value\":\"$snmp_process_cpu_threshold$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_process.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-process\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_crit\":0,\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_process_cpu_threshold\":\"0,0\",\"snmp_process_cpu_usage\":false,\"snmp_process_mem_threshold\":\"0,0\",\"snmp_process_mem_usage\":false,\"snmp_process_name\":\".*\",\"snmp_process_use_fullpath\":false,\"snmp_process_use_params\":false,\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false,\"snmp_warn\":0}}', 'yalh', '2026-09-03 00:35:38', 0x7b245827a10745c52034d98883d2ed5fd13be865, 0xfce6ce93808098d60c36aa8f4ad4f5af699dff9b),
(40, 'icinga_command', 'disk', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$disk_extra_opts$\"},\"--inode-perfdata\":{\"description\":\"Enable performance data for inode-based statistics (nagios-plugins)\",\"set_if\":\"$disk_np_inode_perfdata$\"},\"-A\":{\"description\":\"Explicitly select all paths. This is equivalent to -R .*\",\"set_if\":\"$disk_all$\",\"order\":\"1\"},\"-E\":{\"description\":\"For paths or partitions specified with -p, only check for exact paths\",\"set_if\":\"$disk_exact_match$\"},\"-I\":{\"description\":\"Regular expression to ignore selected path\\/partition (case insensitive) (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_ignore_eregi_path$\",\"order\":\"2\"},\"-K\":{\"description\":\"Exit with CRITICAL status if less than PERCENT of inode space is free\",\"value\":\"$disk_inode_cfree$\",\"order\":\"-3\"},\"-L\":{\"description\":\"Only check local filesystems against thresholds. Yet call stat on remote filesystems to test if they are accessible (e.g. to detect Stale NFS Handles)\",\"set_if\":\"$disk_stat_remote_fs$\"},\"-M\":{\"description\":\"Display the mountpoint instead of the partition\",\"set_if\":\"$disk_mountpoint$\"},\"-N\":{\"description\":\"Check only filesystems of indicated type (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_include_type$\"},\"-P\":{\"description\":\"Display inode usage in perfdata\",\"set_if\":\"$disk_inode_perfdata$\"},\"-R\":{\"description\":\"Case insensitive regular expression for path\\/partition (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_eregi_path$\"},\"-W\":{\"description\":\"Exit with WARNING status if less than PERCENT of inode space is free\",\"value\":\"$disk_inode_wfree$\",\"order\":\"-3\"},\"-X\":{\"description\":\"Ignore all filesystems of indicated type (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_exclude_type$\"},\"-c\":{\"description\":\"Exit with CRITICAL status if less than INTEGER units of disk are free or Exit with CRITCAL status if less than PERCENT of disk space is free\",\"required\":true,\"value\":\"$disk_cfree$\",\"order\":\"-3\"},\"-e\":{\"description\":\"Display only devices\\/mountpoints with errors\",\"set_if\":\"$disk_errors_only$\"},\"-f\":{\"description\":\"Don\'t account root-reserved blocks into freespace in perfdata\",\"set_if\":\"$disk_ignore_reserved$\"},\"-g\":{\"description\":\"Group paths. Thresholds apply to (free-)space of all partitions together\",\"value\":\"$disk_group$\"},\"-i\":{\"description\":\"Regular expression to ignore selected path or partition (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_ignore_ereg_path$\",\"order\":\"2\"},\"-k\":{\"description\":\"Same as --units kB\",\"set_if\":\"$disk_kilobytes$\"},\"-l\":{\"description\":\" Only check local filesystems\",\"set_if\":\"$disk_local$\"},\"-m\":{\"description\":\"Same as --units MB\",\"set_if\":\"$disk_megabytes$\"},\"-p\":{\"description\":\"Path or partition (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_partitions$\",\"order\":\"1\"},\"-p_old\":{\"value\":\"$disk_partition$\",\"order\":\"1\"},\"-r\":{\"description\":\"Regular expression for path or partition (may be repeated)\",\"repeat_key\":true,\"value\":\"$disk_ereg_path$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$disk_timeout$\"},\"-u\":{\"description\":\"Choose bytes, kB, MB, GB, TB\",\"value\":\"$disk_units$\"},\"-w\":{\"description\":\"Exit with WARNING status if less than INTEGER units of disk are free or Exit with WARNING status if less than PERCENT of disk space is free\",\"required\":true,\"value\":\"$disk_wfree$\",\"order\":\"-3\"},\"-x\":{\"description\":\"Ignore device (only works if -p unspecified)\",\"value\":\"$disk_partitions_excluded$\"},\"-x_old\":\"$disk_partition_excluded$\"},\"command\":\"check_disk\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"disk\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"disk_cfree\":\"10%\",\"disk_exclude_type\":[\"none\",\"tmpfs\",\"sysfs\",\"proc\",\"configfs\",\"devtmpfs\",\"devfs\",\"mtmfs\",\"tracefs\",\"cgroup\",\"fuse.*\",\"fuse.gvfsd-fuse\",\"fuse.gvfs-fuse-daemon\",\"fuse.portal\",\"fuse.sshfs\",\"fdescfs\",\"overlay\",\"nsfs\",\"squashfs\"],\"disk_wfree\":\"20%\"}}', 'yalh', '2026-09-03 00:35:39', 0xc957a3fcb1470584ff397fdeb09058b00c2edd7d, 0x7b245827a10745c52034d98883d2ed5fd13be865),
(41, 'icinga_command', 'disk-windows', 'create', NULL, '{\"arguments\":{\"-U\":{\"description\":\"Work with used instead of free space\",\"set_if\":\"$disk_win_show_used$\"},\"-c\":{\"description\":\"Critical threshold\",\"value\":\"$disk_win_crit$\"},\"-p\":{\"description\":\"Optional paths to check\",\"repeat_key\":true,\"value\":\"$disk_win_path$\"},\"-u\":{\"description\":\"Use this unit to display disk space\",\"value\":\"$disk_win_unit$\"},\"-w\":{\"description\":\"Warning threshold\",\"value\":\"$disk_win_warn$\"},\"-x\":{\"description\":\"Exclude these drives from check\",\"value\":\"$disk_win_exclude$\"}},\"command\":\"check_disk.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"disk-windows\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"disk_win_crit\":\"10%\",\"disk_win_unit\":\"mb\",\"disk_win_warn\":\"20%\"}}', 'yalh', '2026-09-03 00:35:39', 0x2fd67ceb4c0cc20786456fcb3805b170498e9532, 0xc957a3fcb1470584ff397fdeb09058b00c2edd7d),
(42, 'icinga_command', 'snmp-service', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-N\":{\"description\":\"Compare matching services with <n> instead of the number of names provided.\",\"value\":\"$snmp_service_count$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-c\":\"$snmp_crit$\",\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-n\":{\"description\":\"Comma separated names of services (perl regular expressions can be used for every one). By default, it is not case sensitive. eg. ^dns$\",\"value\":\"$snmp_service_name$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-r\":{\"description\":\"Do not use regexp to match NAME in service description.\",\"set_if\":\"$snmp_service_noregexp$\"},\"-s\":{\"description\":\"Show all services in the output, instead of only the non-active ones.\",\"set_if\":\"$snmp_service_showall$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_win.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-service\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_service_name\":\".*\",\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false}}', 'yalh', '2026-09-03 00:35:39', 0x001f290ad8704c461dd2eb4fcb78f93926f686b8, 0x2fd67ceb4c0cc20786456fcb3805b170498e9532),
(43, 'icinga_command', 'disk_smb', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"NetBIOS name of the server.\",\"value\":\"$disk_smb_hostname$\"},\"-P\":{\"description\":\"Port to be used to connect to. Some Windows boxes use 139, others 445 (Defaults to smbclient default if omitted).\",\"value\":\"$disk_smb_port$\"},\"-W\":{\"description\":\"Workgroup or Domain used (Defaults to \'WORKGROUP\' if omitted).\",\"value\":\"$disk_smb_workgroup$\"},\"-a\":{\"description\":\"IP-address of HOST (only necessary if HOST is in another network).\",\"value\":\"$disk_smb_address$\"},\"-c\":{\"description\":\"Percent of used space at which a critical will be generated (Defaults: 95%)\",\"value\":\"$disk_smb_cused$\"},\"-p\":{\"description\":\"Password to log in to server. (Defaults to an empty password if omitted).\",\"value\":\"$disk_smb_password$\"},\"-s\":{\"description\":\"Share name to be tested.\",\"value\":\"$disk_smb_share$\"},\"-u\":{\"description\":\"Username to log in to server. (Defaults to \'guest\' if omitted).\",\"value\":\"$disk_smb_username$\"},\"-w\":{\"description\":\"Percent of used space at which a warning will be generated (Default: 85%).\",\"value\":\"$disk_smb_wused$\"}},\"command\":\"check_disk_smb\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"disk_smb\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"disk_smb_cused\":\"95%\",\"disk_smb_wused\":\"85%\"}}', 'yalh', '2026-09-03 00:35:39', 0x6d1965a62720c56217969da42f3d4be3e4194a9c, 0x001f290ad8704c461dd2eb4fcb78f93926f686b8),
(44, 'icinga_command', 'dns', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$dns_extra_opts$\"},\"-A\":{\"description\":\"Optionally expect the DNS server to be authoritative for the lookup\",\"set_if\":\"$dns_authoritative$\"},\"-H\":{\"description\":\"The name or address you want to query.\",\"value\":\"$dns_lookup$\"},\"-L\":{\"description\":\"Return critical if the list of expected addresses does not match all addresses returned. Only supported in newer versions of monitoring-plugins (2.3 and later), and is needed in such versions to replicate behaviour of previous versions of the plugins. When not passed, one address is enough for success, instead of all.\",\"set_if\":\"$dns_all_expected$\"},\"-a\":{\"description\":\"Optional ip address or host you expect the DNS server to return. Host must end with a dot (.). This option can be repeated multiple times (Returns OK if any value match). If multiple addresses are returned at once: for version 2.2 and earlier of the monitoring-plugins, you have to match the whole string of addresses separated with commas (sorted alphabetically). For version 2.3 and later, you need to pass a list of strings, one for each address you want to match.\",\"value\":\"$dns_expected_answers$\"},\"-c\":{\"description\":\"Return critical if elapsed time exceeds value.\",\"value\":\"$dns_ctime$\"},\"-n\":{\"description\":\"Optionally accept cname responses as a valid result to a query. The default is to ignore cname responses as part of the result\",\"set_if\":\"$dns_accept_cname$\"},\"-q\":{\"description\":\"Optional DNS record query type where TYPE =(A, AAAA, SRV, TXT, MX, ANY). The default query type is \'A\' (IPv4 host entry)\",\"value\":\"$dns_query_type$\"},\"-s\":{\"description\":\"Optional DNS server you want to use for the lookup.\",\"value\":\"$dns_server$\"},\"-t\":{\"description\":\"Seconds before connection times out. Defaults to 10.\",\"value\":\"$dns_timeout$\"},\"-w\":{\"description\":\"Return warning if elapsed time exceeds value.\",\"value\":\"$dns_wtime$\"}},\"command\":\"check_dns\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"dns\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"dns_lookup\":\"$host.name$\",\"dns_timeout\":10}}', 'yalh', '2026-09-03 00:35:39', 0xb93a034d809a3c064005bffbcbdc83d98f528bf3, 0x6d1965a62720c56217969da42f3d4be3e4194a9c),
(45, 'icinga_command', 'snmp-storage', 'create', NULL, '{\"arguments\":{\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$snmp_v2$\"},\"-C\":{\"description\":\"Community name for the host\'s SNMP agent (implies v1 protocol)\",\"set_if\":\"$snmp_nocrypt$\",\"value\":\"$snmp_community$\"},\"-H\":{\"description\":\"Name or IP address of host to check\",\"value\":\"$snmp_address$\"},\"-L\":{\"description\":\"<authproto>,<privproto> - <Authentication protocol (md5|sha : default md5)>,<Priv protocole (des|aes : default des)>\",\"set_if\":\"$snmp_v3_use_authprotocol$\",\"value\":\"$snmp_authprotocol$\"},\"-X\":{\"description\":\"Priv password for snmpv3 (AuthPriv protocol)\",\"set_if\":\"$snmp_v3_use_privpass$\",\"value\":\"$snmp_privpass$\"},\"-c\":\"$snmp_crit$\",\"-e\":{\"description\":\"Select all storages except the one(s) selected by -m. No action on storage type selection.\",\"set_if\":\"$snmp_exclude$\"},\"-f\":{\"description\":\"Perfparse compatible output\",\"set_if\":\"$snmp_perf$\"},\"-l\":{\"description\":\"Login and auth password for snmpv3 authentication\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_login$\"},\"-m\":{\"description\":\"Name in description OID (can be mounpoints \'\\/home\' or \'Swap Space\'...)\",\"value\":\"$snmp_storage_name$\"},\"-o\":{\"description\":\"Max-size of the SNMP message, usefull in case of Too Long responses.\",\"value\":\"$snmp_storage_olength$\"},\"-p\":{\"description\":\"SNMP port (Default 161)\",\"value\":\"$snmp_port$\"},\"-q\":{\"description\":\"Storage type: Other, Ram, VirtualMemory, FixedDisk, RemovableDisk, FloppyDisk, CompactDisk, RamDisk, FlashMemory, or NetworkDisk\",\"value\":\"$snmp_storage_type$\"},\"-t\":{\"description\":\"Timeout for SNMP in seconds (Default: 5)\",\"value\":\"$snmp_timeout$\"},\"-w\":\"$snmp_warn$\",\"-x\":{\"description\":\"Priv password\",\"set_if\":\"$snmp_v3$\",\"value\":\"$snmp_password$\"}},\"command\":\"check_snmp_storage.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-storage\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmp_address\":\"$check_address$\",\"snmp_authprotocol\":\"md5,des\",\"snmp_community\":\"public\",\"snmp_crit\":90,\"snmp_exclude\":false,\"snmp_login\":\"snmpuser\",\"snmp_nocrypt\":true,\"snmp_perf\":true,\"snmp_storage_name\":\"^\\/$$\",\"snmp_timeout\":\"5\",\"snmp_v2\":false,\"snmp_v3\":false,\"snmp_v3_use_authprotocol\":false,\"snmp_v3_use_privpass\":false,\"snmp_warn\":80}}', 'yalh', '2026-09-03 00:35:39', 0x32bf59b580fa01d072b7fb3f402fc4b520c4a61b, 0xb93a034d809a3c064005bffbcbdc83d98f528bf3),
(46, 'icinga_command', 'dummy', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"dummy\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"dummy_state\":0,\"dummy_text\":\"Check was successful.\"}}', 'yalh', '2026-09-03 00:35:40', 0x7c28379d8c2049417ea727e4ec8b40584deeaf4f, 0x32bf59b580fa01d072b7fb3f402fc4b520c4a61b),
(47, 'icinga_command', 'elasticsearch', 'create', NULL, '{\"arguments\":{\"--failure-domain\":{\"description\":\"A comma-separated list of ElasticSearch attributes that make up your cluster\'s failure domain\",\"value\":\"$elasticsearch_failuredomain$\"},\"--host\":{\"description\":\"Hostname or network address to probe, defaults to \'localhost\'\",\"value\":\"$elasticsearch_host$\"},\"--master-nodes\":{\"description\":\"Issue a warning if the number of master-eligible nodes in the cluster drops below this number. By default, do not monitor the number of nodes in the cluster\",\"value\":\"$elasticsearch_masternodes$\"},\"--port\":{\"description\":\"TCP port to probe, defaults to 9200\",\"value\":\"$elasticsearch_port$\"},\"--prefix\":{\"description\":\"Optional prefix for the ElasticSearch API, defaults to \'\'\",\"value\":\"$elasticsearch_prefix$\"},\"--yellow-critical\":{\"description\":\"Instead of issuing a \'warning\' for a yellow cluster state, issue a \'critical\' alert\",\"set_if\":\"$elasticsearch_yellowcritical$\",\"value\":\"TRUE\"}},\"command\":\"check_elasticsearch\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"elasticsearch\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"elasticsearch_host\":\"$check_address$\",\"elasticsearch_yellowcritical\":false}}', 'yalh', '2026-09-03 00:35:40', 0x5ef9c1c3f58cf7142da0786589db8bfb45dba9f1, 0x7c28379d8c2049417ea727e4ec8b40584deeaf4f),
(48, 'icinga_command', 'snmp-uptime', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$snmp_extra_opts$\"},\"--invert-search\":{\"description\":\"Invert search result and return CRITICAL if found\",\"set_if\":\"$snmp_invert_search$\"},\"--offset\":{\"description\":\"Add\\/substract the specified OFFSET to numeric sensor data\",\"value\":\"$snmp_offset$\"},\"--rate\":{\"description\":\"Enable rate calculation\",\"set_if\":\"$snmp_rate$\"},\"--rate-multiplier\":{\"description\":\"Converts rate per second. For example, set to 60 to convert to per minute\",\"value\":\"$snmp_rate_multiplier$\"},\"-C\":{\"description\":\"Optional community string for SNMP communication (default is \'public\')\",\"value\":\"$snmp_community$\"},\"-D\":{\"description\":\"Separates output on multiple OID requests\",\"value\":\"$snmp_output_delimiter$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$snmp_address$\"},\"-M\":{\"description\":\"Multiplies current value, 0 < n < 1 works as divider, defaults to 1\",\"value\":\"$snmp_multiplier$\"},\"-O\":{\"description\":\"Label performance data with OIDs instead of --label\'s\",\"set_if\":\"$snmp_perf_oids$\"},\"-P\":{\"description\":\"SNMP protocol version\",\"value\":\"$snmp_version$\"},\"-R\":{\"description\":\"Return OK state (for that OID) if case-insensitive extended REGEX matches\",\"value\":\"$snmp_eregi$\"},\"-c\":{\"description\":\"Critical threshold range(s)\",\"value\":\"$snmp_crit$\"},\"-e\":{\"description\":\"Number of retries to be used in the requests\",\"value\":\"$snmp_retries$\"},\"-l\":{\"description\":\"Prefix label for output from plugin\",\"value\":\"$snmp_label$\"},\"-m\":{\"description\":\"List of MIBS to be loaded (default = none if using numeric OIDs or \'ALL\' for symbolic OIDs.)\",\"value\":\"$snmp_miblist$\"},\"-n\":{\"description\":\"Use SNMP GETNEXT instead of SNMP GET\",\"set_if\":\"$snmp_getnext$\"},\"-o\":{\"description\":\"Object identifier(s) or SNMP variables whose value you wish to query\",\"value\":\"$snmp_oid$\"},\"-p\":{\"description\":\"Port number (default: 161)\",\"value\":\"$snmp_port$\"},\"-r\":{\"description\":\"Return OK state (for that OID) if extended regular expression REGEX matches\",\"value\":\"$snmp_ereg$\"},\"-s\":{\"description\":\"Return OK state (for that OID) if STRING is an exact match\",\"value\":\"$snmp_string$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$snmp_timeout$\"},\"-u\":{\"description\":\"Units label(s) for output data (e.g., \'sec.\')\",\"value\":\"$snmp_units$\"},\"-w\":{\"description\":\"Warning threshold range(s)\",\"value\":\"$snmp_warn$\"}},\"command\":\"check_snmp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmp-uptime\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"snmp_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"snmp_community\":\"public\",\"snmp_invert_search\":false,\"snmp_oid\":\"1.3.6.1.2.1.1.3.0\",\"snmp_timeout\":\"10\"}}', 'yalh', '2026-09-03 00:35:40', 0x8f318324de94637f84d6444a04f99c1d3d7a98f1, 0x5ef9c1c3f58cf7142da0786589db8bfb45dba9f1),
(49, 'icinga_command', 'esxi_hardware', 'create', NULL, '{\"arguments\":{\"--format\":{\"description\":\"Set output format to string or json (defaults to string)\",\"value\":\"$esxi_hardware_format$\"},\"--no-current\":{\"description\":\"don\'t collect current performance data\",\"set_if\":\"$esxi_hardware_nocurrent$\"},\"--no-fan\":{\"description\":\"don\'t collect fan performance data\",\"set_if\":\"$esxi_hardware_nofan$\"},\"--no-lcd\":{\"description\":\"don\'t collect lcd\\/display status data\",\"set_if\":\"$esxi_hardware_nolcd$\"},\"--no-power\":{\"description\":\"don\'t collect power performance data\",\"set_if\":\"$esxi_hardware_nopower$\"},\"--no-temp\":{\"description\":\"don\'t collect temperature performance data\",\"set_if\":\"$esxi_hardware_notemp$\"},\"--no-volts\":{\"description\":\"don\'t collect voltage performance data\",\"set_if\":\"$esxi_hardware_novolts$\"},\"--pretty\":{\"description\":\"Show plugin output in a human readable format (in combination with --format json)\",\"set_if\":\"$esxi_hardware_pretty$\"},\"-C\":{\"description\":\"cim port\",\"value\":\"$esxi_hardware_port$\"},\"-H\":{\"description\":\"report on HOST\",\"value\":\"$esxi_hardware_host$\"},\"-I\":{\"description\":\"generate html links for country XX\",\"value\":\"$esxi_hardware_html$\"},\"-P\":{\"description\":\"password\",\"value\":\"$esxi_hardware_pass$\"},\"-S\":{\"description\":\"Overwrite system default of SSL\\/TLS protocol to use. Must be one of: SSLv2, SSLv3, TLSv1, TLSv1.1, TLSv1.2, TLSv1.3\",\"value\":\"$esxi_hardware_sslproto$\"},\"-U\":{\"description\":\"user to connect as\",\"value\":\"$esxi_hardware_user$\"},\"-V\":{\"description\":\"Vendor code: auto, dell, hp, ibm, intel, or unknown\",\"value\":\"$esxi_hardware_vendor$\"},\"-i\":{\"description\":\"comma-separated list of elements to ignore\",\"value\":\"$esxi_hardware_ignore$\"},\"-p\":{\"description\":\"collect performance data for pnp4nagios\",\"set_if\":\"$esxi_hardware_perfdata$\"},\"-r\":{\"description\":\"Allow regular expression lookups of elements in ignore list\",\"set_if\":\"$esxi_hardware_regex$\"}},\"command\":\"check_esxi_hardware.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"esxi_hardware\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"esxi_hardware_host\":\"$address$\",\"esxi_hardware_nocurrent\":false,\"esxi_hardware_nofan\":false,\"esxi_hardware_nolcd\":false,\"esxi_hardware_nopower\":false,\"esxi_hardware_notemp\":false,\"esxi_hardware_novolts\":false,\"esxi_hardware_perfdata\":false,\"esxi_hardware_port\":5989,\"esxi_hardware_regex\":false}}', 'yalh', '2026-09-03 00:35:40', 0x5c49f74ad94bb36ac55ce15fcd184877c776e0d4, 0x8f318324de94637f84d6444a04f99c1d3d7a98f1),
(50, 'icinga_command', 'exception', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"exception\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:40', 0xf308599b2d121e0f95d9293f5c3d68e049276e04, 0x5c49f74ad94bb36ac55ce15fcd184877c776e0d4),
(51, 'icinga_command', 'snmpv3', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$snmpv3_extra_opts$\"},\"--invert-search\":{\"description\":\"Invert search result and return CRITICAL if found\",\"set_if\":\"$snmpv3_invert_search$\"},\"--rate\":{\"description\":\"Enable rate calculation\",\"set_if\":\"$snmpv3_rate$\"},\"--rate-multiplier\":{\"description\":\"Converts rate per second. For example, set to 60 to convert to per minute\",\"value\":\"$snmpv3_rate_multiplier$\"},\"-A\":{\"description\":\"SNMPv3 authentication password\",\"value\":\"$snmpv3_auth_key$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$snmpv3_address$\"},\"-L\":{\"description\":\"SNMPv3 securityLevel\",\"value\":\"$snmpv3_seclevel$\"},\"-M\":{\"description\":\"Multiplies current value, 0 < n < 1 works as divider, defaults to 1\",\"value\":\"$snmpv3_multiplier$\"},\"-N\":{\"description\":\"SNMPv3 context\",\"value\":\"$snmpv3_context$\"},\"-P\":{\"description\":\"SNMP protocol version\",\"value\":3},\"-R\":{\"description\":\"Return OK state (for that OID) if case-insensitive extended REGEX matches\",\"value\":\"$snmpv3_eregi$\"},\"-U\":{\"description\":\"SNMPv3 username\",\"value\":\"$snmpv3_user$\"},\"-X\":{\"description\":\"SNMPv3 privacy password\",\"value\":\"$snmpv3_priv_key$\"},\"-a\":{\"description\":\"SNMPv3 auth proto\",\"value\":\"$snmpv3_auth_alg$\"},\"-c\":{\"description\":\"Critical threshold range(s)\",\"value\":\"$snmpv3_crit$\"},\"-l\":{\"description\":\"Prefix label for output from plugin\",\"value\":\"$snmpv3_label$\"},\"-m\":{\"description\":\"List of SNMP MIBs for translating OIDs between numeric and textual representation\",\"value\":\"$snmpv3_miblist$\"},\"-n\":{\"description\":\"Use SNMP GETNEXT instead of SNMP GET\",\"set_if\":\"$snmpv3_getnext$\"},\"-o\":{\"description\":\"Object identifier(s) or SNMP variables whose value you wish to query\",\"value\":\"$snmpv3_oid$\"},\"-p\":{\"description\":\"Port number\",\"value\":\"$snmpv3_port$\"},\"-r\":{\"description\":\"Return OK state (for that OID) if extended regular expression REGEX matches\",\"value\":\"$snmpv3_ereg$\"},\"-s\":{\"description\":\"Return OK state (for that OID) if STRING is an exact match\",\"value\":\"$snmpv3_string$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$snmpv3_timeout$\"},\"-u\":{\"description\":\"Units label(s) for output data (e.g., \'sec.\')\",\"value\":\"$snmpv3_units$\"},\"-w\":{\"description\":\"Warning threshold range(s)\",\"value\":\"$snmpv3_warn$\"},\"-x\":{\"description\":\"SNMPv3 priv proto (default DES)\",\"value\":\"$snmpv3_priv_alg$\"}},\"command\":\"check_snmp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"snmpv3\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"snmpv3_address\":\"$check_address$\",\"snmpv3_auth_alg\":\"SHA\",\"snmpv3_priv_alg\":\"AES\",\"snmpv3_seclevel\":\"authPriv\",\"snmpv3_timeout\":\"10\"}}', 'yalh', '2026-09-03 00:35:40', 0x04a3e63f7e221d8322a6905f69fcecf238b0b856, 0xf308599b2d121e0f95d9293f5c3d68e049276e04),
(52, 'icinga_command', 'fail2ban', 'create', NULL, '{\"arguments\":{\"-D\":{\"description\":\"To modify the output display, default is \'CHECK FAIL2BAN ACTIVITY\'\",\"value\":\"$fail2ban_display$\"},\"-P\":{\"description\":\"Specify the path to the tw_cli binary, default value is \\/usr\\/bin\\/fail2ban-client\",\"value\":\"$fail2ban_path$\"},\"-c\":{\"description\":\"Specify a critical threshold, default is 2\",\"value\":\"$fail2ban_critical$\"},\"-j\":{\"description\":\"Specify the name of the specific jail to monitor; omitted by default, i.e. all jails are being monitored\",\"value\":\"$fail2ban_jail$\"},\"-p\":{\"description\":\"If set to true, activate the perfdata output\",\"set_if\":\"$fail2ban_perfdata$\"},\"-s\":{\"description\":\"Specify a socket path, default is unset\",\"value\":\"$fail2ban_socket$\"},\"-w\":{\"description\":\"Specify a warning threshold, default is 1\",\"value\":\"$fail2ban_warning$\"}},\"command\":\"sudo \\/usr\\/lib\\/nagios\\/plugins\\/check_fail2ban\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"fail2ban\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"fail2ban_perfdata\":true}}', 'yalh', '2026-09-03 00:35:41', 0x6d1a5a1a46dc3d2bbcd75916569463a7a17bb7b2, 0x04a3e63f7e221d8322a6905f69fcecf238b0b856);
INSERT INTO `director_activity_log` (`id`, `object_type`, `object_name`, `action_name`, `old_properties`, `new_properties`, `author`, `change_time`, `checksum`, `parent_checksum`) VALUES
(53, 'icinga_command', 'spop', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$spop_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$spop_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$spop_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$spop_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$spop_certificate_age$\"},\"-E\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \\r\\n added to end of quit\",\"value\":\"$spop_escape$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$spop_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit (default: warn)\",\"value\":\"$spop_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$spop_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$spop_critical$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response\",\"value\":\"$spop_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated)\",\"value\":\"$spop_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$spop_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received\",\"value\":\"$spop_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$spop_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$spop_quit$\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit (default: crit)\",\"value\":\"$spop_refuse$\"},\"-s\":{\"description\":\"String to send to the server\",\"value\":\"$spop_send$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$spop_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$spop_warning$\"}},\"command\":\"check_spop\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"spop\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$spop_ipv4$\",\"check_ipv6\":\"$spop_ipv6$\",\"spop_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:41', 0xbdb1835e07424ae162214a3d6e13248b251e379d, 0x6d1a5a1a46dc3d2bbcd75916569463a7a17bb7b2),
(54, 'icinga_command', 'file_age', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"File must be at least this many bytes long (default: 0B)\",\"value\":\"$file_age_critical_size$\"},\"-W\":{\"description\":\"File must be at least this many bytes long\",\"value\":\"$file_age_warning_size$\"},\"-c\":{\"description\":\"File must be no more than this many seconds old (default: 600s)\",\"value\":\"$file_age_critical_time$\"},\"-f\":{\"description\":\"File to monitor\",\"value\":\"$file_age_file$\"},\"-i\":{\"description\":\"return OK if the file does not exist\",\"set_if\":\"$file_age_ignoremissing$\"},\"-w\":{\"description\":\"File must be no more than this many seconds old (default: 240s)\",\"value\":\"$file_age_warning_time$\"}},\"command\":\"check_file_age\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"file_age\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"file_age_ignoremissing\":false}}', 'yalh', '2026-09-03 00:35:41', 0xf0611999bcb972c0c3bd501676d67790a3ccac40, 0xbdb1835e07424ae162214a3d6e13248b251e379d),
(55, 'icinga_command', 'flexlm', 'create', NULL, '{\"arguments\":{\"-F\":{\"description\":\"Name of license file (usually license.dat)\",\"required\":true,\"value\":\"$flexlm_licensefile$\"},\"-t\":{\"description\":\"Plugin time out in seconds (default = 15)\",\"value\":\"$flexlm_timeout$\"}},\"command\":\"check_flexlm\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"flexlm\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:41', 0xfbf657adfece900f95f18ae70ae1452d004c4d1a, 0xf0611999bcb972c0c3bd501676d67790a3ccac40),
(56, 'icinga_command', 'squid', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Critical threshold. See http:\\/\\/nagiosplug.sourceforge.net\\/developer-guidelines.html#THRESHOLDFORMAT for the threshold format.\",\"value\":\"$squid_critical$\"},\"--data\":{\"description\":\"Optional data to fetch (default: Connections)    available data : Connections Cache Resources Memory FileDescriptors\",\"value\":\"$squid_data$\"},\"--host\":{\"description\":\"Name of the proxy to check (default: localhost)\",\"value\":\"$squid_hostname$\"},\"--password\":{\"description\":\"WWW password\",\"value\":\"$squid_password$\"},\"--port\":{\"description\":\"Optional port number (default: 3128)\",\"value\":\"$squid_port$\"},\"--squidclient\":{\"description\":\"Path of squidclient (default: \\/usr\\/bin\\/squidclient)\",\"value\":\"$squid_client$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 15)\",\"value\":\"$squid_timeout$\"},\"--user\":{\"description\":\"WWW user\",\"value\":\"$squid_user$\"},\"--warning\":{\"description\":\"Warning threshold. See http:\\/\\/nagiosplug.sourceforge.net\\/developer-guidelines.html#THRESHOLDFORMAT for the threshold format.\",\"value\":\"$squid_warning$\"}},\"command\":\"check_squid\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"squid\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"squid_client\":\"\\/usr\\/bin\\/squidclient\",\"squid_hostname\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:41', 0xfca51eb5a9a8c26d3ca5a3151fecafdf1ab92ade, 0xfbf657adfece900f95f18ae70ae1452d004c4d1a),
(57, 'icinga_command', 'fping', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$fping_extra_opts$\"},\"-I\":{\"description\":\"source interface name\",\"value\":\"$fping_source_interface$\"},\"-S\":{\"description\":\"name or IP Address of sourceip\",\"value\":\"$fping_source_ip$\"},\"-T\":{\"description\":\"Target timeout (ms) (default: fping\'s default for -t)\",\"value\":\"$fping_target_timeout$\"},\"-b\":{\"description\":\"size of ICMP packet (default: 56)\",\"value\":\"$fping_bytes$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$fping_crta$,$fping_cpl$%\"},\"-i\":{\"description\":\"Interval (ms) between sending packets (default: fping\'s default for -p)\",\"value\":\"$fping_interval$\"},\"-n\":{\"description\":\"number of ICMP packets to send (default: 1)\",\"value\":\"$fping_number$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$fping_wrta$,$fping_wpl$%\"}},\"command\":\"check_fping $fping_address$\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"fping\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"fping_address\":\"$check_address$\",\"fping_cpl\":15,\"fping_crta\":200,\"fping_interval\":500,\"fping_number\":5,\"fping_wpl\":5,\"fping_wrta\":100}}', 'yalh', '2026-09-03 00:35:41', 0x6ac252c7120b8a25dea707aaa27c244325a66d82, 0xfca51eb5a9a8c26d3ca5a3151fecafdf1ab92ade),
(58, 'icinga_command', 'ssh', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ssh_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$ssh_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$ssh_ipv4$\"},\"-P\":{\"description\":\"Alert if protocol doesn\'t match expected protocol version (ex: 2.0)\",\"value\":\"$ssh_remote_protocol$\"},\"-p\":{\"description\":\"Port number (default: 22)\",\"value\":\"$ssh_port$\"},\"-r\":{\"description\":\"Alert if string doesn\'t match expected server version (ex: OpenSSH_3.9p1)\",\"value\":\"$ssh_remote_version$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ssh_timeout$\"},\"host\":{\"skip_key\":true,\"value\":\"$ssh_address$\",\"order\":\"1\"}},\"command\":\"check_ssh\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ssh\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$ssh_ipv4$\",\"check_ipv6\":\"$ssh_ipv6$\",\"ssh_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:41', 0xeaf582e6e9f8f4932aa1bce7da46fd01d6dc6c7d, 0x6ac252c7120b8a25dea707aaa27c244325a66d82),
(59, 'icinga_command', 'fping4', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$fping_extra_opts$\"},\"-I\":{\"description\":\"source interface name\",\"value\":\"$fping_source_interface$\"},\"-S\":{\"description\":\"name or IP Address of sourceip\",\"value\":\"$fping_source_ip$\"},\"-T\":{\"description\":\"Target timeout (ms) (default: fping\'s default for -t)\",\"value\":\"$fping_target_timeout$\"},\"-b\":{\"description\":\"size of ICMP packet (default: 56)\",\"value\":\"$fping_bytes$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$fping_crta$,$fping_cpl$%\"},\"-i\":{\"description\":\"Interval (ms) between sending packets (default: fping\'s default for -p)\",\"value\":\"$fping_interval$\"},\"-n\":{\"description\":\"number of ICMP packets to send (default: 1)\",\"value\":\"$fping_number$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$fping_wrta$,$fping_wpl$%\"}},\"command\":\"check_fping $fping_address$ -4\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"fping4\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"fping_address\":\"$address$\",\"fping_cpl\":15,\"fping_crta\":200,\"fping_interval\":500,\"fping_number\":5,\"fping_wpl\":5,\"fping_wrta\":100}}', 'yalh', '2026-09-03 00:35:41', 0x522696191ae204252a08a1713361a4b7daa33cc2, 0xeaf582e6e9f8f4932aa1bce7da46fd01d6dc6c7d),
(60, 'icinga_command', 'ssl', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ssl_extra_opts$\"},\"--sni\":{\"description\":\"Enable SSL\\/TLS hostname extension support (SNI)\",\"value\":\"$ssl_sni$\"},\"--ssl\":{\"description\":\"Use SSL for the connection\"},\"-D\":{\"type\":\"Function\",\"body\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\"},\"-H\":{\"description\":\"Host address\",\"value\":\"$ssl_address$\"},\"-p\":{\"description\":\"TCP port (default: 443)\",\"value\":\"$ssl_port$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ssl_timeout$\"}},\"command\":\"check_tcp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ssl\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"ssl_address\":\"$check_address$\",\"ssl_cert_valid_days_critical\":false,\"ssl_cert_valid_days_warn\":false,\"ssl_port\":443}}', 'yalh', '2026-09-03 00:35:41', 0x62d8802873b14984515572621d159af3be37219b, 0x522696191ae204252a08a1713361a4b7daa33cc2),
(61, 'icinga_command', 'fping6', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$fping_extra_opts$\"},\"-I\":{\"description\":\"source interface name\",\"value\":\"$fping_source_interface$\"},\"-S\":{\"description\":\"name or IP Address of sourceip\",\"value\":\"$fping_source_ip$\"},\"-T\":{\"description\":\"Target timeout (ms) (default: fping\'s default for -t)\",\"value\":\"$fping_target_timeout$\"},\"-b\":{\"description\":\"size of ICMP packet (default: 56)\",\"value\":\"$fping_bytes$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$fping_crta$,$fping_cpl$%\"},\"-i\":{\"description\":\"Interval (ms) between sending packets (default: fping\'s default for -p)\",\"value\":\"$fping_interval$\"},\"-n\":{\"description\":\"number of ICMP packets to send (default: 1)\",\"value\":\"$fping_number$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$fping_wrta$,$fping_wpl$%\"}},\"command\":\"check_fping $fping_address$ -6\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"fping6\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"fping_address\":\"$address6$\",\"fping_cpl\":15,\"fping_crta\":200,\"fping_interval\":500,\"fping_number\":5,\"fping_wpl\":5,\"fping_wrta\":100}}', 'yalh', '2026-09-03 00:35:41', 0xf8afb96da7d056edcf2bfa0b60172181530b291b, 0x62d8802873b14984515572621d159af3be37219b),
(62, 'icinga_command', 'ftp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ftp_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$ftp_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$ftp_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$ftp_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid. 1st value is number of days for warning, 2nd is critical (if not specified: 0) - seperated by comma.\",\"value\":\"$ftp_certificate$\"},\"-E_quit\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in quit string. Default is \\r\\n added to end of quit.\",\"set_if\":\"$ftp_escape_quit$\",\"order\":\"3\"},\"-E_send\":{\"description\":\"Enable usage of \\n, \\r, \\t or \\\\ in send string. Default is nothing.\",\"set_if\":\"$ftp_escape_send$\",\"order\":\"1\"},\"-H\":{\"description\":\"The host\'s address. Defaults to $address$ or $address6$ if the address attribute is not set.\",\"value\":\"$ftp_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit. Defaults to warn.\",\"value\":\"$ftp_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$ftp_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds).\",\"value\":\"$ftp_ctime$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response.\",\"value\":\"$ftp_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated).\",\"value\":\"$ftp_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$ftp_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received.\",\"value\":\"$ftp_maxbytes$\"},\"-p\":{\"description\":\"The FTP port number. Defaults to none\",\"value\":\"$ftp_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection.\",\"value\":\"$ftp_quit$\",\"order\":\"4\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit. Defaults to crit.\",\"value\":\"$ftp_refuse$\"},\"-s\":{\"description\":\"String to send to the server.\",\"value\":\"$ftp_send$\",\"order\":\"2\"},\"-t\":{\"description\":\"Seconds before connection times out. Defaults to 10.\",\"value\":\"$ftp_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds).\",\"value\":\"$ftp_wtime$\"}},\"command\":\"check_ftp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ftp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$ftp_ipv4$\",\"check_ipv6\":\"$ftp_ipv6$\",\"ftp_address\":\"$check_address$\",\"ftp_mismatch\":\"warn\",\"ftp_refuse\":\"crit\",\"ftp_ssl\":false,\"ftp_timeout\":10}}', 'yalh', '2026-09-03 00:35:42', 0x1ce734267b28bc733b9d279c942842e4c75c183a, 0xf8afb96da7d056edcf2bfa0b60172181530b291b),
(63, 'icinga_command', 'ssl_cert', 'create', NULL, '{\"arguments\":{\"--clientpass\":{\"description\":\"Set passphrase for client certificate\",\"value\":\"$ssl_cert_clientpass$\"},\"--dane\":{\"description\":\"verify that valid DANE records exist (since OpenSSL 1.1.0)\",\"repeat_key\":false,\"value\":\"$ssl_cert_dane$\"},\"--ecdsa\":{\"description\":\"Cipher selection: force ECDSA authentication\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--ignore-exp\":{\"description\":\"Ignore expiration date\",\"set_if\":\"$ssl_cert_ignore_expiration$\"},\"--ignore-host-cn\":{\"description\":\"Do not complain if the CN does not match\",\"set_if\":\"$ssl_cert_ignore_host_cn$\"},\"--ignore-maximum-validity\":{\"description\":\"Ignore the certificate maximum validity\",\"set_if\":\"$ssl_cert_ignore_maximum_validity$\"},\"--ignore-ocsp\":{\"description\":\"Do not check revocation with OCSP\",\"set_if\":\"$ssl_cert_ignore_ocsp$\"},\"--ignore-ocsp-errors\":{\"description\":\"Continue if the OCSP status cannot be checked\",\"set_if\":\"$ssl_cert_ignore_ocsp_errors$\"},\"--ignore-ocsp-timeout\":{\"description\":\"Ignore OCSP result when timeout occurs while checking\",\"set_if\":\"$ssl_cert_ignore_ocsp_timeout$\"},\"--ignore-sct\":{\"description\":\"Do not check for signed certificate timestamps\",\"set_if\":\"$ssl_cert_ignore_sct$\"},\"--ignore-sig-alg\":{\"description\":\"Do not check if the certificate was signed with SHA1 od MD5\",\"set_if\":\"$ssl_cert_ignore_signature$\"},\"--ignore-ssl-labs-cache\":{\"description\":\"Forces a new check by SSL Labs\",\"set_if\":\"$ssl_cert_ssllabs_nocache$\"},\"--ignore-tls-renegotiation\":{\"description\":\"Do not check for renegotiation\",\"set_if\":\"$ssl_cert_ignore_tls_renegotiation$\"},\"--long-output\":{\"description\":\"Append the specified comma separated (no spaces) list of attributes to the plugin output on additional lines\",\"value\":\"$ssl_cert_long_output$\"},\"--match\":{\"description\":\"Pattern to match the CN or AltNames of the certificate\",\"value\":\"$ssl_cert_cn$\"},\"--maximum-validity\":{\"description\":\"The maximum validity of the certificate in days (default: 397)\",\"value\":\"$ssl_cert_maximum_validity$\"},\"--no_ssl2\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--no_ssl3\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--no_tls1\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--no_tls1_1\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--no_tls1_2\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--proxy\":{\"description\":\"Sets http_proxy and the s_client -proxy option\",\"value\":\"$ssl_cert_proxy$\"},\"--rsa\":{\"description\":\"Cipher selection: force RSA authentication\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--serial\":{\"description\":\"Pattern to match the serial number\",\"value\":\"$ssl_cert_serial$\"},\"--sni\":{\"description\":\"Sets the TLS SNI (Server Name Indication) extension\",\"value\":\"$ssl_cert_sni$\"},\"--ssl2\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--ssl3\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--tls1\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--tls1_1\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--tls1_2\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"--url\":{\"description\":\"HTTP request URL (default: \\/)\",\"value\":\"$ssl_cert_http_url$\"},\"-A\":{\"description\":\"Ignore authority warnings (expiration only)\",\"set_if\":\"$ssl_cert_noauth$\"},\"-C\":{\"description\":\"Use client certificate to authenticate\",\"value\":\"$ssl_cert_clientssl_cert$\"},\"-H\":{\"description\":\"The host\'s address\",\"required\":true,\"value\":\"$ssl_cert_address$\"},\"-L\":{\"description\":\"SSL Labs assestment\",\"value\":\"$ssl_cert_ssllabs$\"},\"-N\":{\"description\":\"Match CN with the host name\",\"set_if\":\"$ssl_cert_match_host$\"},\"-P\":{\"description\":\"Use the specific protocol {http|smtp|pop3|imap|ftp|xmpp|irc|ldap} (default: http)\",\"value\":\"$ssl_cert_protocol$\"},\"-c\":{\"description\":\"Minimum number of days a certificate has to be valid to issue a critical status\",\"value\":\"$ssl_cert_critical$\"},\"-e\":{\"description\":\"Pattern to match the email address contained in the certificate\",\"value\":\"$ssl_cert_email$\"},\"-f\":{\"description\":\"Local file path (works with -H localhost only)\",\"value\":\"$ssl_cert_file$\"},\"-i\":{\"description\":\"Pattern to match the issuer of the certificate\",\"value\":\"$ssl_cert_issuer$\"},\"-o\":{\"description\":\"Pattern to match the organization of the certificate\",\"value\":\"$ssl_cert_org$\"},\"-p\":{\"description\":\"TCP port number (default: 443)\",\"value\":\"$ssl_cert_port$\"},\"-r\":{\"description\":\"Root certificate or directory to be used for certificate validation\",\"value\":\"$ssl_cert_rootssl_cert$\"},\"-s\":{\"description\":\"Allow self-signed certificate\",\"set_if\":\"$ssl_cert_selfsigned$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 15)\",\"value\":\"$ssl_cert_timeout$\"},\"-w\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$ssl_cert_warn$\"}},\"command\":\"check_ssl_cert\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ssl_cert\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"ssl_cert_address\":\"$check_address$\",\"ssl_cert_cn\":\"$ssl_cert_altnames$\",\"ssl_cert_port\":443}}', 'yalh', '2026-09-03 00:35:42', 0x0755f63a1b3846efc4261bb27649118a20065d3d, 0x1ce734267b28bc733b9d279c942842e4c75c183a),
(64, 'icinga_command', 'game', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$game_extra_opts$\"},\"-G\":{\"description\":\"Field number in raw qstat output that contains game time\",\"value\":\"$game_gametime$\"},\"-H\":{\"description\":\"Name of the host running the game\",\"value\":\"$game_hostname$\"},\"-P\":{\"description\":\"Port to connect to\",\"value\":\"$game_port$\"},\"-g\":{\"description\":\"Field number in raw qstat output that contains game name\",\"value\":\"$game_gamefield$\"},\"-m\":{\"description\":\"Field number in raw qstat output that contains map name\",\"value\":\"$game_mapfield$\"},\"-p\":{\"description\":\"Field number in raw qstat output that contains ping time\",\"value\":\"$game_pingfield$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$game_timeout$\"},\"game\":{\"description\":\"Name of the game\",\"skip_key\":true,\"value\":\"$game_game$\",\"order\":\"1\"},\"ipaddress\":{\"description\":\"Ipaddress of the game server to query\",\"skip_key\":true,\"value\":\"$game_ipaddress$\",\"order\":\"2\"}},\"command\":\"check_game\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"game\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false}}', 'yalh', '2026-09-03 00:35:42', 0xd757b06c1f35b101afa7c2d0c93e11f5c187476d, 0x0755f63a1b3846efc4261bb27649118a20065d3d),
(65, 'icinga_command', 'ssmtp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ssmtp_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$ssmtp_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$ssmtp_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$ssmtp_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$ssmtp_certificate_age$\"},\"-E\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \\r\\n added to end of quit\",\"value\":\"$ssmtp_escape$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$ssmtp_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit (default: warn)\",\"value\":\"$ssmtp_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$ssmtp_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$ssmtp_critical$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response\",\"value\":\"$ssmtp_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated)\",\"value\":\"$ssmtp_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$ssmtp_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received\",\"value\":\"$ssmtp_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$ssmtp_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$ssmtp_quit$\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit (default: crit)\",\"value\":\"$ssmtp_refuse$\"},\"-s\":{\"description\":\"String to send to the server\",\"value\":\"$ssmtp_send$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ssmtp_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$ssmtp_warning$\"}},\"command\":\"check_ssmtp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ssmtp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$ssmtp_ipv4$\",\"check_ipv6\":\"$ssmtp_ipv6$\",\"ssmtp_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:42', 0x3bd48cc0d72527ca4eed029bf3ead71bd0164f4a, 0xd757b06c1f35b101afa7c2d0c93e11f5c187476d),
(66, 'icinga_command', 'glusterfs', 'create', NULL, '{\"arguments\":{\"--perfdata\":{\"description\":\"Optional. Print perfdata of all or the specified volume.\",\"set_if\":\"$glusterfs_perfdata$\"},\"--volume\":{\"description\":\"Optional. Only check the specified *VOLUME*. If --volume is not set, all volumes are checked.\",\"value\":\"$glusterfs_volume$\"},\"--warnonfailedheal\":{\"description\":\"Optional. Warn if the *heal-failed* log contains entries. The log can be cleared by restarting glusterd.\",\"set_if\":\"$glusterfs_warnonfailedheal$\"},\"-C\":{\"description\":\"Optional. Return a critical error if inode usage is above *DISKCRIT*. Defaults to 95 (percent).\",\"value\":\"$glusterfs_inode_critical$\"},\"-W\":{\"description\":\"Optional. Warn if inode usage is above *DISKWARN*. Defaults to 90 (percent).\",\"value\":\"$glusterfs_inode_warning$\"},\"-c\":{\"description\":\"Optional. Return a critical error if disk usage is above *DISKCRIT*. Defaults to 95 (percent).\",\"value\":\"$glusterfs_disk_critical$\"},\"-w\":{\"description\":\"Optional. Warn if disk usage is above *DISKWARN*. Defaults to 90 (percent).\",\"value\":\"$glusterfs_disk_warning$\"}},\"command\":\"sudo \\/usr\\/lib\\/nagios\\/plugins\\/check_glusterfs\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"glusterfs\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"glusterfs_disk_critical\":95,\"glusterfs_disk_warning\":90,\"glusterfs_inode_critical\":95,\"glusterfs_inode_warning\":90}}', 'yalh', '2026-09-03 00:35:43', 0xd16d8570d22b5224fe4a4cd3b8d34c22f9af222d, 0x3bd48cc0d72527ca4eed029bf3ead71bd0164f4a),
(67, 'icinga_command', 'swap', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$swap_extra_opts$\"},\"-a\":{\"description\":\"Conduct comparisons for all swap partitions, one by one\",\"set_if\":\"$swap_allswaps$\"},\"-c\":{\"type\":\"Function\",\"body\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\"},\"-n\":{\"description\":\"Resulting state when there is no swap regardless of thresholds. Possible values are \\\"ok\\\", \\\"warning\\\", \\\"critical\\\", \\\"unknown\\\". Defaults to \\\"critical\\\"\",\"value\":\"$swap_noswap$\"},\"-w\":{\"type\":\"Function\",\"body\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\"}},\"command\":\"check_swap\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"swap\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"swap_allswaps\":false,\"swap_cfree\":25,\"swap_integer\":false,\"swap_wfree\":50}}', 'yalh', '2026-09-03 00:35:43', 0xc124e826afc33fe5f08a62607aea1a81bf47cb79, 0xd16d8570d22b5224fe4a4cd3b8d34c22f9af222d),
(68, 'icinga_command', 'graphite', 'create', NULL, '{\"arguments\":{\"-M\":{\"description\":\"Text message to output (default: \'metric count:\')\",\"value\":\"$graphite_message$\"},\"-U\":{\"description\":\"Adds a text tag to the metric count in the plugin output. Useful to identify the metric units. Doesn\'t affect data queries.\",\"value\":\"$graphite_units$\"},\"-c\":{\"description\":\"Critical threshold\",\"required\":true,\"value\":\"$graphite_critical$\"},\"-d\":{\"description\":\"Length, in minute of data to parse (default: 5)\",\"value\":\"$graphite_duration$\"},\"-f\":{\"description\":\"Function applied to metrics for thresholds (default: average)\",\"value\":\"$graphite_function$\"},\"-l\":{\"description\":\"Add a link in the plugin output, showing a 24h graph for this metric in graphite.\",\"set_if\":\"$graphite_link_graph$\"},\"-m\":{\"description\":\"Metric path string\",\"required\":true,\"value\":\"$graphite_metric$\"},\"-s\":{\"description\":\"Metric short name (used for performance data)\",\"value\":\"$graphite_shortname$\"},\"-u\":{\"description\":\"Target url\",\"required\":true,\"value\":\"$graphite_url$\"},\"-w\":{\"description\":\"Warning threshold\",\"required\":true,\"value\":\"$graphite_warning$\"},\"-z\":{\"description\":\"Return 0 on a graphite 500 error\",\"set_if\":\"$graphite_zero_on_error$\"}},\"command\":\"check_graphite\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"graphite\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"graphite_duration\":\"5\",\"graphite_function\":\"average\",\"graphite_link_graph\":false,\"graphite_message\":\"metric count:\",\"graphite_zero_on_error\":false}}', 'yalh', '2026-09-03 00:35:43', 0x6a65911d73770ef926f4f9b1efda9d73af864bde, 0xc124e826afc33fe5f08a62607aea1a81bf47cb79),
(69, 'icinga_command', 'swap-windows', 'create', NULL, '{\"arguments\":{\"-U\":{\"description\":\"Show used swap instead of the free swap\",\"set_if\":\"$swap_win_show_used$\"},\"-c\":{\"description\":\"Critical threshold\",\"value\":\"$swap_win_crit$\"},\"-u\":{\"description\":\"Unit to display swap in\",\"value\":\"$swap_win_unit$\"},\"-w\":{\"description\":\"Warning threshold\",\"value\":\"$swap_win_warn$\"}},\"command\":\"check_swap.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"swap-windows\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"swap_win_crit\":\"5%\",\"swap_win_unit\":\"mb\",\"swap_win_warn\":\"10%\"}}', 'yalh', '2026-09-03 00:35:43', 0x2fbc949de191ad87c6c33079822ba48a209296a9, 0x6a65911d73770ef926f4f9b1efda9d73af864bde),
(70, 'icinga_command', 'haproxy', 'create', NULL, '{\"arguments\":{\"--password\":{\"description\":\"Password for HTTP Auth\",\"value\":\"$haproxy_password$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 10)\",\"value\":\"$haproxy_timeout$\"},\"--url\":{\"description\":\"URL of the HAProxy csv statistics page\",\"required\":true,\"value\":\"$haproxy_url$\"},\"--username\":{\"description\":\"Username for HTTP Auth\",\"value\":\"$haproxy_username$\"},\"-c\":{\"description\":\"Critical request time threshold (in seconds)\",\"value\":\"$haproxy_critical$\"},\"-w\":{\"description\":\"Warning request time threshold (in seconds)\",\"value\":\"$haproxy_warning$\"}},\"command\":\"check_haproxy\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"haproxy\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:43', 0x868adb9898e44eda0f3092dacaee78af66388683, 0x2fbc949de191ad87c6c33079822ba48a209296a9),
(71, 'icinga_command', 'systemd', 'create', NULL, '{\"arguments\":{\"--cli\":{\"description\":\"Use text output from parsing command output. (Default)\",\"set_if\":\"$systemd_cli$\"},\"--critical\":{\"description\":\"Startup time in seconds to result in a critical status. (Default 120 seconds)\",\"value\":\"$systemd_critical$\"},\"--dbus\":{\"description\":\"Use systemd\'s D-Bus API instead of parsing command output. Only partially implemented!\",\"set_if\":\"$systemd_dbus$\"},\"--dead-timers\":{\"description\":\"Detect dead \\/ inactive timers, see `systemd_dead_timers_{warning,critical}`. (Default `false`)\",\"set_if\":\"$systemd_dead_timers$\"},\"--dead-timers-critical\":{\"description\":\"Time ago in seconds for dead \\/ inactive timers to trigger a critical state. (Default 7 days)\",\"value\":\"$systemd_dead_timers_critical$\"},\"--dead-timers-warning\":{\"description\":\"Time ago in seconds for dead \\/ inactive timers to trigger a warning state. (Default 6 days)\",\"value\":\"$systemd_dead_timers_warning$\"},\"--exclude\":{\"description\":\"Exclude a systemd unit from the checks, regular expressions are supported. This option can be applied multiple times.\",\"repeat_key\":true,\"value\":\"$systemd_exclude_unit$\"},\"--exclude-type\":{\"description\":\"Exclude a systemd unit type (for example: `service`, `timer`)\",\"value\":\"$systemd_exclude_type$\"},\"--exclude-unit\":{\"description\":\"Exclude a systemd unit from the checks. This option can be applied multiple times.\",\"repeat_key\":true,\"value\":\"$systemd_exclude_unit_name$\"},\"--ignore-inactive-state\":{\"description\":\"Ignore an inactive state on a specific unit. Only affective if used with `systemd_unit`.\",\"set_if\":\"$systemd_ignore_inactive_state$\"},\"--include\":{\"description\":\"Include systemd units to the checks, regular expressions are supported. This option can be applied multiple times.\",\"repeat_key\":true,\"value\":\"$systemd_include$\"},\"--include-type\":{\"description\":\"Unit types to be tested (for example: `service`, `timer`). This option can be applied multiple times.\",\"repeat_key\":true,\"value\":\"$systemd_include_type$\"},\"--no-startup-time\":{\"description\":\"Don\'t check the startup time. Using this option, the options `systemd_{warning,critical}` have no effect. (Default `false`)\",\"set_if\":\"$systemd_no_startup_time$\"},\"--state\":{\"description\":\"Specify the active state that the systemd unit must have (for example: `active`, `inactive`)\",\"value\":\"$systemd_state$\"},\"--unit\":{\"description\":\"Name of the systemd unit that is being tested.\",\"value\":\"$systemd_unit$\"},\"--user\":{\"description\":\"Also show user (systemctl --user) units.\",\"set_if\":\"$systemd_user$\"},\"--warning\":{\"description\":\"Startup time in seconds to result in a warning status. (Default 60 seconds)\",\"value\":\"$systemd_warning$\"},\"-v\":{\"description\":\"Increase verbosity level (Accepted values: `1`, `2` or `3`). Defaults to none.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"-vv\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"},\"-vvv\":{\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\"}},\"command\":\"check_systemd\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"systemd\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:43', 0x8b2f2296bc46368ed540c28d47fc2513f2b5206b, 0x868adb9898e44eda0f3092dacaee78af66388683),
(72, 'icinga_command', 'haproxy_status', 'create', NULL, '{\"arguments\":{\"--backends\":{\"description\":\"Enable checks for the backends in HAProxy (that they have the required quorum of servers, and that the session limits haven\'t been reached).\",\"set_if\":\"$haproxy_status_backends$\"},\"--defaults\":{\"description\":\"Set\\/Override the defaults which will be applied to all checks (unless specifically set by --overrides).\",\"value\":\"$haproxy_status_default$\"},\"--frontends\":{\"description\":\"Enable checks for the frontends in HAProxy (that they\'re marked as OPEN and the session limits haven\'t been reached).\",\"set_if\":\"$haproxy_status_frontends$\"},\"--nobackends\":{\"description\":\"Disable checks for the backends in HAProxy (that they have the required quorum of servers, and that the session limits haven\'t been reached).\",\"set_if\":\"$haproxy_status_nobackends$\"},\"--nofrontends\":{\"description\":\"Disable checks for the frontends in HAProxy (that they\'re marked as OPEN and the session limits haven\'t been reached).\",\"set_if\":\"$haproxy_status_nofrontends$\"},\"--noservers\":{\"description\":\"Disable checks for the servers in HAProxy (that they haven\'t reached the limits for the sessions or for queues).\",\"set_if\":\"$haproxy_status_noservers$\"},\"--overrides\":{\"description\":\"Override the defaults for a particular frontend or backend, in the form {name}:{override}, where {override} is the same format as --defaults above.\",\"value\":\"$haproxy_status_overrides$\"},\"--servers\":{\"description\":\"Enable checks for the servers in HAProxy (that they haven\'t reached the limits for the sessions or for queues).\",\"set_if\":\"$haproxy_status_servers$\"},\"--socket\":{\"description\":\"Path to the socket check_haproxy should connect to\",\"required\":true,\"value\":\"$haproxy_status_socket$\"}},\"command\":\"check_haproxy_status\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"haproxy_status\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:43', 0x8c1db5562984a876e15f1e91273a29eec72a7a7b, 0x8b2f2296bc46368ed540c28d47fc2513f2b5206b),
(73, 'icinga_command', 'tcp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$tcp_extra_opts$\"},\"--sni\":{\"description\":\"Hostname to send in the server_name (SNI) SSL\\/TLS extension.\",\"value\":\"$tcp_sni$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$tcp_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$tcp_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Defaults to false.\",\"set_if\":\"$tcp_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid. 1st value is number of days for warning, 2nd is critical (if not specified: 0) - seperated by comma.\",\"value\":\"$tcp_certificate$\"},\"-E_quit\":{\"description\":\"Enable usage of \\n, \\r, \\t or \\\\ in quit string.\",\"set_if\":\"$tcp_escape_quit$\",\"order\":\"3\"},\"-E_send\":{\"description\":\"Enable usage of \\n, \\r, \\t or \\\\ in send string.\",\"set_if\":\"$tcp_escape_send$\",\"order\":\"1\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path).\",\"value\":\"$tcp_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit. Defaults to warn.\",\"value\":\"$tcp_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$tcp_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds).\",\"value\":\"$tcp_ctime$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response.\",\"value\":\"$tcp_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated).\",\"value\":\"$tcp_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$tcp_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received.\",\"value\":\"$tcp_maxbytes$\"},\"-p\":{\"description\":\"The TCP port number.\",\"value\":\"$tcp_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection.\",\"value\":\"$tcp_quit$\",\"order\":\"4\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit. Defaults to crit.\",\"value\":\"$tcp_refuse$\"},\"-s\":{\"description\":\"String to send to the server.\",\"value\":\"$tcp_send$\",\"order\":\"2\"},\"-t\":{\"description\":\"Seconds before connection times out. Defaults to 10.\",\"value\":\"$tcp_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds).\",\"value\":\"$tcp_wtime$\"}},\"command\":\"check_tcp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"tcp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$tcp_ipv4$\",\"check_ipv6\":\"$tcp_ipv6$\",\"tcp_address\":\"$check_address$\",\"tcp_all\":false,\"tcp_mismatch\":\"warn\",\"tcp_refuse\":\"crit\",\"tcp_timeout\":10}}', 'yalh', '2026-09-03 00:35:43', 0x7c75458ecd667859119b6950b4330cdf24c17f14, 0x8c1db5562984a876e15f1e91273a29eec72a7a7b),
(74, 'icinga_command', 'hddtemp', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"critical temperature\",\"required\":true,\"value\":\"$hddtemp_critical$\"},\"--devices\":{\"description\":\"comma separated devices list, or empty for all devices in hddtemp response\",\"value\":\"$hddtemp_devices$\"},\"--performance-data\":{\"description\":\"return performance data\",\"set_if\":\"$hddtemp_performance$\"},\"--port\":{\"description\":\"port number\",\"value\":\"$hddtemp_port$\"},\"--quiet\":{\"description\":\"be quiet\",\"set_if\":\"$hddtemp_quiet$\"},\"--separator\":{\"description\":\"hddtemp separator\",\"value\":\"$hddtemp_separator$\"},\"--server\":{\"description\":\"server name or address\",\"required\":true,\"value\":\"$hddtemp_server$\"},\"--timeout\":{\"description\":\"receiving data from hddtemp operation network timeout\",\"value\":\"$hddtemp_timeout$\"},\"--warning\":{\"description\":\"warning temperature\",\"required\":true,\"value\":\"$hddtemp_warning$\"}},\"command\":\"check_hddtemp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"hddtemp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"hddtemp_critical\":60,\"hddtemp_performance\":true,\"hddtemp_server\":\"127.0.0.1\",\"hddtemp_timeout\":5,\"hddtemp_warning\":55}}', 'yalh', '2026-09-03 00:35:43', 0xddb98df888c49ee7e4696ace2d564a64843a5fac, 0x7c75458ecd667859119b6950b4330cdf24c17f14),
(75, 'icinga_command', 'thola-cpu-load', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Critical threshold for the CPU load in %\",\"value\":\"$thola_cpu_load_critical$\"},\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"--warning\":{\"description\":\"Warning threshold for the CPU load in %\",\"value\":\"$thola_cpu_load_warning$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check cpu-load\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-cpu-load\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:44', 0x1d63e4c3fdc0f3a88eca6b32f632e143cb2f3b3a, 0xddb98df888c49ee7e4696ace2d564a64843a5fac),
(76, 'icinga_command', 'thola-hardware-health', 'create', NULL, '{\"arguments\":{\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check hardware-health\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-hardware-health\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:44', 0x64e91032cef1220d2a8689a4cc4cda9887ae45ba, 0x1d63e4c3fdc0f3a88eca6b32f632e143cb2f3b3a),
(77, 'icinga_command', 'hostalive', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ping_extra_opts$\"},\"-H\":{\"description\":\"host to ping\",\"value\":\"$ping_address$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$ping_crta$,$ping_cpl$%\"},\"-p\":{\"description\":\"number of ICMP ECHO packets to send (Default: 5)\",\"value\":\"$ping_packets$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ping_timeout$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$ping_wrta$,$ping_wpl$%\"}},\"command\":\"check_ping\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"hostalive\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"ping_address\":\"$check_address$\",\"ping_cpl\":100,\"ping_crta\":5000,\"ping_wpl\":80,\"ping_wrta\":3000}}', 'yalh', '2026-09-03 00:35:44', 0x851823c36cd1e47cfe38dde5b5340ccaf978b8c0, 0x64e91032cef1220d2a8689a4cc4cda9887ae45ba),
(78, 'icinga_command', 'hostalive4', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ping_extra_opts$\"},\"-H\":{\"description\":\"host to ping\",\"value\":\"$ping_address$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$ping_crta$,$ping_cpl$%\"},\"-p\":{\"description\":\"number of ICMP ECHO packets to send (Default: 5)\",\"value\":\"$ping_packets$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ping_timeout$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$ping_wrta$,$ping_wpl$%\"}},\"command\":\"check_ping -4\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"hostalive4\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"ping_address\":\"$address$\",\"ping_cpl\":100,\"ping_crta\":5000,\"ping_wpl\":80,\"ping_wrta\":3000}}', 'yalh', '2026-09-03 00:35:44', 0x43330d230c4a5b161b88b75e2f394ad138c00545, 0x851823c36cd1e47cfe38dde5b5340ccaf978b8c0);
INSERT INTO `director_activity_log` (`id`, `object_type`, `object_name`, `action_name`, `old_properties`, `new_properties`, `author`, `change_time`, `checksum`, `parent_checksum`) VALUES
(79, 'icinga_command', 'thola-identify', 'create', NULL, '{\"arguments\":{\"--model\":{\"description\":\"Model that is compared to the actual model of the device\",\"value\":\"$thola_identify_model$\"},\"--os-version\":{\"description\":\"OS-version that is compared to the actual OS-version of the device\",\"value\":\"$thola_identify_os_version$\"},\"--serial-number\":{\"description\":\"Serial number that is compared to the actual serial number of the device\",\"value\":\"$thola_identify_serial_number$\"},\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-discover-retries\":{\"description\":\"Number of discover retries\",\"value\":\"$thola_identify_discover_retries$\"},\"--snmp-discover-timeout\":{\"description\":\"Number of discover timeouts\",\"value\":\"$thola_identify_discover_timeouts$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"--vendor\":{\"description\":\"Vendor that is compared to the actual vendor of the device\",\"value\":\"$thola_identify_vendor$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check identify\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-identify\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:44', 0x5407e58bbbfa56fdcb9437e42282d7948c35da5f, 0x43330d230c4a5b161b88b75e2f394ad138c00545),
