(81, 'icinga_command', 'hostalive6', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ping_extra_opts$\"},\"-H\":{\"description\":\"host to ping\",\"value\":\"$ping_address$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$ping_crta$,$ping_cpl$%\"},\"-p\":{\"description\":\"number of ICMP ECHO packets to send (Default: 5)\",\"value\":\"$ping_packets$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ping_timeout$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$ping_wrta$,$ping_wpl$%\"}},\"command\":\"check_ping -6\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"hostalive6\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"ping_address\":\"$address6$\",\"ping_cpl\":100,\"ping_crta\":5000,\"ping_wpl\":80,\"ping_wrta\":3000}}', 'yalh', '2026-09-03 00:35:44', 0x081cd901247a564a873b6b6b28220e6c0c93c085, 0x79db2083be303faa28b47d4351b0b164e914efaf),
(82, 'icinga_command', 'thola-memory-usage', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Critical threshold for the memory usage in %\",\"value\":\"$thola_memory_usage_critical$\"},\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"--warning\":{\"description\":\"Warning threshold for the memory usage in %\",\"value\":\"$thola_memory_usage_warning$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check memory-usage\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-memory-usage\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:44', 0x9cc92a0f12b81196dd5c20da64f3bec451633974, 0x081cd901247a564a873b6b6b28220e6c0c93c085),
(83, 'icinga_command', 'hpasm', 'create', NULL, '{\"arguments\":{\"--authpassword\":{\"description\":\"The authentication password for SNMPv3\",\"value\":\"$hpasm_authpassword$\"},\"--authprotocol\":{\"description\":\"The authentication protocol for SNMPv3 (md5|sha)\",\"value\":\"$hpasm_authprotocol$\"},\"--blacklist\":{\"description\":\"Blacklist some (missing\\/failed) components\",\"value\":\"$hpasm_blacklist$\"},\"--community\":{\"description\":\"SNMP community of the server (SNMP v1\\/2 only)\",\"value\":\"$hpasm_community$\"},\"--customthresholds\":{\"description\":\"Use custom thresholds for certain temperatures\",\"value\":\"$hpasm_customthresholds$\"},\"--eval-nics\":{\"description\":\"Check network interfaces (and groups). Try it and report me whyt you think about it. I need to build up some know how on this subject. If get an error and you think, it is not justified for your configuration, please tell me about it. (alwasy send the output of \\\"snmpwalk -On .... 1.3.6.1.4.1.232\\\" and a description how you setup your nics and why it is correct opposed to the plugins error message\",\"set_if\":\"$hpasm_eval-nics$\"},\"--eventrange\":{\"description\":\"Period of time before critical IML events respecively become warnings or vanish. A range is descibed as a number and a unit (s, m, h, d), e.g. --eventrange 1h\\/20m.\",\"value\":\"$hpasm_eventrange$\"},\"--hostname\":{\"description\":\"Hostname or IP-address of the server (SNMP mode only)\",\"set_if\":\"$hpasm_remote$\",\"value\":\"$hpasm_hostname$\"},\"--ignore-dimms\":{\"description\":\"Ignore \\\"N\\/A\\\"-DIMM status on misc. servers (e.g. older DL320)\",\"set_if\":\"$hpasm_ignore-dimms$\"},\"--ignore-fan-redundancy\":{\"description\":\"Ignore missing redundancy partners\",\"set_if\":\"$hpasm_ignore-fan-redundancy$\"},\"--perfdata\":{\"description\":\"Output performance data. If your performance data string becomes too long and is truncated by Nagios, then you can use --perfdata=short instead. This will output temperature tags without location information\",\"value\":\"$hpasm_perfdata$\"},\"--port\":{\"description\":\"The SNMP port to use (default: 161)\",\"value\":\"$hpasm_port$\"},\"--privpassword\":{\"description\":\"The password for authPriv security level\",\"value\":\"$hpasm_privpassword$\"},\"--privprotocol\":{\"description\":\"The private protocol for SNMPv3 (des|aes|aes128|3des|3desde)\",\"value\":\"$hpasm_privprotocol$\"},\"--protocol\":{\"description\":\"The SNMP protocol to use (default: 2c, other possibilities: 1,3)\",\"value\":\"$hpasm_protocol$\"},\"--servertype\":{\"description\":\"The type of the server: proliant (default) or bladesystem\",\"value\":\"$hpasm_servertype$\"},\"--username\":{\"description\":\"The securityName for the USM security model (SNMPv3 only)\",\"value\":\"$hpasm_username$\"}},\"command\":\"check_hpasm\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"hpasm\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"hpasm_hostname\":\"$check_address$\",\"hpasm_remote\":true}}', 'yalh', '2026-09-03 00:35:44', 0x71094febc27e7d20b9ed6df17198fc04b4b2d479, 0x9cc92a0f12b81196dd5c20da64f3bec451633974),
