(85, 'icinga_command', 'thola-sbc', 'create', NULL, '{\"arguments\":{\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--system-health-score-critical\":{\"description\":\"Critical threshold for the health score in %\",\"value\":\"$thola_sbc_system_health_score_critical$\"},\"--system-health-score-warning\":{\"description\":\"Warning threshold for the health score in %\",\"value\":\"$thola_sbc_system_health_score_warning$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check sbc\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-sbc\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:45', 0x6f7d1a761fb9177480218f2ec8024be4a5691776, 0x9430c96a4241f0f4377c4fa079ccbdbdabc0b8b0),
