(87, 'icinga_command', 'thola-ups', 'create', NULL, '{\"arguments\":{\"--batt-current-critical-max\":{\"description\":\"High critical threshold for the battery current in Volt\",\"value\":\"$thola_ups_batt_current_critical_max$\"},\"--batt-current-critical-min\":{\"description\":\"Low critical threshold for the battery current in Volt\",\"value\":\"$thola_ups_batt_current_critical_min$\"},\"--batt-current-warning-max\":{\"description\":\"High warning threshold for the battery current in Volt\",\"value\":\"$thola_ups_batt_current_warning_max$\"},\"--batt-current-warning-min\":{\"description\":\"Low warning threshold for the battery current in Volt\",\"value\":\"$thola_ups_batt_current_warning_min$\"},\"--batt-temperature-critical-max\":{\"description\":\"High critical threshold for the battery temperature in degree celsius\",\"value\":\"$thola_ups_batt_temperature_critical_max$\"},\"--batt-temperature-critical-min\":{\"description\":\"Low critical threshold for the battery temperature in degree celsius\",\"value\":\"$thola_ups_batt_temperature_critical_min$\"},\"--batt-temperature-warning-max\":{\"description\":\"High warning threshold for the battery temperature in degree celsius\",\"value\":\"$thola_ups_batt_temperature_warning_max$\"},\"--batt-temperature-warning-min\":{\"description\":\"Low warning threshold for the battery temperature in degree celsius\",\"value\":\"$thola_ups_batt_temperature_warning_min$\"},\"--current-load-critical-max\":{\"description\":\"High critical threshold for the current load in %\",\"value\":\"$thola_ups_current_load_critical_max$\"},\"--current-load-critical-min\":{\"description\":\"Low critical threshold for the current load in %\",\"value\":\"$thola_ups_current_load_critical_min$\"},\"--current-load-warning-max\":{\"description\":\"High warning threshold for the current load in %\",\"value\":\"$thola_ups_current_load_warning_max$\"},\"--current-load-warning-min\":{\"description\":\"Low warning threshold for the current load in %\",\"value\":\"$thola_ups_current_load_warning_min$\"},\"--rectifier-current-critical-max\":{\"description\":\"High critical threshold for the current rectifier in Volt\",\"value\":\"$thola_ups_rectifier_current_critical_max$\"},\"--rectifier-current-critical-min\":{\"description\":\"Low critical threshold for the current rectifier in Volt\",\"value\":\"$thola_ups_rectifier_current_critical_min$\"},\"--rectifier-current-warning-max\":{\"description\":\"High warning threshold for the current rectifier in Volt\",\"value\":\"$thola_ups_rectifier_current_warning_max$\"},\"--rectifier-current-warning-min\":{\"description\":\"Low warning threshold for the current rectifier in Volt\",\"value\":\"$thola_ups_rectifier_current_warning_min$\"},\"--snmp-community\":{\"description\":\"SNMP Community of target device\",\"value\":\"$thola_device_snmp_community$\"},\"--snmp-version\":{\"description\":\"SNMP Version of target device\",\"value\":\"$thola_device_snmp_protocol$\"},\"--system-voltage-critical-max\":{\"description\":\"High critical threshold for the system voltage in Volt\",\"value\":\"$thola_ups_system_voltage_critical_max$\"},\"--system-voltage-critical-min\":{\"description\":\"Low critical threshold for the system voltage in Volt\",\"value\":\"$thola_ups_system_voltage_critical_min$\"},\"--system-voltage-warning-max\":{\"description\":\"High warning threshold for the system voltage in Volt\",\"value\":\"$thola_ups_system_voltage_warning_max$\"},\"--system-voltage-warning-min\":{\"description\":\"Low warning threshold for the system voltage in Volt\",\"value\":\"$thola_ups_system_voltage_warning_min$\"},\"--target-api\":{\"description\":\"Address of the thola API\",\"required\":true,\"value\":\"$thola_api_address$\"},\"thola_device_address\":{\"description\":\"IP address of target device\",\"required\":true,\"skip_key\":true,\"value\":\"$thola_device_address$\",\"order\":\"0\"}},\"command\":\"thola-client check ups\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"thola-ups\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"thola_device_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:45', 0x853330b5b719ad5939703ade207869c5e82f1627, 0x329d7ff82c1202437429209bd04c2246ea86d4c7),
(88, 'icinga_command', 'http', 'create', NULL, '{\"arguments\":{\"--continue-after-certificate\":{\"description\":\"Allows the HTTP check to continue after performing the certificate check. Does nothing unless -C is used\",\"set_if\":\"$http_certificate_continue$\"},\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$http_extra_opts$\"},\"--invert-regex\":{\"description\":\"Return CRITICAL if found, OK if not\",\"set_if\":\"$http_invertregex$\"},\"--no-body\":{\"description\":\"Don\'t wait for document body: stop reading after headers\",\"set_if\":\"$http_ignore_body$\"},\"--sni\":{\"description\":\"Enable SSL\\/TLS hostname extension support (SNI). This is (normally) the default in modern setups\",\"set_if\":\"$http_sni$\"},\"--verify-host\":{\"description\":\"Verify SSL certificate is for the -H hostname (with --sni and -S)\",\"set_if\":\"$http_verify_host$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$http_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$http_ipv4$\"},\"-A\":{\"description\":\"String to be sent in http header as User Agent\",\"value\":\"$http_useragent$\"},\"-C\":{\"description\":\"Minimum number of days a certificate has to be valid. This parameter explicitely sets the port to 443 and ignores the URL if passed.\",\"value\":\"$http_certificate$\"},\"-E\":{\"description\":\"Print additional perfdata\",\"set_if\":\"$http_extendedperfdata$\"},\"-H\":{\"description\":\"Host name argument for servers using host headers (virtual host)\",\"value\":\"$http_vhost$\"},\"-I\":{\"description\":\"IP address or name (use numeric address if possible to bypass DNS lookup)\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$http_address$\"},\"-J\":{\"description\":\"Name of file contains the client certificate (PEM format)\",\"value\":\"$http_clientcert$\"},\"-K\":{\"description\":\"Name of file contains the private key (PEM format)\",\"value\":\"$http_privatekey$\"},\"-L\":{\"description\":\"Wrap output in HTML link\",\"set_if\":\"$http_link$\"},\"-M\":{\"description\":\"Warn if document is more than seconds old\",\"value\":\"$http_maxage$\"},\"-P\":{\"description\":\"URL encoded http POST data\",\"value\":\"$http_post$\"},\"-R\":{\"description\":\"Search page for case-insensitive regex\",\"value\":\"$http_expect_body_eregi$\",\"order\":\"2\"},\"-S\":{\"description\":\"Connect via SSL\",\"set_if\":\"$http_ssl$\"},\"-S1\":{\"description\":\"Connect via SSL version TLSv1\",\"set_if\":\"$http_ssl_force_tlsv1$\"},\"-S1+\":{\"description\":\"Connect via SSL version TLSv1 and newer\",\"set_if\":\"$http_ssl_force_tlsv1_or_higher$\"},\"-S1.1\":{\"description\":\"Connect via SSL version TLSv1.1\",\"set_if\":\"$http_ssl_force_tlsv1_1$\"},\"-S1.1+\":{\"description\":\"Connect via SSL version TLSv1.1 and newer\",\"set_if\":\"$http_ssl_force_tlsv1_1_or_higher$\"},\"-S1.2\":{\"description\":\"Connect via SSL version TLSv1.2\",\"set_if\":\"$http_ssl_force_tlsv1_2$\"},\"-S1.2+\":{\"description\":\"Connect via SSL version TLSv1.2 and newer\",\"set_if\":\"$http_ssl_force_tlsv1_2_or_higher$\"},\"-S2\":{\"description\":\"Connect via SSL version SSLv2\",\"set_if\":\"$http_ssl_force_sslv2$\"},\"-S2+\":{\"description\":\"Connect via SSL version SSLv2 and newer\",\"set_if\":\"$http_ssl_force_sslv2_or_higher$\"},\"-S3\":{\"description\":\"Connect via SSL version SSLv3\",\"set_if\":\"$http_ssl_force_sslv3$\"},\"-S3+\":{\"description\":\"Connect via SSL version SSLv3 and newer\",\"set_if\":\"$http_ssl_force_sslv3_or_higher$\"},\"-T\":{\"description\":\"Specify Content-Type header when POSTing\",\"value\":\"$http_contenttype$\"},\"-a\":{\"description\":\"Username:password on sites with basic authentication\",\"value\":\"$http_auth_pair$\"},\"-b\":{\"description\":\"Username:password on proxy-servers with basic authentication\",\"value\":\"$http_proxy_auth_pair$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$http_critical_time$\"},\"-d\":{\"description\":\"String to expect in the response headers\",\"value\":\"$http_headerstring$\"},\"-e\":{\"description\":\"Comma-delimited list of strings, at least one of them is expected in the first (status) line of the server response (default: HTTP\\/1.)\",\"value\":\"$http_expect$\"},\"-f\":{\"description\":\"How to handle redirect pages\",\"value\":\"$http_onredirect$\"},\"-j\":{\"description\":\"Set http method (for example: HEAD, OPTIONS, TRACE, PUT, DELETE)\",\"value\":\"$http_method$\"},\"-k\":{\"description\":\"Any other tags to be sent in http header (may be repeated)\",\"value\":\"$http_header$\"},\"-l\":{\"description\":\"Allow regex to span newline\",\"set_if\":\"$http_linespan$\",\"order\":\"1\"},\"-m\":{\"description\":\"Minim page size required:Maximum page size required\",\"value\":\"$http_pagesize$\"},\"-p\":{\"description\":\"Port number (default: 80)\",\"value\":\"$http_port$\"},\"-r\":{\"description\":\"Search page for regex\",\"value\":\"$http_expect_body_regex$\",\"order\":\"2\"},\"-s\":{\"description\":\"String to expect in the content\",\"value\":\"$http_string$\"},\"-t\":{\"description\":\"Seconds before connection times out\",\"value\":\"$http_timeout$\"},\"-u\":{\"description\":\"URL to GET or POST (default: \\/)\",\"value\":\"$http_uri$\"},\"-v\":{\"description\":\"Show details for command-line debugging\",\"set_if\":\"$http_verbose$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$http_warn_time$\"}},\"command\":\"check_http\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"http\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$http_ipv4$\",\"check_ipv6\":\"$http_ipv6$\",\"http_address\":\"$check_address$\",\"http_invertregex\":false,\"http_linespan\":false,\"http_link\":false,\"http_sni\":false,\"http_ssl\":false,\"http_verbose\":false}}', 'yalh', '2026-09-03 00:35:45', 0x339601d50ac127de9c5f99dcc98253477f052edf, 0x853330b5b719ad5939703ade207869c5e82f1627),
(89, 'icinga_command', 'icinga', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"icinga\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"icinga_min_version\":\"\"}}', 'yalh', '2026-09-03 00:35:45', 0xabcde3c7fedbadcab34c53b99324f19e4877f67f, 0x339601d50ac127de9c5f99dcc98253477f052edf),
(90, 'icinga_command', 'udp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$udp_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$udp_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$udp_ipv4$\"},\"-e\":{\"description\":\" String to expect in server response\",\"required\":true,\"value\":\"$udp_expect$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$udp_quit$\"},\"-s\":{\"description\":\"String to send to the server\",\"required\":true,\"value\":\"$udp_send$\"}},\"command\":\"check_udp -H $udp_address$ -p $udp_port$\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"udp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$udp_ipv4$\",\"check_ipv6\":\"$udp_ipv6$\",\"udp_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:45', 0x7ddab3aa9b69dc923854bc5ef48d18f4df35bfbc, 0xabcde3c7fedbadcab34c53b99324f19e4877f67f),
(91, 'icinga_command', 'update-windows', 'create', NULL, '{\"arguments\":{\"--no-reboot-critical\":{\"description\":\"Do not automatically return critical if an update requiring reboot is present.\",\"set_if\":\"$ignore_reboot$\"},\"--possible-reboot\":{\"description\":\"Treat \'may need update\' as \'definitely needs update\'\",\"set_if\":\"$update_win_reboot$\"},\"-c\":{\"description\":\"Number of updates to trigger a critical\",\"value\":\"$update_win_crit$\"},\"-w\":{\"description\":\"Number of updates to trigger a warning\",\"value\":\"$update_win_warn$\"}},\"command\":\"check_update.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"update-windows\",\"object_type\":\"external_object\",\"timeout\":300}', 'yalh', '2026-09-03 00:35:45', 0xe43d217fadd501b9535a3e83f926d1f6f4f23909, 0x7ddab3aa9b69dc923854bc5ef48d18f4df35bfbc),
(92, 'icinga_command', 'icingacli-businessprocess', 'create', NULL, '{\"arguments\":{\"--ack-is-ok\":{\"description\":\"Treat acknowledged hosts\\/services always as UP\\/OK\",\"set_if\":\"$icingacli_businessprocess_ackisok$\"},\"--blame\":{\"description\":\"Show problem details as a tree reduced to the nodes which have the same state as the business process\",\"set_if\":\"$icingacli_businessprocess_blame$\"},\"--colors\":{\"description\":\"Show colored output\",\"set_if\":\"$icingacli_businessprocess_colors$\"},\"--config\":{\"description\":\"Configuration file containing your business process without file extension\",\"value\":\"$icingacli_businessprocess_config$\"},\"--details\":{\"description\":\"Get details for root cause analysis\",\"set_if\":\"$icingacli_businessprocess_details$\"},\"--downtime-is-ok\":{\"description\":\"Treat hosts\\/services in downtime always as UP\\/OK\",\"set_if\":\"$icingacli_businessprocess_downtimeisok$\"},\"--process\":{\"description\":\"Business process to monitor\",\"required\":true,\"skip_key\":true,\"value\":\"$icingacli_businessprocess_process$\",\"order\":\"-1\"},\"--root-cause\":{\"description\":\"Used in combination with --blame. Only shows the paths of the nodes which are responsible for the state of the business process\",\"set_if\":\"$icingacli_businessprocess_rootcause$\"},\"--state-type\":{\"description\":\"Define which state type to look at. Could be either soft or hard, overrides an eventually configured default\",\"value\":\"$icingacli_businessprocess_statetype$\"}},\"command\":\"\\/usr\\/bin\\/icingacli businessprocess process check\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"icingacli-businessprocess\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"icingacli_businessprocess_ackisok\":false,\"icingacli_businessprocess_blame\":false,\"icingacli_businessprocess_colors\":false,\"icingacli_businessprocess_details\":false,\"icingacli_businessprocess_downtimeisok\":false,\"icingacli_businessprocess_rootcause\":false}}', 'yalh', '2026-09-03 00:35:46', 0x2e8a2eb6a1d358fcf920130a5d5104e7b76e6ffb, 0xe43d217fadd501b9535a3e83f926d1f6f4f23909),
(93, 'icinga_command', 'ups', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ups_extra_opts$\"},\"-H\":{\"description\":\"Address of the upsd server\",\"required\":true,\"value\":\"$ups_address$\"},\"-T\":{\"description\":\"Display temperature in degrees Celsius instead of Fahrenheit\",\"set_if\":\"$ups_celsius$\"},\"-c\":{\"description\":\"Critical threshold for the selected variable\",\"value\":\"$ups_critical$\"},\"-p\":{\"description\":\"Port number (default: 3493)\",\"value\":\"$ups_port$\"},\"-t\":{\"description\":\"Seconds before the connection times out (default: 10)\",\"value\":\"$ups_timeout$\"},\"-u\":{\"description\":\"Name of the UPS to monitor\",\"required\":true,\"value\":\"$ups_name$\"},\"-v\":{\"description\":\"Variable to monitor, valid strings are LINE, TEMP, BATTPCT or LOADPCT\",\"value\":\"$ups_variable$\"},\"-w\":{\"description\":\"Warning threshold for the selected variable\",\"value\":\"$ups_warning$\"}},\"command\":\"check_ups\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ups\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"ups_address\":\"$check_address$\",\"ups_name\":\"ups\"}}', 'yalh', '2026-09-03 00:35:46', 0xb71e089431e4776f5aa8260facd0730cbe7e9b91, 0x2e8a2eb6a1d358fcf920130a5d5104e7b76e6ffb),
(94, 'icinga_command', 'icingacli-director', 'create', NULL, '{\"arguments\":{\"--check\":{\"description\":\"Run only a specific test suite\",\"value\":\"$icingacli_director_check$\"},\"--db\":{\"description\":\"Use a specific Icinga Web DB resource\",\"value\":\"$icingacli_director_db$\"}},\"command\":\"\\/usr\\/bin\\/icingacli director health check\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"icingacli-director\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:46', 0xc55504678b2a8247bbe893aa4f3dc10f2b5368c9, 0xb71e089431e4776f5aa8260facd0730cbe7e9b91),
(95, 'icinga_command', 'uptime', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Min. number of uptime to generate critical alert ( w < c )\",\"required\":true,\"value\":\"$uptime_critical$\"},\"--for\":{\"description\":\"Show uptime in a pretty format (Running for x weeks, x days, ...)\",\"set_if\":\"$uptime_for$\"},\"--since\":{\"description\":\"Show last boot in yyyy-mm-dd HH:MM:SS format (output from \'uptime -s\')\",\"set_if\":\"$uptime_since$\"},\"--warning\":{\"description\":\"Min. number of uptime to generate warning\",\"required\":true,\"value\":\"$uptime_warning$\"}},\"command\":\"check_uptime\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"uptime\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"uptime_critical\":\"15m\",\"uptime_warning\":\"30m\"}}', 'yalh', '2026-09-03 00:35:46', 0xc313832d4a176361049454eefc7a2fa21cb71467, 0xc55504678b2a8247bbe893aa4f3dc10f2b5368c9),
(96, 'icinga_command', 'icingacli-elasticsearch', 'create', NULL, '{\"arguments\":{\"--crit\":{\"description\":\"Critical threshold\",\"value\":\"$icingacli_elasticsearch_critical$\"},\"--filter\":{\"description\":\"Filter for events\",\"value\":\"$icingacli_elasticsearch_filter$\"},\"--from\":{\"description\":\"Negative value of time to search from now\",\"value\":\"$icingacli_elasticsearch_from$\"},\"--index\":{\"description\":\"Index pattern to use when searching\",\"value\":\"$icingacli_elasticsearch_index$\"},\"--instance\":{\"description\":\"Elasticsearch instance to connect to\",\"value\":\"$icingacli_elasticsearch_instance$\"},\"--warn\":{\"description\":\"Warning threshold\",\"value\":\"$icingacli_elasticsearch_warning$\"}},\"command\":\"\\/usr\\/bin\\/icingacli elasticsearch check\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"icingacli-elasticsearch\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:46', 0x1a223f6499391b8f72a432785b8bf870048b923c, 0xc313832d4a176361049454eefc7a2fa21cb71467),
(97, 'icinga_command', 'uptime-windows', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"Critical threshold\",\"value\":\"$uptime_win_crit$\"},\"-u\":{\"description\":\"Time unit to use\",\"value\":\"$uptime_win_unit$\"},\"-w\":{\"description\":\"Warning threshold\",\"value\":\"$uptime_win_warn$\"}},\"command\":\"check_uptime.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"uptime-windows\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"uptime_win_unit\":\"s\"}}', 'yalh', '2026-09-03 00:35:46', 0xac9a2edc69a714ed8caa381a12b46c47b0dd0d52, 0x1a223f6499391b8f72a432785b8bf870048b923c),
(98, 'icinga_command', 'icingacli-x509', 'create', NULL, '{\"arguments\":{\"--allow-self-signed\":{\"description\":\"Ignore if a certificate or its issuer has been self-signed\",\"set_if\":\"$icingacli_x509_allow_self_signed$\"},\"--critical\":{\"description\":\"Less remaining time results in state CRITICAL\",\"value\":\"$icingacli_x509_critical$\"},\"--host\":{\"description\":\"A hosts name\",\"value\":\"$icingacli_x509_host$\"},\"--ip\":{\"description\":\"A hosts IP address\",\"value\":\"$icingacli_x509_ip$\"},\"--port\":{\"description\":\"The port to check in particular\",\"value\":\"$icingacli_x509_port$\"},\"--warning\":{\"description\":\"Less remaining time results in state WARNING\",\"value\":\"$icingacli_x509_warning$\"}},\"command\":\"\\/usr\\/bin\\/icingacli x509 check host\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"icingacli-x509\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:46', 0x87368e09159048b1538a291b2ed2af9dd10e1a4e, 0xac9a2edc69a714ed8caa381a12b46c47b0dd0d52),
(99, 'icinga_command', 'users', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$users_extra_opts$\"},\"-c\":{\"description\":\"Set CRITICAL status if more than INTEGER users are logged in\",\"value\":\"$users_cgreater$\"},\"-w\":{\"description\":\"Set WARNING status if more than INTEGER users are logged in\",\"value\":\"$users_wgreater$\"}},\"command\":\"check_users\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"users\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"users_cgreater\":50,\"users_wgreater\":20}}', 'yalh', '2026-09-03 00:35:46', 0x5bb427cb0b777c6884d4df5305230aa32be956f5, 0x87368e09159048b1538a291b2ed2af9dd10e1a4e),
(100, 'icinga_command', 'users-windows', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"Critical threshold\",\"value\":\"$users_win_crit$\"},\"-w\":{\"description\":\"Warning threshold\",\"value\":\"$users_win_warn$\"}},\"command\":\"check_users.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"users-windows\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:46', 0xd8196d8de6f26e2ca513a3bfb5277d678e068ff8, 0x5bb427cb0b777c6884d4df5305230aa32be956f5),
(101, 'icinga_command', 'icmp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$icmp_extra_opts$\"},\"-H\":{\"description\":\"Host address\",\"repeat_key\":false,\"value\":\"$icmp_address$\",\"order\":\"1\"},\"-I\":{\"description\":\"max target interval (currently 0.000ms)\",\"value\":\"$icmp_target_interval$\"},\"-b\":{\"description\":\"Number of icmp data bytes to send. Packet size will be data bytes + icmp header (currently 68 + 8)\",\"value\":\"$icmp_data_bytes$\"},\"-c\":{\"description\":\"critical threshold (currently 500.000ms,30%)\",\"value\":\"$icmp_crta$,$icmp_cpl$%\"},\"-i\":{\"description\":\"max packet interval (currently 80.000ms)\",\"value\":\"$icmp_packet_interval$\"},\"-l\":{\"description\":\"TTL on outgoing packets (currently 0)\",\"value\":\"$icmp_ttl$\"},\"-m\":{\"description\":\"number of alive hosts required for success\",\"value\":\"$icmp_hosts_alive$\"},\"-n\":{\"description\":\"number of packets to send (currently 5)\",\"value\":\"$icmp_packets$\"},\"-s\":{\"description\":\"specify a source IP address or device name\",\"value\":\"$icmp_source$\"},\"-t\":{\"description\":\"timeout value (seconds, currently  10)\",\"value\":\"$icmp_timeout$\"},\"-w\":{\"description\":\"warning threshold (currently 200.000ms,10%)\",\"value\":\"$icmp_wrta$,$icmp_wpl$%\"}},\"command\":\"check_icmp\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"icmp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"icmp_address\":\"$address$\",\"icmp_cpl\":30,\"icmp_crta\":200,\"icmp_wpl\":10,\"icmp_wrta\":100}}', 'yalh', '2026-09-03 00:35:46', 0x18170ada6af39d301e4a197f9f69f0eb67d24a5a, 0xd8196d8de6f26e2ca513a3bfb5277d678e068ff8),
(102, 'icinga_command', 'varnish', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"Set critical threshold: [@][lo:]hi\",\"value\":\"$varnish_critical$\"},\"-n\":{\"description\":\"Specify the Varnish instance name\",\"value\":\"$varnish_name$\"},\"-p\":{\"description\":\"Specify the parameter to check (see below). The default is \'ratio\'.\",\"value\":\"$varnish_param$\"},\"-w\":{\"description\":\"Set warning threshold: [@][lo:]hi\",\"value\":\"$varnish_warning$\"}},\"command\":\"check_varnish\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"varnish\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:46', 0x0d22adf03bf7c05f68fec3652acdddfc8e247748, 0x18170ada6af39d301e4a197f9f69f0eb67d24a5a),
(103, 'icinga_command', 'iftraffic', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"SNMP community. Defaults to \'public\' if omitted.\",\"value\":\"$iftraffic_community$\"},\"-H\":{\"description\":\"Check interface on the indicated host.\",\"required\":true,\"value\":\"$iftraffic_address$\"},\"-M\":{\"description\":\"Max counter value of net devices in kilo\\/mega\\/giga\\/bytes.\",\"value\":\"$iftraffic_max_counter$\"},\"-V\":{\"description\":\"SNMP version. Defaults to \'1\' if omitted.\",\"value\":\"$iftraffic_version$\"},\"-b\":{\"description\":\"Interface maximum speed in kilo\\/mega\\/giga\\/bits per second.\",\"required\":true,\"value\":\"$iftraffic_bandwidth$\"},\"-c\":{\"description\":\"% of bandwidth usage necessary to result in critical status (default: 98)\",\"value\":\"$iftraffic_crit$\"},\"-i\":{\"description\":\"Interface name.\",\"required\":true,\"value\":\"$iftraffic_interface$\"},\"-u\":{\"description\":\"g=gigabits\\/s,m=megabits\\/s,k=kilobits\\/s,b=bits\\/s.\",\"value\":\"$iftraffic_units$\"},\"-w\":{\"description\":\"% of bandwidth usage necessary to result in warning status (default: 85)\",\"value\":\"$iftraffic_warn$\"}},\"command\":\"check_iftraffic.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"iftraffic\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"iftraffic_address\":\"$check_address$\",\"iftraffic_crit\":\"98\",\"iftraffic_warn\":\"85\"}}', 'yalh', '2026-09-03 00:35:46', 0x98cb623958f2501fb69a6882f7b3f4fd6aa36934, 0x0d22adf03bf7c05f68fec3652acdddfc8e247748),
(104, 'icinga_command', 'vmware-esx-dc-runtime-info', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--cluster\":{\"description\":\"ESX or ESXi clustername.\",\"required\":false,\"value\":\"$vmware_cluster$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":true,\"value\":\"$vmware_datacenter$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":{\"description\":\"Shows all runtime info for the datacenter\\/Vcenter.\",\"value\":\"runtime\"},\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-dc-runtime-info\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:46', 0xfe630bf09a935fda56d2d86189002d8eff1209c5, 0x98cb623958f2501fb69a6882f7b3f4fd6aa36934),
(105, 'icinga_command', 'iftraffic64', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"SNMP community. Defaults to \'public\' if omitted.\",\"value\":\"$iftraffic64_community$\"},\"-H\":{\"description\":\"Check interface on the indicated host.\",\"required\":true,\"value\":\"$iftraffic64_address$\"},\"-M\":{\"description\":\"Max counter value of net devices in kilo\\/mega\\/giga\\/bytes.\",\"value\":\"$iftraffic64_max_counter$\"},\"-b\":{\"description\":\"Interface maximum speed in kilo\\/mega\\/giga\\/bits per second.\",\"required\":true,\"value\":\"$iftraffic64_bandwidth$\"},\"-c\":{\"description\":\"% of bandwidth usage necessary to result in critical status (default: 98)\",\"value\":\"$iftraffic64_crit$\"},\"-i\":{\"description\":\"Interface name.\",\"required\":true,\"value\":\"$iftraffic64_interface$\"},\"-u\":{\"description\":\"g=gigabits\\/s,m=megabits\\/s,k=kilobits\\/s,b=bits\\/s.\",\"value\":\"$iftraffic64_units$\"},\"-w\":{\"description\":\"% of bandwidth usage necessary to result in warning status (default: 85)\",\"value\":\"$iftraffic64_warn$\"}},\"command\":\"check_iftraffic64.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"iftraffic64\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"iftraffic64_address\":\"$check_address$\",\"iftraffic64_crit\":\"98\",\"iftraffic64_warn\":\"85\"}}', 'yalh', '2026-09-03 00:35:46', 0x27aa35919a41a675d49fefdc916d0a0078c0e8fd, 0xfe630bf09a935fda56d2d86189002d8eff1209c5),
(106, 'icinga_command', 'ifw-api', 'create', NULL, '{\"methods_execute\":\"PluginCheck\",\"object_name\":\"ifw-api\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"ifw_api_arguments\":{},\"ifw_api_command\":\"$command.name$\",\"ifw_api_expected_san\":\"$ifw_api_host$\",\"ifw_api_port\":5668}}', 'yalh', '2026-09-03 00:35:47', 0x70b955e987faeda25e0faf98cc2558c95d348536, 0x27aa35919a41a675d49fefdc916d0a0078c0e8fd),
(107, 'icinga_command', 'vmware-esx-dc-runtime-issues', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--cluster\":{\"description\":\"ESX or ESXi clustername.\",\"required\":false,\"value\":\"$vmware_cluster$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":true,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--multiline\":{\"set_if\":\"$vmware_multiline$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"runtime\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--subselect\":\"issues\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-dc-runtime-issues\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:47', 0x1c8ad29808573c217e01374917669343ad893f71, 0x70b955e987faeda25e0faf98cc2558c95d348536),
(108, 'icinga_command', 'imap', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$imap_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$imap_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$imap_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$imap_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$imap_certificate_age$\"},\"-E\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \\r\\n added to end of quit\",\"value\":\"$imap_escape$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$imap_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit (default: warn)\",\"value\":\"$imap_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$imap_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$imap_critical$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response\",\"value\":\"$imap_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated)\",\"value\":\"$imap_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$imap_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received\",\"value\":\"$imap_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$imap_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$imap_quit$\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit (default: crit)\",\"value\":\"$imap_refuse$\"},\"-s\":{\"description\":\"String to send to the server\",\"value\":\"$imap_send$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$imap_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$imap_warning$\"}},\"command\":\"check_imap\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"imap\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$imap_ipv4$\",\"check_ipv6\":\"$imap_ipv6$\",\"imap_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:35:47', 0xccb00d426238080e2469533cfa1c1589e587e078, 0x1c8ad29808573c217e01374917669343ad893f71);
