(109, 'icinga_command', 'vmware-esx-dc-runtime-listcluster', 'create', NULL, '{\"arguments\":{\"--alertonly\":{\"set_if\":\"$vmware_alertonly$\"},\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--cluster\":{\"description\":\"ESX or ESXi clustername.\",\"required\":false,\"value\":\"$vmware_cluster$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":true,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--multiline\":{\"set_if\":\"$vmware_multiline$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"runtime\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--subselect\":\"listcluster\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-dc-runtime-listcluster\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:47', 0x9d3d17abf16c2b80e02d95d11690241f5d1ad828, 0xccb00d426238080e2469533cfa1c1589e587e078),
(110, 'icinga_command', 'interfaces', 'create', NULL, '{\"arguments\":{\"--aliases\":{\"description\":\"Retrieves the interface description.\",\"set_if\":\"$interfaces_aliases$\"},\"--auth-phrase\":{\"description\":\"SNMPv3 Auth Phrase\",\"value\":\"$interfaces_auth_phrase$\"},\"--auth-proto\":{\"description\":\"SNMPv3 Auth Protocol (SHA|MD5)\",\"value\":\"$interfaces_auth_proto$\"},\"--bandwidth\":{\"description\":\"Bandwidth warn level in percent.\",\"value\":\"$interfaces_bandwidth$\"},\"--community\":{\"description\":\"The community string (default public).\",\"value\":\"$interfaces_community$\"},\"--down-is-ok\":{\"description\":\"Disables critical alerts for down interfaces.\",\"set_if\":\"$interfaces_down_is_ok$\"},\"--errors\":{\"description\":\"Number of in errors (CRC errors for cisco) to consider a warning (default 50).\",\"value\":\"$interfaces_errors$\"},\"--exclude-regex\":{\"description\":\"Interface list negative regexp.\",\"value\":\"$interfaces_exclude_regex$\"},\"--hostname\":\"$interfaces_address$\",\"--if-names\":{\"description\":\"Use ifName instead of ifDescr.\",\"set_if\":\"$interfaces_names$\"},\"--lastcheck\":{\"description\":\"Last checktime (unixtime).\",\"value\":\"$interfaces_lastcheck$\"},\"--match-aliases\":{\"description\":\"Also match against aliases (Option --aliases automatically enabled).\",\"set_if\":\"$interfaces_match_aliases$\"},\"--mode\":{\"description\":\"Special operating mode (default,cisco,nonbulk,bintec).\",\"value\":\"$interfaces_mode$\"},\"--out-errors\":{\"description\":\"Number of out errors (collisions for cisco) to consider a warning (default same as in errors).\",\"value\":\"$interface_out_errors$\"},\"--perfdata\":\"$interfaces_perfdata$\",\"--prefix\":{\"description\":\"Prefix interface names with this label.\",\"value\":\"$interfaces_prefix$\"},\"--priv-phrase\":{\"description\":\"SNMPv3 Privacy Phrase\",\"value\":\"$interfaces_priv_phrase$\"},\"--priv-proto\":{\"description\":\"SNMPv3 Privacy Protocol (AES|DES)\",\"value\":\"$interfaces_priv_proto$\"},\"--regex\":{\"description\":\"Interface list regexp.\",\"value\":\"$interfaces_regex$\"},\"--sleep\":{\"description\":\"Sleep between every SNMP query (in ms).\",\"value\":\"$interfaces_sleep$\"},\"--speed\":{\"description\":\"Override speed detection with this value (bits per sec).\",\"value\":\"$interfaces_speed$\"},\"--timeout\":{\"description\":\"Sets the SNMP timeout (in ms).\",\"value\":\"$interfaces_timeout$\"},\"--trim\":{\"description\":\"Cut this number of characters from the start of interface descriptions.\",\"value\":\"$interfaces_trim$\"},\"--user\":{\"description\":\"SNMPv3 User\",\"value\":\"$interfaces_user$\"}},\"command\":\"check_interfaces\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"interfaces\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"interfaces_address\":\"$check_address$\",\"interfaces_aliases\":false,\"interfaces_down_is_ok\":false,\"interfaces_match_aliases\":false}}', 'yalh', '2026-09-03 00:35:47', 0x757a28b4e9f481170eeee5c612a2f4f7c4d8dec7, 0x9d3d17abf16c2b80e02d95d11690241f5d1ad828),
