(114, 'icinga_command', 'interfacetable', 'create', NULL, '{\"arguments\":{\"--64bits\":{\"description\":\"Use SNMP 64-bits counters\",\"set_if\":\"$interfacetable_64bits$\"},\"--accessmethod\":{\"description\":\"Access method for a shortcut to the host in the HTML page\",\"value\":\"$interfacetable_accessmethod$\"},\"--alias\":{\"description\":\"Add the alias information for each interface in the interface table\",\"set_if\":\"$interfacetable_alias$\"},\"--alias-matching\":{\"description\":\"Allow you to specify alias in addition to interface names\",\"set_if\":\"$interfacetable_aliasmatching$\"},\"--cache\":{\"description\":\"Define the retention time of the cached data\",\"value\":\"$interfacetable_cache$\"},\"--config\":{\"description\":\"Specify a config file to load\",\"value\":\"$interfacetable_config$\"},\"--contextname\":{\"description\":\"Context name for the snmp requests\",\"value\":\"$interfacetable_contextname$\"},\"--cp\":{\"description\":\"Number of property changes before leading to a critical alert\",\"value\":\"$interfacetable_criticalproperty$\"},\"--css\":{\"description\":\"Define the css stylesheet used by the generated html files\",\"value\":\"$interfacetable_css$\"},\"--ct\":{\"description\":\"Interface traffic load percentage leading to a critical alert\",\"value\":\"$interfacetable_criticaltraffic$\"},\"--default-table-sorting\":{\"description\":\"Default table sorting\",\"value\":\"$interfacetable_defaulttablesorting$\"},\"--delta\":{\"description\":\"Set the delta used for interface throuput calculation\",\"value\":\"$interfacetable_delta$\"},\"--domain\":{\"description\":\"SNMP transport domain\",\"value\":\"$interfacetable_domain$\"},\"--duplex\":{\"description\":\"Add the duplex mode property for each interface in the interface table\",\"set_if\":\"$interfacetable_duplex$\"},\"--ep\":{\"description\":\"Comma separated list of interfaces excluded from the property tracking\",\"value\":\"$interfacetable_excludeproperty$\"},\"--et\":{\"description\":\"Comma separated list of interfaces excluded from traffic checks\",\"value\":\"$interfacetable_excludetraffic$\"},\"--grapherurl\":{\"description\":\"Graphing system url\",\"value\":\"$interfacetable_grapherurl$\"},\"--htmltablelinktarget\":{\"description\":\"Specifies the windows or the frame where the [details] link will load the generated html page\",\"value\":\"$interfacetable_htmltablelinktarget$\"},\"--ifs\":{\"description\":\"Input field separator\",\"value\":\"$interfacetable_ifs$\"},\"--ip\":{\"description\":\"Comma separated list of interfaces included in the property tracking\",\"value\":\"$interfacetable_includeproperty$\"},\"--it\":{\"description\":\"Comma separated list of interfaces included for traffic checks\",\"value\":\"$interfacetable_includetraffic$\"},\"--max-repetitions\":{\"description\":\"Increasing this value may enhance snmp query performances by gathering more results at one time\",\"value\":\"$interfacetable_maxrepetitions$\"},\"--noconfigtable\":{\"description\":\"Disable configuration table on the generated HTML page\",\"set_if\":\"$interfacetable_noconfigtable$\"},\"--nodetype\":{\"description\":\"Specify the node type, for specific information to be printed \\/ specific oids to be used\",\"value\":\"$interfacetable_nodetype$\"},\"--nohuman\":{\"description\":\"Do not translate bandwidth usage in human readable format\",\"set_if\":\"$interfacetable_nohuman$\"},\"--noifloadgradient\":{\"description\":\"Disable color gradient from green over yellow to red for the load percentage\",\"set_if\":\"$interfacetable_noifloadgradient$\"},\"--noipinfo\":{\"description\":\"Remove the ip information for each interface from the interface table\",\"set_if\":\"$interfacetable_noipinfo$\"},\"--notips\":{\"description\":\"Disable the tips in the generated html tables\",\"set_if\":\"$interfacetable_notips$\"},\"--notype\":{\"description\":\"Remove the interface type for each interface\",\"set_if\":\"$interfacetable_notype$\"},\"--outputshort\":{\"description\":\"Reduce the verbosity of the plugin output\",\"set_if\":\"$interfacetable_outputshort$\"},\"--perfdatadir\":{\"description\":\"When specified, the performance data are also written directly to a file, in the specified location\",\"value\":\"$interfacetable_perfdatadir$\"},\"--perfdataformat\":{\"description\":\"Define which performance data will be generated\",\"value\":\"$interfacetable_perfdataformat$\"},\"--perfdataservicedesc\":{\"description\":\"Specify additional parameters for output performance data to PNP\",\"value\":\"$interfacetable_perfdataservicedesc$\"},\"--perfdatathreshold\":{\"description\":\"Define which thresholds are printed in the generated performance data\",\"value\":\"$interfacetable_perfdatathreshold$\"},\"--pkt\":{\"description\":\"Add unicast\\/non-unicast pkt stats for each interface\",\"set_if\":\"$interfacetable_pkt$\"},\"--portperfunit\":{\"description\":\"Traffic could be reported in bits (counters) or in bps (calculated value)\",\"value\":\"$interfacetable_portperfunit$\"},\"--snapshot\":{\"description\":\"Force the plugin to run like if it was the first launch\",\"set_if\":\"$interfacetable_snapshot$\"},\"--snmp-maxmsgsize\":{\"description\":\"Size of the SNMP message in octets, usefull in case of too long responses. Be carefull with network filters. Range 484 - 65535. Apply only to netsnmp perl bindings. The default is 1472 octets for UDP\\/IPv4, 1452 octets for UDP\\/IPv6, 1460 octets for TCP\\/IPv4, and 1440 octets for TCP\\/IPv6.\",\"value\":\"$interfacetable_snmpmaxmsgsize$\"},\"--snmp-retries\":{\"description\":\"Define the number of times to retry sending a SNMP message\",\"value\":\"$interfacetable_snmpretries$\"},\"--snmp-timeout\":{\"description\":\"Define the Transport Layer timeout for the snmp queries\",\"value\":\"$interfacetable_snmptimeout$\"},\"--stp\":{\"description\":\"Add the stp state property for each interface in the interface table\",\"set_if\":\"$interfacetable_stp$\"},\"--table-split\":{\"description\":\"Generate multiple interface tables, one per interface type\",\"set_if\":\"$interfacetable_tablesplit$\"},\"--timeout\":{\"description\":\"Define the global timeout limit of the plugin\",\"value\":\"$interfacetable_timeout$\"},\"--tp\":{\"description\":\"List of tracked properties\",\"value\":\"$interfacetable_trackproperty$\"},\"--trafficwithpkt\":{\"description\":\"Enable traffic calculation using pkt counters instead of octet counters. Useful when using 32-bit counters to track the load on > 1GbE interfaces.\",\"set_if\":\"$interfacetable_trafficwithpkt$\"},\"--unixsnmp\":{\"description\":\"Use unix snmp utilities for snmp requests\",\"set_if\":\"$interfacetable_unixsnmp$\"},\"--vlan\":{\"description\":\"Add the vlan attribution property for each interface in the interface table\",\"set_if\":\"$interfacetable_vlan$\"},\"--wp\":{\"description\":\"Number of property changes before leading to a warning alert\",\"value\":\"$interfacetable_warningproperty$\"},\"--wt\":{\"description\":\"Interface traffic load percentage leading to a warning alert\",\"value\":\"$interfacetable_warningtraffic$\"},\"-2\":{\"description\":\"Use snmp v2c\",\"set_if\":\"$interfacetable_snmpv2$\"},\"-C\":{\"description\":\"Specifies the snmp v1\\/v2c community string\",\"value\":\"$interfacetable_community$\"},\"-H\":{\"description\":\"Specifies the remote host to poll\",\"value\":\"$interfacetable_hostquery$\"},\"-L\":{\"description\":\"Authentication protocol,Priv protocol\",\"value\":\"$interfacetable_protocols$\"},\"-P\":{\"description\":\"SNMP port\",\"value\":\"$interfacetable_port$\"},\"-X\":{\"description\":\"Priv password for snmpv3\",\"value\":\"$interfacetable_privpass$\"},\"-e\":{\"description\":\"Comma separated list of interfaces globally excluded from the monitoring\",\"value\":\"$interfacetable_exclude$\"},\"-f\":{\"description\":\"Enable port performance data\",\"set_if\":\"$interfacetable_enableperfdata$\"},\"-g\":{\"description\":\"Specify the used graphing solution\",\"value\":\"$interfacetable_grapher$\"},\"-h\":{\"description\":\"Specifies the hostname to display in the HTML link\",\"value\":\"$interfacetable_hostdisplay$\"},\"-i\":{\"description\":\"Comma separated list of interfaces globally included in the monitoring\",\"value\":\"$interfacetable_include$\"},\"-l\":{\"description\":\"Login for snmpv3 authentication\",\"value\":\"$interfacetable_login$\"},\"-r\":{\"description\":\"Interface names and property names for some other options will be interpreted as regular expressions\",\"set_if\":\"$interfacetable_regex$\"},\"-x\":{\"description\":\"Auth password for snmpv3 authentication\",\"value\":\"$interfacetable_passwd$\"}},\"command\":\"check_interface_table_v3t\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"interfacetable\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"interfacetable_64bits\":false,\"interfacetable_aliasmatching\":false,\"interfacetable_duplex\":false,\"interfacetable_enableperfdata\":false,\"interfacetable_hostdisplay\":\"$host.display_name$\",\"interfacetable_hostquery\":\"$address$\",\"interfacetable_noconfigtable\":false,\"interfacetable_nohuman\":false,\"interfacetable_noifloadgradient\":false,\"interfacetable_noipinfo\":false,\"interfacetable_notips\":false,\"interfacetable_notype\":false,\"interfacetable_outputshort\":false,\"interfacetable_perfdataservicedesc\":\"$service.name$\",\"interfacetable_pkt\":false,\"interfacetable_regex\":false,\"interfacetable_snapshot\":false,\"interfacetable_snmpv2\":false,\"interfacetable_stp\":false,\"interfacetable_trafficwithpkt\":false,\"interfacetable_unixsnmp\":false,\"interfacetable_vlan\":false}}', 'yalh', '2026-09-03 00:35:48', 0xa80d9b2bb25b6b0468130eb9f6fd474f4e99a518, 0xd37604966db2134d0b5de5ce752560d43756b594),
(115, 'icinga_command', 'vmware-esx-dc-runtime-tools', 'create', NULL, '{\"arguments\":{\"--alertonly\":{\"set_if\":\"$vmware_alertonly$\"},\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--cluster\":{\"description\":\"ESX or ESXi clustername.\",\"required\":false,\"value\":\"$vmware_cluster$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":true,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--multiline\":{\"set_if\":\"$vmware_multiline$\"},\"--no_vm_tools_ok\":{\"set_if\":\"$vmware_novmtools$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--open_vm_tools_ok\":{\"set_if\":\"$vmware_openvmtools$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--poweredonly\":{\"set_if\":\"$vmware_poweredonly$\"},\"--select\":\"runtime\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--subselect\":\"tools\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-dc-runtime-tools\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:49', 0x1dd32f8bb7c7208667efc6c1cc1c37869a2c8642, 0xa80d9b2bb25b6b0468130eb9f6fd474f4e99a518),
(116, 'icinga_command', 'iostat', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"warning threshold for tps, KB_read\\/s and KB_written\\/s\",\"value\":\"$iostat_ctps$,$iostat_cread$,$iostat_cwrite$\"},\"-d\":{\"description\":\"Device to check without path. e.g. sda\",\"value\":\"$iostat_disk$\"},\"-w\":{\"description\":\"warning threshold for tps, KB_read\\/s and KB_written\\/s\",\"value\":\"$iostat_wtps$,$iostat_wread$,$iostat_wwrite$\"}},\"command\":\"check_iostat\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"iostat\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"iostat_cread\":200,\"iostat_ctps\":200,\"iostat_cwrite\":200,\"iostat_disk\":\"sda\",\"iostat_wread\":100,\"iostat_wtps\":100,\"iostat_wwrite\":100}}', 'yalh', '2026-09-03 00:35:49', 0x3df9a6b028aaaf089bd8fa74bd177c03763766eb, 0x1dd32f8bb7c7208667efc6c1cc1c37869a2c8642),
(117, 'icinga_command', 'iostats', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"Sets the CRITICAL level for iowait\",\"value\":\"$iostats_critical_wait$\"},\"-W\":{\"description\":\"Sets the WARNING level for iowait\",\"value\":\"$iostats_warning_wait$\"},\"-c\":{\"description\":\"Sets the CRITICAL level for tps, KB_read\\/s and KB_written\\/s, respectively\",\"value\":\"$iostats_critical_tps$,$iostats_critical_read$,$iostats_critical_write$\"},\"-d\":{\"description\":\"Device to check without path. e.g. sda\",\"value\":\"$iostats_disk$\"},\"-w\":{\"description\":\"Sets the WARNING level for tps, KB_read\\/s and KB_written\\/s, respectively\",\"value\":\"$iostats_warning_tps$,$iostats_warning_read$,$iostats_warning_write$\"}},\"command\":\"check_iostats\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"iostats\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"iostats_critical_read\":80000,\"iostats_critical_tps\":5000,\"iostats_critical_wait\":80,\"iostats_critical_write\":25000,\"iostats_disk\":\"sda\",\"iostats_warning_read\":50000,\"iostats_warning_tps\":3000,\"iostats_warning_wait\":50,\"iostats_warning_write\":10000}}', 'yalh', '2026-09-03 00:35:49', 0x6c1957b20d1a7a3873a378b53760b48b41f5a4cc, 0x3df9a6b028aaaf089bd8fa74bd177c03763766eb),
