(119, 'icinga_command', 'ipmi-alive', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$ping_extra_opts$\"},\"-H\":{\"description\":\"host to ping\",\"value\":\"$ping_address$\"},\"-c\":{\"description\":\"critical threshold pair\",\"value\":\"$ping_crta$,$ping_cpl$%\"},\"-p\":{\"description\":\"number of ICMP ECHO packets to send (Default: 5)\",\"value\":\"$ping_packets$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$ping_timeout$\"},\"-w\":{\"description\":\"warning threshold pair\",\"value\":\"$ping_wrta$,$ping_wpl$%\"}},\"command\":\"check_ping\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"ipmi-alive\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"ping_address\":\"$check_address$\",\"ping_cpl\":100,\"ping_crta\":5000,\"ping_packets\":1,\"ping_wpl\":100,\"ping_wrta\":5000}}', 'yalh', '2026-09-03 00:35:50', 0xe0178951e9f56efca857394487b2b171427536af, 0x510910c041e4279984850f5d0e05d876eb5bd354),
(120, 'icinga_command', 'vmware-esx-soap-host-check', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":false,\"value\":\"$vmware_datacenter$\"},\"--host\":{\"description\":\"ESX or ESXi hostname.\",\"required\":true,\"value\":\"$vmware_host$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":{\"description\":\"Simple check to verify a successfull connection to VMWare SOAP API.\",\"value\":\"soap\"},\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is 