(121, 'icinga_command', 'ipmi-sensor', 'create', NULL, '{\"arguments\":{\"--assettag\":{\"description\":\"Print the assettag if it is available in the IPMI FRU data. (--fru is mandatory)\",\"set_if\":\"$ipmi_show_assettag$\"},\"--board\":{\"description\":\"Print additional motherboard information if it is available in the IPMI FRU data. (--fru is mandatory)\",\"set_if\":\"$ipmi_show_board$\"},\"--fru\":{\"description\":\"Print the product serial number got by ipmi-fru\",\"set_if\":\"$ipmi_show_fru$\"},\"--noentityabsent\":{\"description\":\"Skip sensor checks for sensors that have \'noentityabsent\' as event state\",\"set_if\":\"$ipmi_noentityabsent$\"},\"--nosel\":{\"description\":\"Turn off system event log checking via ipmi-sel\",\"set_if\":\"$ipmi_no_sel_checking$\"},\"--nothresholds\":{\"description\":\"Turn off performance data thresholds from output-sensor-thresholds\",\"set_if\":\"$ipmi_no_thresholds$\"},\"-D\":{\"description\":\"Change the protocol LAN version (default: LAN_2_0)\",\"value\":\"$ipmi_protocol_lan_version$\"},\"-H\":{\"description\":\"Hostname or ip address of the IPMI interface (default: host.address or host.address6)\",\"value\":\"$ipmi_address$\"},\"-L\":{\"description\":\"Privilege level of the user\",\"value\":\"$ipmi_privilege_level$\"},\"-P\":{\"description\":\"Password to use\",\"value\":\"$ipmi_password$\"},\"-ST\":{\"description\":\"Limit SEL entries to specific types. (seperated by comma)\",\"value\":\"$ipmi_sel_type$\"},\"-T\":{\"description\":\"Limit sensors to query based on IPMI sensor type (seperated by comma)\",\"value\":\"$ipmi_sensor_type$\"},\"-U\":{\"description\":\"Username to connect with\",\"value\":\"$ipmi_username$\"},\"-b\":{\"description\":\"Enable backward compatibility mode (for FreeIPMI 0.5.*)\",\"set_if\":\"$ipmi_backward_compatibility_mode$\"},\"-f\":{\"description\":\"Path to the FreeIPMI configuration file\",\"value\":\"$ipmi_config_file$\"},\"-fc\":{\"description\":\"Number of fans that should be active\",\"