(137, 'icinga_command', 'lsi-raid', 'create', NULL, '{\"arguments\":{\"--nocleanlogs\":{\"description\":\"Do not clean up the log files after executing storcli checks.\",\"set_if\":\"$lsi_nocleanlogs$\"},\"--noenclosures\":{\"description\":\"Define if enclosures are present.\",\"set_if\":\"$lsi_noenclosures$\"},\"--nosudo\":{\"description\":\"Do not use sudo when running storcli.\",\"set_if\":\"$lsi_nosudo$\"},\"-BBUTc\":{\"description\":\"Battery critical temperature.\",\"value\":\"$lsi_bbu_temp_critical$\"},\"-BBUTw\":{\"description\":\"Battery warning temperature.\",\"value\":\"$lsi_bbu_temp_warning$\"},\"-C\":{\"description\":\"Insert the controller number to be checked.\",\"value\":\"$lsi_controller_number$\"},\"-CVTc\":{\"description\":\"CacheVault critical temperature.\",\"value\":\"$lsi_cv_temp_critical$\"},\"-CVTw\":{\"description\":\"CacheVault warning temperature.\",\"value\":\"$lsi_cv_temp_warning$\"},\"-EID\":{\"description\":\"Enclosure numbers to be checked, comma-separated.\",\"value\":\"$lsi_enclosure_id$\"},\"-Ib\":{\"description\":\"Warning threshold for BBM counter.\",\"value\":\"$lsi_ignored_bbm_counters$\"},\"-Im\":{\"description\":\"Warning threshold for media errors.\",\"value\":\"$lsi_ignored_media_errors$\"},\"-Io\":{\"description\":\"Warning threshold for other errors.\",\"value\":\"$lsi_ignored_other_errors$\"},\"-Ip\":{\"description\":\"Warning threshold for predictive failures.\",\"value\":\"$lsi_ignored_predictive_fails$\"},\"-Is\":{\"description\":\"Warning threshold for shield counter.\",\"value\":\"$lsi_ignored_shield_counters$\"},\"-LD\":{\"description\":\"Logical devices to be checked, comma-separated.\",\"value\":\"$lsi_ld_id$\"},\"-PD\":{\"description\":\"Physical devices to be checked, comma-separated.\",\"value\":\"$lsi_pd_id$\"},\"-PDTc\":{\"description\":\"Disk critical temperature.\",\"value\":\"$lsi_pd_temp_critical$\"},\"-PDTw\":{\"description\":\"Disk warning temperature.\",\"value\":\"$lsi_pd_temp_warning$\"},\"-Tc\":{\"description\":\"RAID controller critical temperature.\",\"value\":\"$lsi_temp_critical$\"},\"-Tw\":{\"description\":\"RAID controller warning temperature.\",\"value\":\"$lsi_temp_warning$\"},\"-b\":{\"description\":\"Define if BBU is present and it\'s state should be checked.\",\"value\":\"$lsi_bbu$\"},\"-p\":{\"description\":\"Insert the path to storcli (e.g. \\/usr\\/sbin\\/storcli).\",\"value\":\"$storcli_path$\"}},\"command\":\"check_lsi_raid\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"lsi-raid\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:53', 0xde3b550b19bbef1f213f9882480f72eb48caf555, 0xd33b849aa7a018f590a8ffbddf9aa6c077dba70e),
