(140, 'icinga_command', 'mailq', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"Min. number of messages for same domain in queue to generate critical alert ( W < C )\",\"value\":\"$mailq_domain_critical$\"},\"-M\":{\"description\":\"[ sendmail | qmail | postfix | exim | nullmailer ] (default = autodetect)\",\"value\":\"$mailq_servertype$\"},\"-W\":{\"description\":\"Min. number of messages for same domain in queue to generate warning\",\"value\":\"$mailq_domain_warning$\"},\"-c\":{\"description\":\"Min. number of messages in queue to generate critical alert ( w < c )\",\"required\":true,\"value\":\"$mailq_critical$\"},\"-s\":{\"description\":\"Use sudo for mailq command\",\"set_if\":\"$mailq_sudo$\"},\"-t\":{\"description\":\"Plugin timeout in seconds (default = 15)\",\"value\":\"$mailq_timeout$\"},\"-w\":{\"description\":\"Min. number of messages in queue to generate warning\",\"required\":true,\"value\":\"$mailq_warning$\"}},\"command\":\"check_mailq\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"mailq\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:35:53', 0x78cadb8410d24b7940f09dca66861cf47d26d081, 0x6e50bec52ad884dd1649ee5156eb32adfb740d19),
