(142, 'icinga_command', 'mem', 'create', NULL, '{\"arguments\":{\"-C\":{\"description\":\"Count OS caches as FREE memory\",\"set_if\":\"$mem_cache$\"},\"-a\":{\"description\":\"Check AVAILABLE memory\",\"set_if\":\"$mem_available$\"},\"-c\":{\"description\":\"Percent free\\/used when critical\",\"value\":\"$mem_critical$\"},\"-f\":{\"description\":\"Check FREE memory\",\"set_if\":\"$mem_free$\"},\"-u\":{\"description\":\"Check USED memory\",\"set_if\":\"$mem_used$\"},\"-w\":{\"description\":\"Percent free\\/used when to warn\",\"value\":\"$mem_warning$\"}},\"command\":\"check_mem.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"mem\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"mem_available\":false,\"mem_cache\":false,\"mem_free\":false,\"mem_used\":false}}', 'yalh', '2026-09-03 00:35:53', 0x0817fdad619eebb1cc02a89c875d5ae81d288757, 0x3df4def02aa106755c28c802135780a91363c34c),
