queue_latency\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"},\"--warning\":\"$vmware_warn$\"},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-soap-host-io-queue-latency\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_host\":\"$address$\",\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:53', 0xc92ef577846ac4782e2d061abd00ff50f42bb6a4, 0x0817fdad619eebb1cc02a89c875d5ae81d288757),
(144, 'icinga_command', 'memcached', 'create', NULL, '{\"arguments\":{\"-E\":{\"description\":\"Generate warning if number of evictions exceeds this threshold. 0=disable. (default: 10)\",\"value\":\"$memcached_warning_evictions$\"},\"-H\":{\"description\":\"Hostname or IP address (required) optional \':port\' overrides -p\",\"required\":true,\"value\":\"$memcached_hostname$\"},\"-K\":{\"description\":\"expiry time in seconds for history object (default: 7200)\",\"value\":\"$memcached_expiry$\"},\"-T\":{\"description\":\"Minimum time interval (in minutes) to use to analyse stats. (default: 30)\",\"value\":\"$memcached_minimum_stat_interval$\"},\"-k\":{\"description\":\"key name for history object (default: check_memcached)\",\"value\":\"$memcached_key$\"},\"-n\":{\"description\":\"Keep up to this many items in the history object in memcached (default: 30)\",\"value\":\"$memcached_keep$\"},\"-p\":{\"description\":\"Port number (default: 11211)\",\"value\":\"$memcached_port$\"},\"-r\":{\"description\":\"output performance statistics as rate-per-minute figures (better suited to pnp4nagios)\",\"set_if\":\"$memcached_performance_output$\"},\"-t\":{\"description\":\"timeout in seconds (default: 1.0)\",\"value\":\"$memcached_timeout$\"},\"-v\":{\"description\":\"verbose messages\",\"set_if\":\"$memcached_verbose$\"},\"-w\":{\"description\":\"Generate warning if quotient of hits\\/misses falls below this value (default: 2.0)\",\"value\":\"$memcached_warning_hits_misses$\"}},\"command\":\"check_memcached\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"memcached\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"memcached_hostname\":\"127.0.0.1\",\"memcached_minimum_stat_interval\":\"10\",\"memcached_performance_output\":true}}', 'yalh', '2026-09-03 00:35:54', 0xf86d5a7dd492782317246f045cb048bb8dccb96d, 0xc92ef577846ac4782e2d061abd00ff50f42bb6a4),
(145, 'icinga_command', 'memory-windows', 'create', NULL, '{\"arguments\":{\"-U\":{\"description\":\"Show used memory instead of the free memory\",\"set_if\":\"$memory_win_show_used$\"},\"-c\":{\"description\":\"Critical Threshold\",\"value\":\"$memory_win_crit$\"},\"-u\":{\"description\":\"Use this unit to display memory\",\"value\":\"$memory_win_unit$\"},\"-w\":{\"description\":\"Warning Threshold\",\"value\":\"$memory_win_warn$\"}},\"command\":\"check_memory.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"memory-windows\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"memory_win_crit\":\"5%\",\"memory_win_unit\":\"mb\",\"memory_win_warn\":\"10%\"}}', 'yalh', '2026-09-03 00:35:54', 0xe635fea9bab36f22b7e8245fe10216d441bf0111, 0xf86d5a7dd492782317246f045cb048bb8dccb96d),
