INSERT INTO `director_activity_log` (`id`, `object_type`, `object_name`, `action_name`, `old_properties`, `new_properties`, `author`, `change_time`, `checksum`, `parent_checksum`) VALUES
(147, 'icinga_command', 'mongodb', 'create', NULL, '{\"arguments\":{\"--all-databases\":{\"description\":\"Check all databases (action database_size)\",\"set_if\":\"$mongodb_alldatabases$\"},\"--database\":{\"description\":\"Specify the database to check\",\"value\":\"$mongodb_database$\"},\"--disable_retry_writes\":{\"description\":\"Disable Retry Writes\",\"set_if\":\"$mongodb_disableretrywrites$\"},\"--mapped-memory\":{\"description\":\"Get mapped memory instead of resident (if resident memory can not be read)\",\"set_if\":\"$mongodb_mappedmemory$\"},\"--max-lag\":{\"description\":\"Get max replication lag (for replication_lag action only)\",\"set_if\":\"$mongodb_maxlag$\"},\"--replicaset\":{\"description\":\"Connect to replicaset\",\"set_if\":\"$mongodb_replcheck$\",\"value\":\"$mongodb_replicaset$\"},\"--ssl\":{\"description\":\"Connect using SSL\",\"set_if\":\"$mongodb_ssl$\"},\"--ssl-ca-cert-file\":{\"description\":\"Path to certificate authority file for SSL\",\"value\":\"$mongodb_ssl_ca_cert_file$\"},\"-A\":{\"description\":\"The action you want to take\",\"value\":\"$mongodb_action$\"},\"-C\":{\"description\":\"The critical threshold we want to set\",\"value\":\"$mongodb_critical$\"},\"-D\":{\"description\":\"Enable output of Nagios performance data\",\"set_if\":\"$mongodb_perfdata$\"},\"-H\":{\"description\":\"The hostname you want to connect to\",\"value\":\"$mongodb_host$\"},\"-P\":{\"description\":\"The port mongodb is runnung on\",\"value\":\"$mongodb_port$\"},\"-T\":{\"description\":\"Time used to sample number of pages faults\",\"value\":\"$mongodb_sampletime$\"},\"-W\":{\"description\":\"The warning threshold we want to set\",\"value\":\"$mongodb_warning$\"},\"-a\":{\"description\":\"The database you want to authenticate against\",\"value\":\"$mongodb_authdb$\"},\"-c\":{\"description\":\"Specify the collection to check\",\"value\":\"$mongodb_collection$\"},\"-p\":{\"description\":\"The password you want to use for that user\",\"value\":\"$mongodb_passwd$\"},\"-q\":{\"description\":\"The query type to check [query|insert|update|delete|getmore|command] from queries_per_second\",\"value\":\"$mongodb_querytype$\"},\"-u\":{\"description\":\"The username you want to login as\",\"value\":\"$mongodb_user$\"}},\"command\":\"check_mongodb.py\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"mongodb\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"mongodb_action\":\"connections\",\"mongodb_host\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"mongodb_perfdata\":true}}', 'yalh', '2026-09-03 00:35:54', 0x25963476eb4b75eef2ccd9ee550b4165c4a552c5, 0x0c642788a8f5087ad26c744b86f9f2782df00bd7),
