(150, 'icinga_command', 'mssql_health', 'create', NULL, '{\"arguments\":{\"--blacklist\":{\"description\":\"Blacklist some (missing\\/failed) components\",\"value\":\"$mssql_health_blacklist$\"},\"--commit\":{\"description\":\"turns on autocommit for the dbd::sybase module\",\"set_if\":\"$mssql_health_commit$\"},\"--critical\":{\"description\":\"the critical range\",\"value\":\"$mssql_health_critical$\"},\"--criticalx\":{\"description\":\"The extended critical thresholds\",\"value\":\"$mssql_health_criticalx$\"},\"--currentdb\":{\"description\":\"the name of a database which is used as the current database for the connection\",\"value\":\"$mssql_health_currentdb$\"},\"--dbthresholds\":{\"description\":\"Read thresholds from a database table\",\"value\":\"$mssql_health_dbthresholds$\"},\"--environment\":{\"description\":\"Add a variable to the plugin\'s environment.\",\"value\":\"$mssql_health_environment$\"},\"--extra-opts\":{\"description\":\"read command line arguments from an external file\",\"value\":\"$mssql_health_extraopts$\"},\"--hostname\":{\"description\":\"the database server\'s hostname\",\"value\":\"$mssql_health_hostname$\"},\"--isvalidtime\":{\"description\":\"Signals the plugin to return OK if now is not a valid check time.\",\"value\":\"$mssql_health_isvalidtime$\"},\"--lookback\":{\"description\":\"The amount of time you want to look back when calculating average rates\",\"value\":\"$mssql_health_lookback$\"},\"--method\":{\"description\":\"how the plugin should connect to the database (dbi for using DBD::Sybase (default), sqlrelay for the SQLRelay proxy)\",\"value\":\"$mssql_health_method$\"},\"--mitigation\":{\"description\":\"The parameter allows you to change a critical error to a warning.\",\"value\":\"$mssql_health_mitigation$\"},\"--mode\":{\"description\":\"the mode of the plugin\",\"value\":\"$mssql_health_mode$\"},\"--morphmessage\":{\"description\":\"Modify the final output message.\",\"value\":\"$mssql_health_morphmessage$\"},\"--morphperfdata\":{\"description\":\"The parameter allows you to change performance data labels.\",\"value\":\"$mssql_health_morphperfdata$\"},\"--multiline\":{\"description\":\"Multiline output.\",\"value\":\"$mssql_health_multiline$\"},\"--name\":{\"description\":\"the name of the database etc depending on the mode\",\"value\":\"$mssql_health_name$\"},\"--name2\":{\"description\":\"if name is a sql statement, name2 can be used to appear in the output and the performance data\",\"value\":\"$mssql_health_name2$\"},\"--name3\":{\"description\":\"The tertiary name of a component\",\"value\":\"$mssql_health_name3$\"},\"--negate\":{\"description\":\"Emulate the negate plugin. --negate warning=critical --negate unknown=critical.\",\"value\":\"$mssql_health_negate$\"},\"--nooffline\":{\"description\":\"Skip the offline databases\",\"set_if\":\"$mssql_health_nooffline$\"},\"--notemp\":{\"description\":\"Ignore temporary databases\\/tablespaces\",\"set_if\":\"$mssql_health_notemp$\"},\"--offlineok\":{\"description\":\"if offline databases are perfectly ok for you\",\"set_if\":\"$mssql_health_offlineok$\"},\"--password\":{\"description\":\"the mssql db user\'s password\",\"value\":\"$mssql_health_password$\"},\"--port\":{\"description\":\"the database\'s port\",\"value\":\"$mssql_health_port$\"},\"--regexp\":{\"description\":\"name will be interpreted as a regular expression\",\"set_if\":\"$mssql_health_regexp$\"},\"--report\":{\"description\":\"Report can be used to output only the bad news (short,long,html)\",\"value\":\"$mssql_health_report$\"},\"--selectedperfdata\":{\"description\":\"The parameter allows you to limit the list of performance data.\",\"value\":\"$mssql_health_selectedperfdata$\"},\"--server\":{\"description\":\"the name of a predefined connection\",\"value\":\"$mssql_health_server$\"},\"--statefilesdir\":{\"description\":\"An alternate directory where the plugin can save files.\",\"value\":\"$mssql_health_statefilesdir$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 15)\",\"value\":\"$mssql_health_timeout$\"},\"--units\":{\"description\":\"This is used for a better output of mode=sql and for specifying thresholds for mode=tablespace-free\",\"value\":\"$mssql_health_units$\"},\"--username\":{\"description\":\"the mssql db user\",\"value\":\"$mssql_health_username$\"},\"--warning\":{\"description\":\"the warning range\",\"value\":\"$mssql_health_warning$\"},\"--warningx\":{\"description\":\"The extended warning thresholds\",\"value\":\"$mssql_health_warningx$\"},\"--with-mymodules-dyn-dir\":{\"description\":\"Add-on modules for the my-modes will be searched in this directory.\",\"value\":\"$mssql_health_withmymodulesdyndir$\"}},\"command\":\"check_mssql_health\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"mssql_health\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"mssql_health_commit\":false,\"mssql_health_nooffline\":false,\"mssql_health_notemp\":false,\"mssql_health_offlineok\":false,\"mssql_health_regexp\":false,\"mssql_health_report\":\"short\"}}', 'yalh', '2026-09-03 00:35:55', 0x0a1b437b43d0032f26474ffe528d106a565fa7cb, 0xe366c225e467f31093e0802e0428e0a8dd8915ec),
