(159, 'icinga_command', 'netgear', 'create', NULL, '{\"arguments\":{\"-base-url\":{\"description\":\"Netgear base URL\",\"required\":true,\"value\":\"$netgear_base_url$\"},\"-cpu-critical\":{\"description\":\"CPU usage critical threshold (default 90)\",\"value\":\"$netgear_cpu_critical$\"},\"-cpu-warning\":{\"description\":\"CPU usage warning threshold (default 50)\",\"value\":\"$netgear_cpu_warning$\"},\"-fan-critical\":{\"description\":\"Fan speed critical threshold (default 5000)\",\"value\":\"$netgear_fan_critical$\"},\"-fan-warning\":{\"description\":\"Fan speed warning threshold (default 3000)\",\"value\":\"$netgear_fan_warning$\"},\"-mem-critical\":{\"description\":\"RAM usage critical threshold (default 90)\",\"value\":\"$netgear_mem_critical$\"},\"-mem-warning\":{\"description\":\"RAM usage warning threshold (default 50)\",\"value\":\"$netgear_mem_warning$\"},\"-mode\":{\"description\":\"Output modes to enable {basic|ports|poe|all} (repeatable) (default: basic)\",\"repeat_key\":true,\"value\":\"$netgear_mode$\"},\"-nocpu\":{\"description\":\"Hide the CPU info\",\"set_if\":\"$netgear_hide_cpu$\"},\"-nofans\":{\"description\":\"Hide the Fans info\",\"set_if\":\"$netgear_hide_fans$\"},\"-nomem\":{\"description\":\"Hide the RAM info\",\"set_if\":\"$netgear_hide_mem$\"},\"-noperfdata\":{\"description\":\"Do not output performance data\",\"set_if\":\"$netgear_hide_perfdata$\"},\"-notemp\":{\"description\":\"Hide the Temperature info\",\"set_if\":\"$netgear_hide_temp$\"},\"-password\":{\"description\":\"Password for authentication\",\"required\":true,\"value\":\"$netgear_password$\"},\"-port\":{\"description\":\"Ports to check (repeatable) (default 1,2,3,4,5,6,7,8)\",\"repeat_key\":true,\"value\":\"$netgear_ports$\"},\"-stats-critical\":{\"description\":\"Port stats critical threshold (default 20)\",\"value\":\"$netgear_stats_critical$\"},\"-stats-warning\":{\"description\":\"Port stats warning threshold (default 5)\",\"value\":\"$netgear_stats_warning$\"},\"-temp-critical\":{\"description\":\"Temperature critical threshold (default 70)\",\"value\":\"$netgear_temp_critical$\"},\"-temp-warning\":{\"description\":\"Temperature warning threshold (default 50)\",\"value\":\"$netgear_temp_warning$\"},\"-username\":{\"description\":\"Username for authentication\",\"required\":true,\"value\":\"$netgear_username$\"}},\"command\":\"check_netgear\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"netgear\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false}}', 'yalh', '2026-09-03 00:35:56', 0xa025a53d2ad7e4497f088ac299f803b6b0b85cdd, 0xa0906c213cc1a338c379dca719ac6b0560137a4f),
(160, 'icinga_command', 'network-windows', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"Critical threshold\",\"value\":\"$network_win_crit$\"},\"-n\":{\"description\":\"Don\'t show ISATAP interfaces in output\",\"set_if\":\"$network_no_isatap$\"},\"-w\":{\"description\":\"Warning threshold\",\"value\":\"$network_win_warn$\"}},\"command\":\"check_network.exe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"network-windows\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"network_no_isatap\":true}}', 'yalh', '2026-09-03 00:35:57', 0x5eae661ad810cc315751c2ba6925fb8f92d93ec9, 0xa025a53d2ad7e4497f088ac299f803b6b0b85cdd),
(161, 'icinga_command', 'nginx_status', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"number of active connections, ReqPerSec or ConnPerSec that will cause a CRITICAL\",\"value\":\"$nginx_status_critical$\"},\"--disable-sslverifyhostname\":{\"description\":\"Disable SSL hostname verification\",\"set_if\":\"$nginx_status_disable_sslverify$\"},\"--hostname\":{\"description\":\"name or IP address of host to check\",\"value\":\"$nginx_status_host_address$\"},\"--maxreach\":{\"description\":\"Number of max processes reached (since last check) that should trigger an alert\",\"value\":\"$nginx_status_maxreach$\"},\"--pass\":{\"description\":\"Password for basic auth\",\"value\":\"$nginx_status_pass$\"},\"--port\":{\"description\":\"the http port\",\"value\":\"$nginx_status_port$\"},\"--realm\":{\"description\":\"Realm for basic auth\",\"value\":\"$nginx_status_realm$\"},\"--servername\":{\"description\":\"ServerName, use it if you specified an IP in -H to match the good Virtualhost in your target\",\"value\":\"$nginx_status_servername$\"},\"--ssl\":{\"description\":\"Wether we should use HTTPS instead of HTTP\",\"set_if\":\"$nginx_status_ssl$\"},\"--timeout\":{\"description\":\"timeout in seconds\",\"value\":\"$nginx_status_timeout$\"},\"--url\":{\"description\":\"Specific URL to use, instead of the default \'http:\\/\\/<nginx_status_hostname>\\/nginx_status\'\",\"value\":\"$nginx_status_url$\"},\"--user\":{\"description\":\"Username for basic auth\",\"value\":\"$nginx_status_user$\"},\"--warn\":{\"description\":\"number of active connections, ReqPerSec or ConnPerSec that will cause a WARNING\",\"value\":\"$nginx_status_warn$\"}},\"command\":\"check_nginx_status.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"nginx_status\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"nginx_status_critical\":\"20000,200,300\",\"nginx_status_disable_sslverify\":false,\"nginx_status_host_address\":\"$check_address$\",\"nginx_status_ssl\":false,\"nginx_status_timeout\":15,\"nginx_status_warn\":\"10000,100,200\"}}', 'yalh', '2026-09-03 00:35:57', 0x055fce7e4fc0a1f98253f18362d5dcf452c895b6, 0x5eae661ad810cc315751c2ba6925fb8f92d93ec9),
(162, 'icinga_command', 'vmware-esx-soap-host-media', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":false,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--host\":{\"description\":\"ESX or ESXi hostname.\",\"required\":true,\"value\":\"$vmware_host$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--multiline\":{\"set_if\":\"$vmware_multiline$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"hostmedia\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-soap-host-media\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_host\":\"$address$\",\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:35:57', 0x1b3bba225982b2cf4e5fe3871b047204af34955c, 0x055fce7e4fc0a1f98253f18362d5dcf452c895b6),
(163, 'icinga_command', 'nrpe', 'create', NULL, '{\"arguments\":{\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$nrpe_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$nrpe_ipv4$\"},\"-3\":{\"description\":\"Use this if you want to connect to NRPE v3\",\"set_if\":\"$nrpe_version_3$\"},\"-2\":{\"description\":\"Use this if you want to connect to NRPE v2\",\"set_if\":\"$nrpe_version_2$\"},\"-A\":{\"description\":\"The CA file to use for PKI\",\"value\":\"$nrpe_ca$\"},\"-C\":{\"description\":\"The cert file to use for PKI\",\"value\":\"$nrpe_cert$\"},\"-D\":{\"description\":\"Disable check_nrpe plugin from logging to syslog (requires check_nrpe >= 4.0)\",\"set_if\":\"$nrpe_no_logging$\"},\"-H\":{\"description\":\"The address of the host running the NRPE daemon\",\"value\":\"$nrpe_address$\"},\"-K\":{\"description\":\"The key file to use for PKI\",\"value\":\"$nrpe_key$\"},\"-L\":{\"description\":\"The list of SSL ciphers to use\",\"value\":\"$nrpe_cipher_list$\"},\"-P\":{\"description\":\"Specify non-default payload size for NSClient++\",\"value\":\"$nrpe_payload_size$\"},\"-S\":{\"description\":\"The SSL\\/TLS version to use\",\"value\":\"$nrpe_ssl_version$\"},\"-a\":{\"repeat_key\":false,\"value\":\"$nrpe_arguments$\",\"order\":\"1\"},\"-c\":\"$nrpe_command$\",\"-d\":{\"description\":\"Anonymous Diffie Hellman use: 0 = deny, 1 = allow, 2 = force\",\"value\":\"$nrpe_dh_opt$\"},\"-n\":{\"description\":\"Do not use SSL\",\"set_if\":\"$nrpe_no_ssl$\"},\"-p\":\"$nrpe_port$\",\"-t\":{\"description\":\"<interval>:<state> = <Number of seconds before connection times out>:<Check state to exit with in the event of a timeout (default=CRITICAL)>\",\"value\":\"$nrpe_timeout$\"},\"-u\":{\"description\":\"Make socket timeouts return an UNKNOWN state instead of CRITICAL\",\"set_if\":\"$nrpe_timeout_unknown$\"}},\"command\":\"check_nrpe\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"nrpe\",\"object_type\":\"external_object\",\"timeout\":300,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$nrpe_ipv4$\",\"check_ipv6\":\"$nrpe_ipv6$\",\"nrpe_address\":\"$check_address$\",\"nrpe_no_ssl\":false,\"nrpe_timeout_unknown\":false,\"nrpe_version_2\":false}}', 'yalh', '2026-09-03 00:35:57', 0xeb6049a9b9613000b50885769814dd42e45aab05, 0x1b3bba225982b2cf4e5fe3871b047204af34955c);
