(165, 'icinga_command', 'nscp', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$nscp_extra_opts$\"},\"-H\":{\"description\":\"Name of the host to check\",\"value\":\"$nscp_address$\"},\"-c\":{\"description\":\"Threshold which will result in a critical status\",\"value\":\"$nscp_crit$\"},\"-d\":{\"description\":\"Use with SERVICESTATE to see working services or PROCSTATE for running processes\",\"set_if\":\"$nscp_showall$\",\"value\":\"SHOWALL\"},\"-l\":{\"repeat_key\":false,\"value\":\"$nscp_params$\"},\"-p\":{\"description\":\"Optional port number (default: 1248)\",\"value\":\"$nscp_port$\"},\"-s\":{\"description\":\"Password needed for the request\",\"value\":\"$nscp_password$\"},\"-t\":{\"description\":\"Seconds before connection attempt times out\",\"value\":\"$nscp_timeout$\"},\"-v\":{\"description\":\"Variable to check\",\"required\":true,\"value\":\"$nscp_variable$\"},\"-w\":{\"description\":\"Threshold which will result in a warning status\",\"value\":\"$nscp_warn$\"}},\"command\":\"check_nt\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"nscp\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"nscp_address\":\"$check_address$\",\"nscp_port\":12489,\"nscp_showall\":false}}', 'yalh', '2026-09-03 00:35:57', 0x3b24555aa406b1db1cf1f4769f495ace52a5e0c8, 0x645149e6d0fc7717f30d2e8870d727c72d06e0d7),
