(184, 'icinga_command', 'nscp-local-tasksched', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Filter which marks items which generates a critical state.\",\"value\":\"$nscp_tasksched_critical$\"},\"--detail-syntax\":{\"description\":\"Detail level syntax.\",\"value\":\"$nscp_tasksched_detailsyntax$\"},\"--empty-state\":{\"description\":\"Return status to use when nothing matched filter.\",\"value\":\"$nscp_tasksched_emptystate$\"},\"--filter\":{\"description\":\"Name of the task to check.\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"title=\'$nscp_tasksched_name$\'\"},\"--folder\":{\"description\":\"The folder in which the tasks to check reside.\",\"value\":\"$nscp_tasksched_folder$\"},\"--hidden\":{\"description\":\"Look for hidden tasks.\",\"set_if\":\"$nscp_tasksched_hidden$\"},\"--load-all\":{\"description\":\"Load all plugins (currently only used with generate)\",\"set_if\":\"$nscp_load_all$\"},\"--log\":{\"description\":\"The log level to use\",\"value\":\"$nscp_log_level$\"},\"--module\":{\"description\":\"Specify which NSClient++ modules are required. \'nscp client\' just needs \'CheckSystem\' by default.\",\"repeat_key\":true,\"value\":\"$nscp_modules$\"},\"--perf-syntax\":{\"description\":\"Performance alias syntax.\",\"value\":\"$nscp_tasksched_perfsyntax$\"},\"--recursive\":{\"description\":\"Recurse sub folder (defaults to true).\",\"value\":\"$nscp_tasksched_recursive$\"},\"--show-all\":{\"set_if\":\"$nscp_showall$\"},\"--warning\":{\"description\":\"Filter which marks items which generates a warning state.\",\"value\":\"$nscp_tasksched_warning$\"},\"-a\":{\"repeat_key\":true,\"value\":\"$nscp_tasksched_arguments$\"},\"-b\":{\"description\":\"Boot the client before executing command (similar as running the command from test mode)\",\"set_if\":\"$nscp_boot$\"},\"-q\":{\"description\":\"Run a query with a given name\",\"required\":true,\"value\":\"$nscp_query$\"}},\"command\":\"\\\\nscp.exe client\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"nscp-local-tasksched\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"nscp_boot\":true,\"nscp_load_all\":false,\"nscp_log_level\":\"critical\",\"nscp_modules\":\"CheckTaskSched\",\"nscp_query\":\"check_tasksched\",\"nscp_showall\":\"$nscp_tasksched_showall$\",\"nscp_tasksched_critical\":\"exit_code < 0\",\"nscp_tasksched_detailsyntax\":\"%(folder)\\/%(title): %(exit_code) != 0\",\"nscp_tasksched_perfsyntax\":\"%(title)\",\"nscp_tasksched_recursive\":true,\"nscp_tasksched_warning\":\"exit_code != 0\"}}', 'yalh', '2026-09-03 00:36:00', 0x2a423fe4c264c06c3068fb90e3e307f4e8213ffb, 0x44ee516bb411d0bbb64b63337e32bd7b8c6f840b);
