(195, 'icinga_command', 'nwc_health', 'create', NULL, '{\"arguments\":{\"--alias\":{\"description\":\"The alias name of a 64bit-interface (ifAlias)\",\"value\":\"$nwc_health_alias$\"},\"--authpassword\":{\"description\":\"The authentication password for SNMPv3\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$nwc_health_authpassword$\"},\"--authprotocol\":{\"description\":\"The authentication protocol for SNMPv3 (md5|sha)\",\"set_if\":\"\\/* Icinga 2 does not export DSL function bodies via API *\\/\",\"set_if_format\":\"expression\",\"value\":\"$nwc_health_authprotocol$\"},\"--blacklist\":{\"description\":\"Blacklist some (missing\\/failed) components\",\"value\":\"$nwc_health_blacklist$\"},\"--community\":{\"description\":\"SNMP community of the server (SNMP v1\\/2 only)\",\"value\":\"$nwc_health_community$\"},\"--community2\":{\"description\":\"SNMP community which can be used to switch the context during runtime\",\"value\":\"$nwc_health_community2$\"},\"--contextengineid\":{\"description\":\"The context engine id for SNMPv3 (10 to 64 hex characters)\",\"value\":\"$nwc_health_contextengineid$\"},\"--contextname\":{\"description\":\"The context name for SNMPv3 (empty represents the default context)\",\"value\":\"$nwc_health_contextname$\"},\"--critical\":{\"description\":\"The critical threshold\",\"value\":\"$nwc_health_critical$\"},\"--criticalx\":{\"description\":\"The extended critical thresholds\",\"repeat_key\":true,\"value\":\"$nwc_health_criticalx$\"},\"--domain\":{\"description\":\"The transport domain to use (default: udp\\/ipv4, other possible values: udp6, udp\\/ipv6, tcp, tcp4, tcp\\/ipv4, tcp6, tcp\\/ipv6)\",\"value\":\"$nwc_health_domain$\"},\"--drecksptkdb\":{\"description\":\"This parameter must be used instead of --name, because Devel::ptkdb is stealing the latter from the command line\",\"value\":\"$nwc_health_drecksptkdb$\"},\"--hostname\":{\"description\":\"Hostname or