(197, 'icinga_command', 'openmanage', 'create', NULL, '{\"arguments\":{\"--all\":{\"description\":\"Check everything, even log content\",\"set_if\":\"$openmanage_all$\"},\"--blacklist\":{\"description\":\"Blacklist missing and\\/or failed components\",\"repeat_key\":true,\"value\":\"$openmanage_blacklist$\"},\"--check\":{\"description\":\"Fine-tune which components are checked\",\"value\":\"$openmanage_check$\"},\"--community\":{\"description\":\"SNMP community string [default=public]\",\"value\":\"$openmanage_community$\"},\"--config\":{\"description\":\"Specify configuration file\",\"value\":\"$openmanage_config$\"},\"--critical\":{\"description\":\"Custom temperature critical limits\",\"value\":\"$openmanage_critical$\"},\"--extinfo\":{\"description\":\"Append system info to alerts\",\"set_if\":\"$openmanage_extinfo$\"},\"--fahrenheit\":{\"description\":\"Use Fahrenheit as temperature unit\",\"set_if\":\"$openmanage_fahrenheit$\"},\"--hostname\":{\"description\":\"Hostname or IP (required for SNMP)\",\"value\":\"$openmanage_hostname$\"},\"--htmlinfo\":{\"description\":\"HTML output with clickable links\",\"set_if\":\"$openmanage_htmlinfo$\"},\"--info\":{\"description\":\"Prefix any alerts with the service tag\",\"set_if\":\"$openmanage_info$\"},\"--ipv6\":{\"description\":\"Use IPv6 instead of IPv4 [default=no]\",\"set_if\":\"$openmanage_ipv6$\"},\"--legacy-perfdata\":{\"description\":\"legacy performance data output\",\"set_if\":\"$openmanage_legacy_perfdata$\"},\"--no-storage\":{\"description\":\"Don\'t check storage\",\"set_if\":\"$openmanage_no_storage$\"},\"--only\":{\"description\":\"Only check a certain component or alert type\",\"value\":\"$openmanage_only$\"},\"--perfdata\":{\"description\":\"Output performance data [default=no]\",\"set_if\":\"$openmanage_perfdata$\"},\"--port\":{\"description\":\"SNMP port number [default=161]\",\"value\":\"$openmanage_port$\"},\"--protocol\":{\"description\":\"SNMP protocol version [default=2c]\",\"value\":\"$openmanag