(200, 'icinga_command', 'oracle_health', 'create', NULL, '{\"arguments\":{\"--commit\":{\"description\":\"turns on autocommit for the dbd::oracle module\",\"set_if\":\"$oracle_health_commit$\"},\"--connect\":{\"description\":\"the connect string\",\"value\":\"$oracle_health_connect$\"},\"--critical\":{\"description\":\"the critical range\",\"value\":\"$oracle_health_critical$\"},\"--ident\":{\"description\":\"outputs instance and database names\",\"set_if\":\"$oracle_health_ident$\"},\"--method\":{\"description\":\"how the plugin should connect to the database (dbi for using DBD::Oracle (default), sqlplus for using the sqlplus-Tool)\",\"value\":\"$oracle_health_method$\"},\"--mode\":{\"description\":\"the mode of the plugin\",\"value\":\"$oracle_health_mode$\"},\"--name\":{\"description\":\"the name of the tablespace, datafile, wait event, latch, enqueue, or sql statement depending on the mode\",\"value\":\"$oracle_health_name$\"},\"--name2\":{\"description\":\"if name is a sql statement, name2 can be used to appear in the output and the performance data\",\"value\":\"$oracle_health_name2$\"},\"--noperfdata\":{\"description\":\"do not output performance data\",\"set_if\":\"$oracle_health_noperfdata$\"},\"--notemp\":{\"description\":\"exclude temporary and system tables\",\"set_if\":\"$oracle_health_notemp$\"},\"--password\":{\"description\":\"the oracle user\'s password\",\"value\":\"$oracle_health_password$\"},\"--regexp\":{\"description\":\"name will be interpreted as a regular expression\",\"set_if\":\"$oracle_health_regexp$\"},\"--report\":{\"description\":\"select the plugin output format. Can be short, long or html. Default is long\",\"value\":\"$oracle_health_report$\"},\"--timeout\":{\"description\":\"plugin timeout. Default is 60 seconds\",\"value\":\"$oracle_health_timeout$\"},\"--units\":{\"description\":\"This is used for a better output of mode=sql and for specifying thresholds for mode=tablespace-free\",\"value\":\"$oracle_health_units$\"},\"--username\":{\"description\":\"the oracle user\",\"value\":\"$oracle_health_username$\"},\"--warning\":{\"description\":\"the warning range\",\"value\":\"$oracle_health_warning$\"}},\"command\":\"check_oracle_health\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"oracle_health\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"oracle_health_commit\":false,\"oracle_health_ident\":false,\"oracle_health_noperfdata\":false,\"oracle_health_notemp\":false,\"oracle_health_regexp\":false,\"oracle_health_report\":\"long\",\"oracle_home\":\"\\/usr\\/lib\\/oracle\\/11.2\\/client64\\/lib\",\"oracle_ld_library_path\":\"\\/usr\\/lib\\/oracle\\/11.2\\/client64\\/lib\",\"oracle_tns_admin\":\"\\/etc\\/icinga2\\/plugin-configs\"}}', 'yalh', '2026-09-03 00:36:03', 0xbd06cd08a2ea8f899f373af9eb27d49631a4305c, 0xf7c7b7af344f7f0c33bf95b97ec1ad784acbc167),
