(204, 'icinga_command', 'pgsql', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$pgsql_extra_opts$\"},\"-C\":{\"description\":\"SQL query value to result in critical status (double)\",\"value\":\"$pgsql_query_critical$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$pgsql_hostname$\"},\"-P\":{\"description\":\"Port number (default: 5432)\",\"value\":\"$pgsql_port$\"},\"-W\":{\"description\":\"SQL query value to result in warning status (double)\",\"value\":\"$pgsql_query_warning$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$pgsql_critical$\"},\"-d\":{\"description\":\"Database to check (default: template1)\",\"value\":\"$pgsql_database$\"},\"-l\":{\"description\":\"Login name of user\",\"value\":\"$pgsql_username$\"},\"-o\":{\"description\":\"Connection parameters (keyword = value), see below\",\"value\":\"$pgsql_options$\"},\"-p\":{\"description\":\"Password (BIG SECURITY ISSUE)\",\"value\":\"$pgsql_password$\"},\"-q\":{\"description\":\"SQL query to run. Only first column in first row will be read\",\"value\":\"$pgsql_query$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$pgsql_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$pgsql_warning$\"}},\"command\":\"check_pgsql\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"pgsql\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"pgsql_hostname\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:36:04', 0x24123b57a31bf038fb99985a71890367cfca3dd5, 0xd99961859f2e102189e4858c4ddca73d0ea7db49),
(205, 'icinga_command', 'vmware-esx-soap-host-runtime-storagehealth', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":false,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--host\":{\"description\":\"ESX or ESXi hostname.\",\"required\":true,\"value\":\"$vmware_host$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--multiline\":{\"set_if\":\"$vmware_multiline$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"runtime\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmwa