(206, 'icinga_command', 'phpfpm_status', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"name or IP address of host to check\",\"required\":true,\"value\":\"$phpfpm_status_hostname$\"},\"-P\":{\"description\":\"Password for basic auth\",\"value\":\"$phpfpm_status_pass$\"},\"-S\":{\"description\":\"Wether we should use HTTPS instead of HTTP. Note that you can give some extra parameters to this settings. Default value is \'TLSv1\' but you could use things like \'TLSv1_1\' or \'TLSV1_2\' (or even \'SSLv23:!SSLv2:!SSLv3\' for old stuff).\",\"set_if\":\"$phpfpm_status_ssl$\"},\"-U\":{\"description\":\"Username for basic auth\",\"value\":\"$phpfpm_status_user$\"},\"-X\":{\"description\":\"Full path to the cacert.pem certificate authority used to verify ssl certificates (use with --verifyssl). if not given the cacert from Mozilla::CA cpan plugin will be used.\",\"value\":\"$phpfpm_status_cacert$\"},\"-c\":{\"description\":\"MIN_AVAILABLE_PROCESSES,PROC_MAX_REACHED,QUEUE_MAX_REACHED number of available workers, or max states reached that will cause an error, -1 for no CRITICAL\",\"value\":\"$phpfpm_status_critical$\"},\"-d\":{\"description\":\"Debug mode (show http request response)\",\"set_if\":\"$phpfpm_status_debug$\"},\"-f\":{\"description\":\"Connect directly to php-fpm via network or local socket, using fastcgi protocol instead of HTTP.\",\"set_if\":\"$phpfpm_status_fastcgi$\"},\"-p\":{\"description\":\"Http port, or Fastcgi port when using --fastcgi\",\"value\":\"$phpfpm_status_port$\"},\"-r\":{\"description\":\"Realm for basic auth\",\"value\":\"$phpfpm_status_realm$\"},\"-s\":{\"description\":\"ServerName, (host header of HTTP request) use it if you specified an IP in -H to match the good Virtualhost in your target\",\"value\":\"$phpfpm_status_servername$\"},\"-t\":{\"description\":\"timeout in seconds (Default: 15)\",\"value\":\"$phpfpm_status_timeout$\"},\"-u\":{\"description\":\"Specific URL (only the path part of it in fact) to use, instead of the default \\/fpm-status\",\"value\":\"$phpfpm_status_url$\"},\"-w\":{\"description\":\"MIN_AVAILABLE_PROCESSES,PROC_MAX_REACHED,QUEUE_MAX_REACHED number of available workers, or max states reached that will cause a warning. -1 for no warning\",\"value\":\"$phpfpm_status_warn$\"},\"-x\":{\"description\":\"verify certificate and hostname from ssl cert, default is 0 (no security), set it to 1 to really make SSL peer name and certificater checks.\",\"set_if\":\"$phpfpm_status_verifyssl$\"}},\"command\":\"check_phpfpm_status\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"phpfpm_status\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"phpfpm_status_hostname\":\"$address$\"}}', 'yalh', '2026-09-03 00:36:04', 0xf08ee5712d6fa2f7dbc49d1fdee5702e5136e705, 0xb619472e826cc21d081101164094062794375283),
