(218, 'icinga_command', 'pop', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$pop_extra_opts$\"},\"-6\":{\"description\":\"Use IPv6 connection\",\"set_if\":\"$pop_ipv6$\"},\"-4\":{\"description\":\"Use IPv4 connection\",\"set_if\":\"$pop_ipv4$\"},\"-A\":{\"description\":\"All expect strings need to occur in server response. Default is any.\",\"set_if\":\"$pop_all$\"},\"-D\":{\"description\":\"Minimum number of days a certificate has to be valid\",\"value\":\"$pop_certificate_age$\"},\"-E\":{\"description\":\"Can use \\n, \\r, \\t or \\\\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \\r\\n added to end of quit\",\"value\":\"$pop_escape$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$pop_address$\"},\"-M\":{\"description\":\"Accept expected string mismatches with states ok, warn, crit (default: warn)\",\"value\":\"$pop_mismatch$\"},\"-S\":{\"description\":\"Use SSL for the connection.\",\"set_if\":\"$pop_ssl$\"},\"-c\":{\"description\":\"Response time to result in critical status (seconds)\",\"value\":\"$pop_critical$\"},\"-d\":{\"description\":\"Seconds to wait between sending string and polling for response\",\"value\":\"$pop_delay$\"},\"-e\":{\"description\":\"String to expect in server response (may be repeated)\",\"value\":\"$pop_expect$\"},\"-j\":{\"description\":\"Hide output from TCP socket.\",\"set_if\":\"$pop_jail$\"},\"-m\":{\"description\":\"Close connection once more than this number of bytes are received\",\"value\":\"$pop_maxbytes$\"},\"-p\":{\"description\":\"Port number (default: none)\",\"value\":\"$pop_port$\"},\"-q\":{\"description\":\"String to send server to initiate a clean close of the connection\",\"value\":\"$pop_quit$\"},\"-r\":{\"description\":\"Accept TCP refusals with states ok, warn, crit (default: crit)\",\"value\":\"$pop_refuse$\"},\"-s\":{\"description\":\"String to send to the server\",\"value\":\"$pop_send$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10)\",\"value\":\"$pop_timeout$\"},\"-w\":{\"description\":\"Response time to result in warning status (seconds)\",\"value\":\"$pop_warning$\"}},\"command\":\"check_pop\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"pop\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":\"$pop_ipv4$\",\"check_ipv6\":\"$pop_ipv6$\",\"pop_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:36:05', 0x4876cc5f48109e9c9a924c59e8919d413d640496, 0xf2155aa0f4a0a8d872c165f4f64e63745e020471),
