nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--standbyok\":{\"set_if\":\"$vmware_standbyok$\"},\"--subselect\":\"path\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"}},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-soap-host-storage-path\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_host\":\"$address$\",\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\"}}', 'yalh', '2026-09-03 00:36:05', 0x9cf5f0fc3ff97bc9a01bd56c31bee26b0de3f538, 0x4876cc5f48109e9c9a924c59e8919d413d640496),
(220, 'icinga_command', 'postgres', 'create', NULL, '{\"arguments\":{\"--action\":{\"description\":\"determines the test executed\",\"value\":\"$postgres_action$\"},\"--assume-prod\":{\"description\":\"assume that server in production mode\",\"set_if\":\"$postgres_production$\"},\"--assume-standby-mode\":{\"description\":\"assume that server in continious WAL recovery mode\",\"set_if\":\"$postgres_standby$\"},\"--datadir\":{\"description\":\"location of the PostgreSQL data directory\",\"value\":\"$postgres_datadir$\"},\"--dbpass\":{\"description\":\"database password(s); use a .pgpass file instead when possible\",\"value\":\"$postgres_dbpass$\"},\"--dbservice\":{\"description\":\"service name to use inside of pg_service.conf\",\"value\":\"$postgres_dbservice$\"},\"--exclude\":{\"description\":\"name(s) items to specifically exclude (e.g. tables), depends on the action\",\"value\":\"$postgres_exclude$\"},\"--excludeuser\":{\"description\":\"exclude objects owned by certain users\",\"value\":\"$postgres_excludeuser$\"},\"--include\":{\"description\":\"name(s) items to specifically include (e.g. tables), depends on the action\",\"value\":\"$postgres_include$\"},\"--includeuser\":{\"description\":\"include objects owned by certain users\",\"value\":\"$postgres_includeuser$\"},\"--language\":{\"description\":\"language to use for messages\",\"value\":\"$postgres_language$\"},\"--perflimit\":{\"description\":\"limit the number of performance data to report\",\"value\":\"$postgres_perflimit$\"},\"--query\":{\"description\":\"query for custom_query action\",\"value\":\"$postgres_query$\"},\"--reverse\":{\"description\":\"reverses warning and critical for custom_query action\",\"set_if\":\"$postgres_reverse$\"},\"--tempdir\":{\"description\":\"specify directory for temporary files. default depends on the OS\",\"value\":\"$postgres_tempdir$\"},\"--valtype\":{\"description\":\"determines the result type for custom_query action\",\"value\":\"$postgres_valtype$\"},\"-H\":{\"desc