(222, 'icinga_command', 'printer_health', 'create', NULL, '{\"arguments\":{\"--authpassword\":{\"description\":\"The authentication password for SNMPv3\",\"value\":\"$printer_health_authpassword$\"},\"--authprotocol\":{\"description\":\"The authentication protocol for SNMPv3 (md5|sha)\",\"value\":\"$printer_health_authprotocol$\"},\"--blacklist\":{\"description\":\"Blacklist some (missing\\/failed) components\",\"value\":\"$printer_health_blacklist$\"},\"--community\":{\"description\":\"SNMP community of the server (SNMP v1\\/2 only)\",\"value\":\"$printer_health_community$\"},\"--community2\":{\"description\":\"SNMP community which can be used to switch the context during runtime\",\"value\":\"$printer_health_community2$\"},\"--contextengineid\":{\"description\":\"The context engine id for SNMPv3 (10 to 64 hex characters)\",\"value\":\"$printer_health_contextengineid$\"},\"--contextname\":{\"description\":\"The context name for SNMPv3 (empty represents the default context)\",\"value\":\"$printer_health_contextname$\"},\"--critical\":{\"description\":\"The critical threshold\",\"value\":\"$printer_health_critical$\"},\"--criticalx\":{\"description\":\"The extended critical thresholds\",\"value\":\"$printer_health_criticalx$\"},\"--domain\":{\"description\":\"The transport domain to use (default: udp\\/ipv4, other possible values: udp6, udp\\/ipv6, tcp, tcp4, tcp\\/ipv4, tcp6, tcp\\/ipv6)\",\"value\":\"$printer_health_domain$\"},\"--hostname\":{\"description\":\"Hostname or IP-address of the switch or router\",\"value\":\"$printer_health_hostname$\"},\"--lookback\":{\"description\":\"The amount of time you want to look back when calculating average rates. Use it for mode interface-errors or interface-usage. Without --lookback the time between two runs of check_printer_health is the base for calculations. If you want your checkresult to be based for example on the past hour, use --lookback 3600.\",\"value\":\"$printer_health_lookback$\"},\"--mitigation\":{\"description\":\"The parameter allows you to change a critical error to a warning.\",\"value\":\"$printer_health_mitigation$\"},\"--mode\":{\"description\":\"Which mode should be executed. Available modes: hardware-health, supplies-status and uptime.\",\"value\":\"$printer_health_mode$\"},\"--morphperfdata\":{\"description\":\"The parameter allows you to change performance data labels. It\'s a perl regexp and a substitution. --morphperfdata \'(.*)ISATAP(.*)\'=\'$1patasi$2\'\",\"value\":\"$printer_health_morphperfdata$\"},\"--multiline\":{\"description\":\"Multiline output\",\"set_if\":\"$printer_health_multiline$\"},\"--name\":{\"description\":\"The name of an interface (ifDescr)\",\"value\":\"$printer_health_name$\"},\"--name2\":{\"description\":\"The secondary name of a component\",\"value\":\"$printer_health_name2$\"},\"--name3\":{\"description\":\"The teritary name of a component\",\"value\":\"$printer_health_name3$\"},\"--negate\":{\"description\":\"The parameter allows you to map exit levels, such as warning=critical\",\"value\":\"$printer_health_negate$\"},\"--offline\":{\"description\":\"The maximum number of seconds since the last update of cache file before it is considered too old\",\"value\":\"$printer_health_offline$\"},\"--oids\":{\"description\":\"A list of oids which are downloaded and written to a cache file. Use it together with --mode oidcache\",\"value\":\"$printer_health_oids$\"},\"--port\":{\"description\":\"The SNMP port to use (default: 161)\",\"value\":\"$printer_health_port$\"},\"--privpassword\":{\"description\":\"The password for authPriv security level\",\"value\":\"$printer_health_privpassword$\"},\"--privprotocol\":{\"description\":\"The private protocol for SNMPv3 (des|aes|aes128|3des|3desde)\",\"value\":\"$printer_health_privprotocol$\"},\"--protocol\":{\"description\":\"The SNMP protocol to use (default: 2c, other possibilities: 1,3)\",\"value\":\"$printer_health_protocol$\"},\"--regexp\":{\"description\":\"A flag indicating that --name is a regular expression\",\"set_if\":\"$printer_health_regexp$\"},\"--report\":{\"description\":\"Can be used to shorten the output.\",\"value\":\"$printer_health_report$\"},\"--selectedperfdata\":{\"description\":\"The parameter allows you to limit the list of performance data. It\'s a perl regexp. Only matching perfdata show up in the output.\",\"value\":\"$printer_health_selectedperfdata$\"},\"--servertype\":{\"description\":\"The type of the network device: cisco (default). Use it if auto-detection is not possible\",\"value\":\"$printer_health_servertype$\"},\"--statefilesdir\":{\"description\":\"An alternate directory where the plugin can save files\",\"value\":\"$printer_health_statefilesdir$\"},\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 15)\",\"value\":\"$printer_health_timeout$\"},\"--units\":{\"description\":\"One of %, B, KB, MB, GB, Bit, KBi, MBi, GBi. (used for e.g. mode interface-usage)\",\"value\":\"$printer_health_units$\"},\"--username\":{\"description\":\"The securityName for the USM security model (SNMPv3 only)\",\"value\":\"$printer_health_username$\"},\"--warning\":{\"description\":\"The warning threshold\",\"value\":\"$printer_health_warning$\"},\"--warningx\":{\"description\":\"The extended warning thresholds\",\"value\":\"$printer_health_warningx$\"},\"--with-mymodules-dyn-dir\":{\"description\":\"A directory where own extensions can be found\",\"value\":\"$printer_health_mymodules-dyn-dir$\"}},\"command\":\"check_printer_health\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"printer_health\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"printer_health_hostname\":\"$check_address$\",\"printer_health_mode\":\"supplies-status\"}}', 'yalh', '2026-09-03 00:36:06', 0x231fb607a5d010210ef93f3b3bc474201f324eb0, 0xeda316153dabe87aac5009b30b47cb3fac1fec60);
