(223, 'icinga_command', 'vmware-esx-soap-host-volumes', 'create', NULL, '{\"arguments\":{\"--alertonly\":{\"description\":\"List only alerting volumes.\",\"set_if\":\"$vmware_alertonly$\"},\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--critical\":\"$vmware_crit$\",\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"required\":false,\"value\":\"$vmware_datacenter$\"},\"--exclude\":\"$vmware_exclude$\",\"--gigabyte\":{\"description\":\"Output in GB instead of MB.\",\"set_if\":\"$vmware_gigabyte$\"},\"--host\":{\"description\":\"ESX or ESXi hostname.\",\"required\":true,\"value\":\"$vmware_host$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--include\":\"$vmware_include$\",\"--isregexp\":{\"set_if\":\"$vmware_isregexp$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"volumes\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--spaceleft\":{\"set_if\":\"$vmware_spaceleft$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--subselect\":\"$vmware_subselect$\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--usedspace\":{\"description\":\"Output used space instead of free.\",\"set_if\":\"$vmware_usedspace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"},\"--warning\":\"$vmware_warn$\"},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-soap-host-volumes\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_alertonly\":false,\"vmware_auth_nosession\":false,\"vmware_crit\":\"90%\",\"vmware_host\":\"$address$\",\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\",\"vmware_usedspace\":true,\"vmware_warn\":\"80%\"}}', 'yalh', '2026-09-03 00:36:06', 0xffb80781c15a6853071f94edcf61e70f3b1310d9, 0x231fb607a5d010210ef93f3b3bc474201f324eb0),
(224, 'icinga_command', 'procs', 'create', NULL, '{\"arguments\":{\"--ereg-argument-array\":{\"description\":\"Only scan for processes with args that contain the regex STRING\",\"value\":\"$procs_argument_regex$\"},\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$procs_extra_opts$\"},\"-C\":{\"description\":\"Only scan for exact matches of COMMAND (without path)\",\"value\":\"$procs_command$\"},\"-P\":{\"description\":\"Only scan for processes with PCPU higher than indicated\",\"value\":\"$procs_pcpu$\"},\"-T\":{\"description\":\"Filter own process the traditional way by PID instead of \\/proc\\/pid\\/exe\",\"set_if\":\"$procs_traditional$\"},\"-X\":{\"description\":\"Exclude processes which match this comma separated list\",\"value\":\"$procs_exclude_process$\"},\"-a\":{\"description\":\"Only scan for processes with args that contain STRING\",\"value\":\"$procs_argument$\"},\"-c\":{\"description\":\"Generate critical state if metric is outside this range\",\"value\":\"$procs_critical$\"},\"-k\":{\"description\":\"Only scan for non kernel threads\",\"set_if\":\"$procs_nokthreads$\"},\"-m\":{\"description\":\"Check thresholds against metric\",\"value\":\"$procs_metric$\"},\"-p\":{\"description\":\"Only scan for children of the parent process ID indicated\",\"value\":\"$procs_ppid$\"},\"-r\":{\"description\":\"Only scan for processes with RSS higher than indicated\",\"value\":\"$procs_rss$\"},\"-s\":{\"description\":\"Only scan for processes that have one or more of the status flags you specify\",\"value\":\"$procs_state$\"},\"-t\":{\"description\":\"Seconds before plugin times out\",\"value\":\"$procs_timeout$\"},\"-u\":{\"description\":\"Only scan for processes with user name or ID indicated\",\"value\":\"$procs_user$\"},\"-w\":{\"description\":\"Generate warning state if metric is outside this range\",\"value\":\"$procs_warning$\"},\"-z\":{\"description\":\"Only scan for processes with VSZ higher than indicated\",\"value\":\"$procs_vsz$\"}},\"command\":\"check_procs\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"procs\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"procs_critical\":400,\"procs_nokthreads\":false,\"procs_traditional\":false,\"procs_warning\":250}}', 'yalh', '2026-09-03 00:36:06', 0x27f9a0ed67515a509d6af8e11f866e6001176dd5, 0xffb80781c15a6853071f94edcf61e70f3b1310d9),
