(227, 'icinga_command', 'proxysql', 'create', NULL, '{\"arguments\":{\"--critical\":{\"description\":\"Critical threshold\",\"value\":\"$proxysql_critical$\"},\"--defaults-file\":{\"description\":\"ProxySQL defaults file\",\"value\":\"$proxysql_defaultfile$\"},\"--host\":{\"description\":\"ProxySQL hostname \\/ IP (default=127.0.0.1)\",\"value\":\"$proxysql_host$\"},\"--ignore-hostgroup\":{\"description\":\"ProxySQL hostgroup(s) to ignore (only applies to \'--type hg\' checks, accepts comma-separated list)\",\"value\":\"$proxysql_ignore_hostgroup$\"},\"--include-hostgroup\":{\"description\":\"ProxySQL hostgroup(s) to include (only applies to \'--type hg\' checks, accepts comma-separated list)\",\"value\":\"$proxysql_include_hostgroup$\"},\"--lower\":{\"description\":\"Alert if ProxySQL value are LOWER than defined WARN \\/ CRIT thresholds (only applies to \'var\' check type)\",\"value\":\"$proxysql_lower$\"},\"--name\":{\"description\":\"ProxySQL variable name to check\",\"value\":\"$proxysql_name$\"},\"--password\":{\"description\":\"ProxySQL admin password (default=admin)\",\"value\":\"$proxysql_password$\"},\"--port\":{\"description\":\"ProxySQL admin port (default=6032)\",\"value\":\"$proxysql_port$\"},\"--runtime\":{\"description\":\"Force ProxySQL Nagios check to query the runtime_mysql_XXX tables rather than the mysql_XXX tables\",\"value\":\"$proxysql_runtime$\"},\"--type\":{\"description\":\"ProxySQL check type (one of conns,hg,rules,status,var)\",\"required\":true,\"value\":\"$proxysql_type$\"},\"--user\":{\"description\":\"ProxySQL admin username (default=admin)\",\"value\":\"$proxysql_user$\"},\"--warning\":{\"description\":\"Warning threshold\",\"value\":\"$proxysql_warning$\"}},\"command\":\"check_proxysql\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"proxysql\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:36:07', 0xffce77dccf555ad989fe7218448ca80d8f72d8e1, 0x461006fd2b555229c12c1f89efcfaf12ff80ccb8),
