(229, 'icinga_command', 'radius', 'create', NULL, '{\"arguments\":{\"--extra-opts\":{\"description\":\"Read extra plugin options from an ini file.\",\"value\":\"$radius_extra_opts$\"},\"-F\":{\"description\":\"Configuration file\",\"value\":\"$radius_config_file$\"},\"-H\":{\"description\":\"Host name, IP Address, or unix socket (must be an absolute path)\",\"value\":\"$radius_address$\"},\"-N\":{\"description\":\"NAS IP Address\",\"value\":\"$radius_nas_address$\"},\"-P\":{\"description\":\"Port number (default: 1645)\",\"value\":\"$radius_port$\"},\"-e\":{\"description\":\"Response string to expect from the server\",\"value\":\"$radius_expect$\"},\"-n\":{\"description\":\"NAS identifier\",\"value\":\"$radius_nas_id$\"},\"-p\":{\"description\":\"Password for authentication\",\"value\":\"$radius_password$\"},\"-r\":{\"description\":\"Number of times to retry a failed connection\",\"value\":\"$radius_retries$\"},\"-t\":{\"description\":\"Seconds before connection times out (default: 10) Optional :<timeout state> can be a state integer (0,1,2,3) or a state STRING\",\"value\":\"$radius_timeout$\"},\"-u\":{\"description\":\"The user to authenticate\",\"value\":\"$radius_username$\"}},\"command\":\"check_radius\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"radius\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"radius_address\":\"$check_address$\"}}', 'yalh', '2026-09-03 00:36:07', 0xf165b741a19270493af586d287da06d694a0391d, 0xcc1f3216ed3e435d70113e51b614dcfdaeae0666),
