(231, 'icinga_command', 'rbl', 'create', NULL, '{\"arguments\":{\"-H\":{\"description\":\"Name or IP address of SMTP server to check.\",\"value\":\"$rbl_hostname$\"},\"-c\":{\"description\":\"Number of blacklisting servers for a critical.\",\"value\":\"$rbl_critical$\"},\"-s\":{\"description\":\"List of RBL servers as an array.\",\"repeat_key\":true,\"required\":true,\"value\":\"$rbl_server$\"},\"-t\":{\"description\":\"Seconds before plugin times out (default: 15).\",\"value\":\"$rbl_timeout$\"},\"-w\":{\"description\":\"Number of blacklisting servers for a warning.\",\"value\":\"$rbl_warning$\"}},\"command\":\"check_rbl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"rbl\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"rbl_critical\":1,\"rbl_hostname\":\"$check_address$\",\"rbl_timeout\":15,\"rbl_warning\":1}}', 'yalh', '2026-09-03 00:36:07', 0x104b86c21531b4e42021272355f86134de2523d2, 0x3dcfe4b856ad04c226ca890f1536dcdcf9516ccf),
(232, 'icinga_command', 'vmware-esx-soap-vm-cpu-usage', 'create', NULL, '{\"arguments\":{\"--authfile\":{\"description\":\"Autentication file content: \\n\\t\\t\\t\\t\\t\\t\\t\\tusername=<username>  \\n\\t\\t\\t\\t\\t\\t\\t\\tpassword=<password>\",\"value\":\"$vmware_authfile$\"},\"--critical\":\"$vmware_crit$\",\"--datacenter\":{\"description\":\"Datacenter\\/Vcenter hostname.\",\"value\":\"$vmware_datacenter$\"},\"--host\":{\"description\":\"ESX or ESXi hostname.\",\"value\":\"$vmware_host$\"},\"--ignore_unknown\":{\"description\":\"Sometimes 3 (unknown) is returned from a component. But the check itself is ok. With this option the plugin will return OK (0) instead of UNKNOWN (3).\",\"set_if\":\"$vmware_ignoreunknown$\"},\"--ignore_warning\":{\"description\":\"Sometimes 2 (warning) is returned from a component. But the check itself is ok (from an operator view).\",\"set_if\":\"$vmware_ignorewarning$\"},\"--maintenance_mode_state\":{\"description\":\"Set status in case ESX host is in maintenace mode. Possible Values are: ok or OK, CRITICAL or critical or CRIT or crit, WARNING or warning or WARN or warn. Default is UNKNOWN because you do not know the real state. Values are case insensitive.\",\"value\":\"$vmware_maintenance_mode_state$\"},\"--name\":{\"description\":\"Virtual machine name.\",\"required\":true,\"value\":\"$vmware_vmname$\"},\"--nosession\":{\"description\":\"No auth session - IT SHOULD BE USED FOR TESTING PURPOSES ONLY!.\",\"set_if\":\"$vmware_nosession$\"},\"--password\":{\"description\":\"Password to use with the username.\",\"value\":\"$vmware_password$\"},\"--select\":\"cpu\",\"--sessionfile\":{\"description\":\"Vmware auth session file - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfile$\"},\"--sessionfiledir\":{\"description\":\"Vmware auth session file directory - no efect if $vmware_nosession$ var is true.\",\"value\":\"$vmware_sessionfiledir$\"},\"--sslport\":{\"description\":\"If a SSL port different from 443 is used.\",\"value\":\"$vmware_sslport$\"},\"--subselect\":\"usage\",\"--timeout\":{\"description\":\"Seconds before plugin times out (default: 90).\",\"value\":\"$vmware_timeout$\"},\"--trace\":{\"description\":\"Set verbosity level of vSphere API request\\/respond trace.\",\"set_if\":\"$vmware_trace$\"},\"--username\":{\"description\":\"Username to connect with.\",\"value\":\"$vmware_username$\"},\"--warning\":\"$vmware_warn$\"},\"command\":\"check_vmware_esx\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"vmware-esx-soap-vm-cpu-usage\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"vmware_auth_nosession\":false,\"vmware_crit\":\"90%\",\"vmware_host\":\"$address$\",\"vmware_ignorewarning\":false,\"vmware_sessionfiledir\":\"\\/var\\/spool\\/icinga2\\/tmp\",\"vmware_sslport\":\"443\",\"vmware_timeout\":\"90\",\"vmware_warn\":\"80%\"}}', 'yalh', '2026-09-03 00:36:07', 0x2736d86bd511d09bf82cae65ffa30535eb39c3b4, 0x104b86c21531b4e42021272355f86134de2523d2),
(233, 'icinga_command', 'redis', 'create', NULL, '{\"arguments\":{\"--credentials\":{\"description\":\"Credentials file to read for Redis authentication.\",\"value\":\"$redis_credentials$\"},\"--crit\":{\"description\":\"This option can only be used if redis_variables is used and number of values listed here must exactly match number of variables specified.\",\"value\":\"$redis_crit$\"},\"--database\":{\"description\":\"Optional database name (usually a number), needed for redis_query.\",\"value\":\"$redis_database$\"},\"--hitrate\":{\"description\":\"Calculates Hitrate.\",\"value\":\"$redis_hitrate$\"},\"--hostname\":{\"description\":\"Hostname or IP Address to check.\",\"value\":\"$redis_hostname$\"},\"--memory_utilization\":{\"description\":\"This calculates percent of total memory on system used by redis.\",\"value\":\"$redis_memory_utilization$\"},\"--option\":{\"description\":\"Specifiers are separated by , and must include NAME or PATTERN. See the help output of the plugin for the detailed format.\",\"repeat_key\":true,\"value\":\"$redis_option$\"},\"--password\":{\"description\":\"Password for Redis authentication. Safer alternative is to put them in a file and use redis_credentials.\",\"value\":\"$redis_password$\"},\"--perfparse\":{\"description\":\"This should only be used with variables and causes variable data not only to be printed as part of main status line but also as perfparse compatible output.\",\"set_if\":\"$redis_perfparse$\"},\"--perfvars\":{\"description\":\"This allows to list variables which values will go only into perfparse output (and not for threshold checking).\",\"value\":\"$redis_perfvars$\"},\"--port\":{\"description\":\"Port number (default: 6379).\",\"value\":\"$redis_port$\"},\"--prev_perfdata\":{\"description\":\"Previous performance data used to calculate rate of change for counter statistics variables and for proper calculation of hitrate.\",\"set_if\":\"$redis_prev_perfdata$\",\"value\":\"$service.perfdata$\"},\"--query\":{\"description\":\"Option specifies key to query and optional variable name to assign the results to after. See the help output of the plugin for the detailed format.\",\"repeat_key\":true,\"value\":\"$redis_query$\"},\"--rate_label\":{\"description\":\"Prefix or Suffix label used to create a new variable which has rate of change of another base variable.\",\"value\":\"$redis_rate_label$\"},\"--replication_delay\":{\"description\":\"Allows to set threshold on replication delay info.\",\"value\":\"$redis_replication_delay$\"},\"--response_time\":{\"description\":\"If this is used plugin will measure and output connection response time in seconds. With perfparse this would also be provided on perf variables.\",\"value\":\"$redis_response_time$\"},\"--timeout\":{\"description\":\"Allows to set timeout for execution of this plugin.\",\"value\":\"$redis_timeout$\"},\"--total_memory\":{\"description\":\"Amount of memory on a system for memory utilization calculations above.\",\"value\":\"$redis_total_memory$\"},\"--variables\":{\"description\":\"List of variables from info data to do threshold checks on.\",\"value\":\"$redis_variables$\"},\"--warn\":{\"description\":\"This option can only be used if redis_variables is used and number of values listed here must exactly match number of variables specified.\",\"value\":\"$redis_warn$\"}},\"command\":\"check_redis.pl\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"redis\",\"object_type\":\"external_object\",\"timeout\":60,\"vars\":{\"check_address\":{\"arguments\":[],\"deprecated\":false,\"name\":\"<anonymous>\",\"side_effect_free\":false,\"type\":\"Function\"},\"check_ipv4\":false,\"check_ipv6\":false,\"redis_hostname\":\"$check_address$\",\"redis_perfparse\":false,\"redis_prev_perfdata\":false}}', 'yalh', '2026-09-03 00:36:08', 0x7522525e19a1a7556a2a5e6ae55d6cd72752eb08, 0x2736d86bd511d09bf82cae65ffa30535eb39c3b4),
