(256, 'icinga_command', 'webinject', 'create', NULL, '{\"arguments\":{\"-c\":{\"description\":\"There is a configuration file named \'config.xml\' that is used to store configuration settings for your project. You can use this to specify which test case files to run and to set some constants and settings to be used by WebInject.\",\"value\":\"$webinject_config_file$\"},\"-n\":{\"description\":\"Suppresses all output to STDOUT except the results summary.\",\"set_if\":\"$webinject_no_output$\"},\"-o\":{\"description\":\"This option is followed by a directory name or a prefix to prepended to the output files. This is used to specify the location for writing output files (http.log, results.html, and results.xml). If a directory name is supplied (use either an absolute or relative path and make sure to add the trailing slash), all output files are written to this directory. If the trailing slash is ommitted, it is assumed to a prefix and this will be prepended to the output files. You may also use a combination of a directory and prefix.\",\"value\":\"$webinject_output$\"},\"-r\":{\"description\":\"This setting is used to enable output formatting that is compatible for use with specific external programs. The available values you can set this to are: nagios, mrtg, external and standard\",\"value\":\"$webinject_report_type$\"},\"-s\":{\"description\":\"key=value\",\"value\":\"$webinject_key_value$\"},\"-t\":{\"description\":\"The value [given in seconds] will be compared to the global time elapsed to run all the tests. If the tests have all been successful, but have taken more time than the \'globaltimeout\' value, a warning message is sent back to Icinga.\",\"value\":\"$webinject_timeout$\"},\"testcase_file\":{\"description\":\"When you launch WebInject in console mode, you can optionally supply an argument for a testcase file to run. It will look for this file in the directory that webinject.pl resides in. If no filename is passed from the command line, it will look in config.xml for testcasefile declarations. If no files are specified, it will look for a default file named \'testcases.xml\' in the current [webinject] directory. If none of these are found, the engine will stop and give you an error.\",\"skip_key\":true,\"value\":\"$webinject_testcase_file$\",\"order\":\"1\"}},\"command\":\"check_webinject\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"webinject\",\"object_type\":\"external_object\",\"timeout\":60}', 'yalh', '2026-09-03 00:36:12', 0x1a3ffe4f16cf9f8c72653fae3d4134deccbd1ba8, 0x0e3235a62ac4dcbcdc2d6f3d256c51e1380b7de1),
(257, 'icinga_command', 'yum', 'create', NULL, '{\"arguments\":{\"--all-updates\":{\"description\":\"Do not distinguish between security and non-security updates. This may be used if the YUM security plugin is absent.\",\"set_if\":\"$yum_all_updates$\"},\"--cache-only\":{\"description\":\"Run entirely from cache and do not update the cache.\",\"set_if\":\"$yum_cache_only$\"},\"--disablerepo\":{\"description\":\"Explicitly disables a reposity when calling YUM. Can take a comma separated list of repositories.\",\"value\":\"$yum_disablerepo$\"},\"--enablerepo\":{\"description\":\"Explicitly enables a reposity when calling YUM. Can take a comma separated list of repositories.\",\"value\":\"$yum_enablerepo$\"},\"--installroot\":{\"description\":\"Specifies another installation root directory\",\"value\":\"$yum_installroot$\"},\"--no-warn-on-lock\":{\"description\":\"Return OK instead of WARNING when YUM is locked.\",\"set_if\":\"$yum_no_warn_on_lock$\"},\"--no-warn-on-updates\":{\"description\":\"Return OK instead of WARNING even when updates are available.\",\"set_if\":\"$yum_no_warn_on_updates$\"},\"--timeout\":{\"description\":\"Sets a timeout in seconds after which the plugin will exit (defaults to 55 seconds).\",\"value\":\"$yum_timeout$\"},\"--warn-on-any-update\":{\"description\":\"Warns if there are any (non-security) package updates available.\",\"set_if\":\"$yum_warn_on_any_update$\"}},\"command\":\"check_yum\",\"methods_execute\":\"PluginCheck\",\"object_name\":\"yum\",\"object_type\":\"external_object\",\"timeout\":300,\"vars\":{\"yum_all_updates\":false,\"yum_cache_only\":false,\"yum_no_warn_on_lock\":false,\"yum_no_warn_on_updates\":false,\"yum_warn_on_any_update\":false}}', 'yalh', '2026-09-03 00:36:12', 0x90d6a3661fbf0e8ce0006a08f6520fd595a6bba1, 0x1a3ffe4f16cf9f8c72653fae3d4134deccbd1ba8),
