INSERT INTO `icinga_command_argument` (`id`, `command_id`, `argument_name`, `argument_value`, `argument_format`, `key_string`, `description`, `skip_key`, `set_if`, `set_if_format`, `sort_order`, `repeat_key`, `required`) VALUES
(1, 4, '-C', '$adaptec_controller_number$', 'string', NULL, 'Insert the controller number to be checked.', NULL, NULL, NULL, NULL, NULL, 'y'),
(2, 4, '-p', '$arcconf_path$', 'string', NULL, 'Insert the path to arcconf (e.g. /sbin/arcconf).', NULL, NULL, NULL, NULL, NULL, 'y'),
(3, 5, 'sar_perf_disk', '$sar_perf_disk$', 'string', NULL, 'Disk name for the \'disk\' profile', 'y', '/* Icinga 2 does not export DSL function bodies via API */', 'expression', NULL, NULL, NULL),
(4, 5, 'sar_perf_profile', '$sar_perf_profile$', 'string', NULL, 'Define the run profile: pagestat, cpu, memory_util, memory_stat, io_transfer, queueln_load, swap_util, swap_stat, task, kernel, disk <disk>. Can be a string or an array of multiple profiles.', 'y', NULL, NULL, NULL, 'n', 'y'),
(5, 6, '-H', '$apache_status_address$', 'string', NULL, 'name or IP address of host to check', NULL, NULL, NULL, NULL, NULL, NULL),
(6, 6, '-N', NULL, NULL, NULL, 'do not validate the SSL certificate chain', NULL, '$apache_status_no_validate$', NULL, NULL, NULL, NULL),
(7, 6, '-P', '$apache_status_password$', 'string', NULL, 'password for basic auth', NULL, NULL, NULL, NULL, NULL, NULL),
(8, 6, '-R', NULL, NULL, NULL, 'CRITICAL if socket timed out or http code >= 500', NULL, '$apache_status_unreachable$', NULL, NULL, NULL, NULL),
(9, 6, '-U', '$apache_status_username$', 'string', NULL, 'username for basic auth', NULL, NULL, NULL, NULL, NULL, NULL),
(10, 6, '-c', '$apache_status_critical$', 'string', NULL, 'number of open slots, busy workers and idle workers that will cause a CRITICAL', NULL, NULL, NULL, NULL, NULL, NULL),
(11, 6, '-p', '$apache_status_port$', 'string', NULL, 'the http port', NULL, NULL, NULL, NULL, NULL, NULL),
(12, 6, '-s', NULL, NULL, NULL, 'Whether we should use HTTPS instead of HTTP', NULL, '$apache_status_ssl$', NULL, NULL, NULL, NULL),
(13, 6, '-t', '$apache_status_timeout$', 'string', NULL, 'timeout in seconds', NULL, NULL, NULL, NULL, NULL, NULL),
(14, 6, '-u', '$apache_status_uri$', 'string', NULL, 'Specific URL to use, instead of the default \'http://<apache_status_address>/server-status\'', NULL, NULL, NULL, NULL, NULL, NULL),
(15, 6, '-w', '$apache_status_warning$', 'string', NULL, 'number of open slots, busy workers and idle workers that will cause a WARNING', NULL, NULL, NULL, NULL, NULL, NULL),
(16, 7, '--description', NULL, NULL, NULL, 'Use service description instead of name', NULL, '$service_win_description$', NULL, NULL, NULL, NULL),
(17, 7, '-s', '$service_win_service$', 'string', NULL, 'Service to check', NULL, NULL, NULL, NULL, NULL, 'y'),
(18, 7, '-w', NULL, NULL, NULL, 'Warn instead of critical when service is not running', NULL, '$service_win_warn$', NULL, NULL, NULL, NULL),
(19, 8, '--critical', '$apt_critical$', 'string', NULL, 'If the full package information of any of the upgradable packages match this REGEXP, the plugin will return CRITICAL status. Can be specified multiple times.', NULL, NULL, NULL, NULL, NULL, NULL),
(20, 8, '--dist-upgrade', NULL, NULL, NULL, 'Perform a dist-upgrade instead of normal upgrade. Like with -U OPTS can be provided to override the default options.', NULL, '/* Icinga 2 does not export DSL function bodies via API */', 'expression', NULL, NULL, NULL),
(21, 8, '--dist-upgrade=OPTS', '$apt_dist_upgrade$', 'string', NULL, 'Perform a dist-upgrade instead of normal upgrade. Like with -U OPTS can be provided to override the default options.', NULL, '/* Icinga 2 does not export DSL function bodies via API */', 'expression', NULL, NULL, NULL),
(22, 8, '--exclude', '$apt_exclude$', 'string', NULL, 'Exclude packages matching REGEXP from the list of packages that would otherwise be included. Can be specified multiple times.', NULL, NULL, NULL, NULL, NULL, NULL),
(23, 8, '--extra-opts', '$apt_extra_opts$', 'string', NULL, 'Read options from an ini file.', NULL, NULL, NULL, NULL, NULL, NULL),
(24, 8, '--include', '$apt_include$', 'string', NULL, 'Include only packages matching REGEXP. Can be specified multiple times the values will be combined together.', NULL, NULL, NULL, NULL, NULL, NULL),
(25, 8, '--list', NULL, NULL, NULL, 'List packages available for upgrade.', NULL, '$apt_list$', NULL, NULL, NULL, NULL),
(26, 8, '--only-critical', NULL, NULL, NULL, 'Only warn about critical upgrades.', NULL, '$apt_only_critical$', NULL, NULL, NULL, NULL),
(27, 8, '--timeout', '$apt_timeout$', 'string', NULL, 'Seconds before plugin times out (default: 10).', NULL, NULL, NULL, NULL, NULL, NULL),
(28, 8, '--upgrade', NULL, NULL, NULL, '[Default] Perform an upgrade. If an optional OPTS argument is provided, apt-get will be run with these command line options instead of the default.', NULL, '/* Icinga 2 does not export DSL function bodies via API */', 'expression', NULL, NULL, NULL),
(29, 8, '--upgrade=OPTS', '$apt_upgrade$', 'string', NULL, '[Default] Perform an upgrade. If an optional OPTS argument is provided, apt-get will be run with these command line options instead of the default.', NULL, '/* Icinga 2 does not export DSL function bodies via API */', 'expression', NULL, NULL, NULL),
(30, 9, '--extra-opts', '$simap_extra_opts$', 'string', NULL, 'Read extra plugin options from an ini file.', NULL, NULL, NULL, NULL, NULL, NULL),
(31, 9, '-6', NULL, NULL, NULL, 'Use IPv6 connection', NULL, '$simap_ipv6$', NULL, NULL, NULL, NULL),
(32, 9, '-4', NULL, NULL, NULL, 'Use IPv4 connection', NULL, '$simap_ipv4$', NULL, NULL, NULL, NULL),
(33, 9, '-A', NULL, NULL, NULL, 'All expect strings need to occur in server response. Default is any.', NULL, '$simap_all$', NULL, NULL, NULL, NULL),
(34, 9, '-D', '$simap_certificate_age$', 'string', NULL, 'Minimum number of days a certificate has to be valid', NULL, NULL, NULL, NULL, NULL, NULL),
(35, 9, '-E', '$simap_escape$', 'string', NULL, 'Can use \n, \r, 	 or \\ in send or quit string. Must come before send or quit option. Default: nothing added to send, \r\n added to end of quit', NULL, NULL, NULL, NULL, NULL, NULL),
(36, 9, '-H', '$simap_address$', 'string', NULL, 'Host name, IP Address, or unix socket (must be an absolute path)', NULL, NULL, NULL, NULL, NULL, NULL),
(37, 9, '-M', '$simap_mismatch$', 'string', NULL, 'Accept expected string mismatches with states ok, warn, crit (default: warn)', NULL, NULL, NULL, NULL, NULL, NULL),
(38, 9, '-S', NULL, NULL, NULL, 'Use SSL for the connection.', NULL, '$simap_ssl$', NULL, NULL, NULL, NULL),
(39, 9, '-c', '$simap_critical$', 'string', NULL, 'Response time to result in critical status (seconds)', NULL, NULL, NULL, NULL, NULL, NULL),
(40, 9, '-d', '$simap_delay$', 'string', NULL, 'Seconds to wait between sending string and polling for response', NULL, NULL, NULL, NULL, NULL, NULL),
(41, 9, '-e', '$simap_expect$', 'string', NULL, 'String to expect in server response (may be repeated)', NULL, NULL, NULL, NULL, NULL, NULL),
(42, 9, '-j', NULL, NULL, NULL, 'Hide output from TCP socket.', NULL, '$simap_jail$', NULL, NULL, NULL, NULL),
(43, 9, '-m', '$simap_maxbytes$', 'string', NULL, 'Close connection once more than this number of bytes are received', NULL, NULL, NULL, NULL, NULL, NULL),
(44, 9, '-p', '$simap_port$', 'string', NULL, 'Port number (default: none)', NULL, NULL, NULL, NULL, NULL, NULL),
(45, 9, '-q', '$simap_quit$', 'string', NULL, 'String to send server to initiate a clean close of the connection', NULL, NULL, NULL, NULL, NULL, NULL),
(46, 9, '-r', '$simap_refuse$', 'string', NULL, 'Accept TCP refusals with states ok, warn, crit (default: crit)', NULL, NULL, NULL, NULL, NULL, NULL),
(47, 9, '-s', '$simap_send$', 'string', NULL, 'String to send to the server', NULL, NULL, NULL, NULL, NULL, NULL),
(48, 9, '-t', '$simap_timeout$', 'string', NULL, 'Seconds before connection times out (default: 10)', NULL, NULL, NULL, NULL, NULL, NULL),
(49, 9, '-w', '$simap_warning$', 'string', NULL, 'Response time to result in warning status (seconds)', NULL, NULL, NULL, NULL, NULL, NULL),
(50, 10, '-C', '$breeze_community$', 'string', NULL, 'SNMPv1 community (default public)', NULL, NULL, NULL, NULL, NULL, NULL),
(51, 10, '-H', '$breeze_hostname$', 'string', NULL, 'Name or IP address of host to check', NULL, NULL, NULL, NULL, NULL, 'y'),
(52, 10, '-c', '$breeze_critical$', 'string', NULL, 'Percentage strength below which a CRITICAL status will result', NULL, NULL, NULL, NULL, NULL, 'y'),
(53, 10, '-w', '$breeze_warning$', 'string', NULL, 'Percentage strength below which a WARNING status will result', NULL, NULL, NULL, NULL, NULL, 'y'),
(54, 12, '--extra-opts', '$smart_extra_opts$', 'string', NULL, 'Read extra plugin options from an ini file.', NULL, NULL, NULL, NULL, NULL, NULL),
(55, 12, '-d', '$smart_device$', 'string', NULL, 'Name of a local hard drive to monitor', NULL, NULL, NULL, NULL, NULL, 'y'),
(56, 13, '--allocated-critical-gib', '$btrfs_acg$', 'string', NULL, 'Exit with CRITICAL status if less than the specified amount of disk space (in GiB) is unallocated', NULL, NULL, NULL, NULL, NULL, NULL),
(57, 13, '--allocated-critical-percent', '$btrfs_acp$', 'string', NULL, 'Exit with CRITICAL status if more than the specified percent of disk space is allocated', NULL, NULL, NULL, NULL, NULL, NULL),
(58, 13, '--allocated-warning-gib', '$btrfs_awg$', 'string', NULL, 'Exit with WARNING status if less than the specified amount of disk space (in GiB) is unallocated', NULL, NULL, NULL, NULL, NULL, NULL),
