(1496, 128, '--rotation', '$logfiles_rotation$', 'string', NULL, 'This is the method how log files are rotated. One of the predefined methods or a regular expression, which helps identify the rotated archives. If this key is missing, check_logfiles assumes that the log file will be simply overwritten instead of rotated.', NULL, NULL, NULL, NULL, NULL, NULL),
(1497, 128, '--rununique', NULL, NULL, NULL, 'This parameter prevents check_logfiles from starting when there’s already another instance using the same config file. (exits with UNKNOWN)', NULL, '$logfiles_run_unique$', NULL, NULL, NULL, NULL),
