(3409, 251, '-c', '$webinject_config_file$', 'string', NULL, 'There is a configuration file named \'config.xml\' that is used to store configuration settings for your project. You can use this to specify which test case files to run and to set some constants and settings to be used by WebInject.', NULL, NULL, NULL, NULL, NULL, NULL),
(3410, 251, '-n', NULL, NULL, NULL, 'Suppresses all output to STDOUT except the results summary.', NULL, '$webinject_no_output$', NULL, NULL, NULL, NULL),
(3411, 251, '-o', '$webinject_output$', 'string', NULL, 'This option is followed by a directory name or a prefix to prepended to the output files. This is used to specify the location for writing output files (http.log, results.html, and results.xml). If a directory name is supplied (use either an absolute or relative path and make sure to add the trailing slash), all output files are written to this directory. If the trailing slash is ommitted, it is assumed to a prefix and this will be prepended to the output files. You may also use a combination of a directory and prefix.', NULL, NULL, NULL, NULL, NULL, NULL),
(3412, 251, '-r', '$webinject_report_type$', 'string', NULL, 'This setting is used to enable output formatting that is compatible for use with specific external programs. The available values you can set this to are: nagios, mrtg, external and standard', NULL, NULL, NULL, NULL, NULL, NULL),
(3413, 251, '-s', '$webinject_key_value$', 'string', NULL, 'key=value', NULL, NULL, NULL, NULL, NULL, NULL),
(3414, 251, '-t', '$webinject_timeout$', 'string', NULL, 'The value [given in seconds] will be compared to the global time elapsed to run all the tests. If the tests have all been successful, but have taken more time than the \'globaltimeout\' value, a warning message is sent back to Icinga.', NULL, NULL, NULL, NULL, NULL, NULL),
(3415, 251, 'testcase_file', '$webinject_testcase_file$', 'string', NULL, 'When you launch WebInject in console mode, you can optionally supply an argument for a testcase file to run. It will look for this file in the directory that webinject.pl resides in. If no filename is passed from the command line, it will look in config.xml for testcasefile declarations. If no files are specified, it will look for a default file named \'testcases.xml\' in the current [webinject] directory. If none of these are found, the engine will stop and give you an error.', 'y', NULL, NULL, 1, NULL, NULL),
(3416, 252, '--all-updates', NULL, NULL, NULL, 'Do not distinguish between security and non-security updates. This may be used if the YUM security plugin is absent.', NULL, '$yum_all_updates$', NULL, NULL, NULL, NULL),
(3417, 252, '--cache-only', NULL, NULL, NULL, 'Run entirely from cache and do not update the cache.', NULL, '$yum_cache_only$', NULL, NULL, NULL, NULL),
(3418, 252, '--disablerepo', '$yum_disablerepo$', 'string', NULL, 'Explicitly disables a reposity when calling YUM. Can take a comma separated list of repositories.', NULL, NULL, NULL, NULL, NULL, NULL),
(3419, 252, '--enablerepo', '$yum_enablerepo$', 'string', NULL, 'Explicitly enables a reposity when calling YUM. Can take a comma separated list of repositories.', NULL, NULL, NULL, NULL, NULL, NULL),
(3420, 252, '--installroot', '$yum_installroot$', 'string', NULL, 'Specifies another installation root directory', NULL, NULL, NULL, NULL, NULL, NULL),
(3421, 252, '--no-warn-on-lock', NULL, NULL, NULL, 'Return OK instead of WARNING when YUM is locked.', NULL, '$yum_no_warn_on_lock$', NULL, NULL, NULL, NULL),
(3422, 252, '--no-warn-on-updates', NULL, NULL, NULL, 'Return OK instead of WARNING even when updates are available.', NULL, '$yum_no_warn_on_updates$', NULL, NULL, NULL, NULL),
